window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0210", [{"word":"networking","ipa_uk":"/ˈnetwɜːkɪŋ/","ipa_us":"/ˈnetwɜːrkɪŋ/","definition_zh":"职业人脉的拓展与维系；计算机网络组网；联网与互联","definition_en":"the activity of building and keeping relationships with other people, or the technical work of linking computers into a network","core_image":"会议室里，几个人交换名片后又各自引荐朋友，人与人的关系像线一样一条条接上，越接越密","scene":"招聘会大厅里，一位求职者主动与几家企业代表交谈，交换名片并记下联系方式。Good networking turns strangers into useful contacts.","sceneCN":"这里指主动与人交往、建立并维护职业关系网（第 1 个义项：职业人脉的拓展与维系）；句意：良好的人脉经营能把陌生人变成有用的联系人。","pos":[{"tag":"n.","zh":"人脉拓展；组网；联网"}],"collocations":[{"phrase":"business networking","zh":"商务人脉拓展"},{"phrase":"networking event","zh":"人脉交流活动"},{"phrase":"social networking","zh":"社交网络活动"},{"phrase":"computer networking","zh":"计算机网络组网"},{"phrase":"networking skills","zh":"社交与联络能力"},{"phrase":"networking cable","zh":"网络连接线缆"}],"forms":[{"label":"名词（不可数）","form":"networking"},{"label":"动词原形","form":"network"},{"label":"现在分词","form":"networking"},{"label":"过去式","form":"networked"},{"label":"过去分词","form":"networked"},{"label":"施动名词","form":"networker"}],"derivatives":[{"word":"network","pos":"n./v.","zh":"由表示「网」的名词与表示「劳作」的名词复合，义为「网络；建立网络」"},{"word":"networked","pos":"adj.","zh":"由「建立网络」的动词加表示已然的词尾构成，义为「已联网的」"},{"word":"networker","pos":"n.","zh":"由该动词加表示施动者的词尾构成，义为「善于经营人脉的人」"},{"word":"net","pos":"n.","zh":"古英语中表示「网」的名词，是复合词的前半部分"},{"word":"work","pos":"n.","zh":"古英语中表示「劳作、工作」的名词，是复合词的后半部分"}],"senses":[{"no":"01","title":"Building a circle of useful contacts","titleCN":"经营有用的联系人圈子","definition":"the activity of meeting people and keeping in touch so that they can help one another in work","definitionCN":"主动结识他人并保持联络，使彼此在工作中互帮互助的活动","example":"She spent the evening networking with investors and engineers.","exampleCN":"她整晚都在与投资人和工程师们建立联系。","why":"The action ending turns the noun for a linked group into the activity of making such links, and the links are people rather than wires.","whyCN":"表示动作的词尾把「相互连接的群体」这一名词变成「建立这种连接」的活动，而这里被连接的是人而不是线缆。"},{"no":"02","title":"Linking computers into a system","titleCN":"把计算机连成网络","definition":"the technical work of connecting computers and devices so that they can exchange data","definitionCN":"把计算机与设备连接起来、使它们能够交换数据的技术工作","example":"Computer networking is the first course in the department.","exampleCN":"计算机网络组网是该系的第一门课程。","why":"The same ending applies to machines: the noun names the work of building a network of linked devices.","whyCN":"同一个词尾也用于机器：这个名词指把设备连成一个网络的工作。"},{"no":"03","title":"The state of being linked","titleCN":"处于已联网的状态","definition":"the condition in which separate machines or people are already connected and can reach one another","definitionCN":"彼此分离的机器或人已经接通、能够相互访问的状态","example":"Good networking keeps every office in touch with the head office.","exampleCN":"良好的联网让每个办公室都能与总部保持联络。","why":"Once the links exist, the noun can name the resulting condition rather than the work that created it.","whyCN":"连接一旦存在，这个名词就可以指由此形成的状态，而不只是创建它的工作。"},{"no":"04","title":"Cooperation between organizations","titleCN":"机构之间的协作联结","definition":"the forming of working relationships between organizations that share information or resources","definitionCN":"彼此共享信息或资源的机构之间建立工作关系","example":"Networking between the two hospitals shortened the waiting list.","exampleCN":"两家医院之间的协作联结缩短了等候名单。","why":"The people being linked can also be institutions, so the word extends from personal contacts to organized cooperation.","whyCN":"被连接的对象也可以是机构，因此这个词从个人交往扩展到有组织的合作。"},{"no":"05","title":"Keeping a relationship alive","titleCN":"持续维系关系","definition":"the ongoing effort to stay in contact with people already known rather than only meeting new ones","definitionCN":"与已经认识的人保持联系、而不只是结识新人的持续努力","example":"Networking is mostly follow-up, not the first handshake.","exampleCN":"人脉经营多半靠后续跟进，而不是第一次握手。","why":"The action ending marks an ongoing process, so the word covers maintenance as much as first contact.","whyCN":"表示动作的词尾标记一个持续过程，因此这个词既指初次接触，也指关系维护。"},{"no":"06","title":"Interacting on social platforms","titleCN":"在社交平台上互动","definition":"the use of online platforms to build and maintain contacts","definitionCN":"借助在线平台建立并维持联系人关系","example":"Social networking moved most of her contacts online.","exampleCN":"社交平台活动把她的大部分联系人转到了线上。","why":"When the links run through websites, the same activity is named after its medium, giving the phrase social networking.","whyCN":"当连接通过网站进行时，同一活动便以其媒介命名，于是有了「社交网络活动」这一说法。"},{"no":"07","title":"Shared broadcasting across stations","titleCN":"多家台站联播","definition":"the arrangement in which several stations carry the same programme at the same time","definitionCN":"多家台站在同一时间播出同一节目的安排","example":"The three stations are networking the evening news.","exampleCN":"这三家台站正在联播晚间新闻。","why":"A broadcasting network is a set of linked stations, so its action ending name means putting a programme across that set.","whyCN":"广播网络就是一组相互连接的台站，因此加动作词尾后指把节目送到这组台站上。"},{"no":"08","title":"Forming a mesh-like structure","titleCN":"结成网状结构","definition":"the forming of a structure whose parts cross and connect like the threads of a net","definitionCN":"各部分交叉相接、形似网线的结构的形成","example":"The roots are networking through the soil in every direction.","exampleCN":"根系正朝各个方向在土壤中结网延伸。","why":"The oldest sense of network is a mesh of cords, so the ending can still describe the making of any net-like pattern.","whyCN":"网络最古老的意义就是绳线结成的网，因此这个词尾仍能描述任何网状图案的形成。"}],"etymology":{"intro":{"en":"Networking joins two Old English nouns, net and work, and adds the action ending -ing; the modern senses grew from a literal mesh to linked people and machines.","cn":"这个词由两个古英语名词「网」与「劳作」复合，再加表示动作的词尾构成；现代各义项从字面的网扩展到相互连接的人与机器。"},"items":[{"era":"OLD ENGLISH NET","en":"Net named a mesh of cords used for catching or carrying, and the word has stayed in English for more than a thousand years.","cn":"「网」原指用绳索编成、用于捕捉或承载的网状物，这个词在英语中已存续一千多年。"},{"era":"OLD ENGLISH WEORC","en":"Work meant labour or a piece of work, and it still supplies the second half of many compounds.","cn":"「劳作」原指劳动或一件工作，至今仍是许多复合词的后半部分。"},{"era":"SIXTEENTH CENTURY COMPOUND","en":"Network first appears as a noun for a net-like arrangement of threads or pipes, keeping the literal picture of interwoven parts.","cn":"复合词最初指绳线或管道交织成的网状结构，保留了「相互编织」的字面画面。"},{"era":"NINETEENTH CENTURY EXTENSION","en":"Railways, telegraph lines and social groups were all called networks because their parts were linked like a mesh.","cn":"铁路、电报线路与社交群体都被称为网络，因为它们的组成部分像网一样相互连接。"},{"era":"TWENTIETH CENTURY COMPUTING","en":"As computers were joined into networks, the action ending produced networking for both the engineering work and the human activity of making contacts.","cn":"随着计算机被连成网络，表示动作的词尾造出了这个词，既指工程上的组网工作，也指人建立联系的活动。"},{"era":"FIRST RECORD UNCERTAIN","en":"The compound is transparent, yet the first recorded date of the career sense is only approximate; the pre-Germanic root of net remains a proposal rather than an established form.","cn":"复合词的构词清楚，但职业人脉义项的首见年代只是约数；「网」在日耳曼语之前的词根仍只是假说，并未确证。"}]},"similar":{"note":{"en":"The first group shares the net stem; the second group names neighbouring ways of linking people or systems.","cn":"第一组共享「网」这一词干；第二组是连接人或系统的相邻说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"network","ipa":"/ˈnetwɜːk/","tag":"base noun","definition":"The linked group itself; networking is the activity of building or using it.","definitionCN":"指相互连接的那个群体本身；而目标词指建立或使用它的活动。"},{"word":"networked","ipa":"/ˈnetwɜːkt/","tag":"result adjective","definition":"Already connected into a network; it describes the result rather than the work.","definitionCN":"已经接入网络的；描述结果而不是过程。"},{"word":"networker","ipa":"/ˈnetwɜːkə/","tag":"person noun","definition":"A person who is skilled at meeting people and keeping useful contacts.","definitionCN":"擅长结识他人并维持有用联系人的人。"},{"word":"net","ipa":"/net/","tag":"short noun","definition":"The mesh or the network itself, a clipped and informal word.","definitionCN":"指网或网络本身，是简短而口语化的说法。"}]},{"heading":"NEAR MEANING","entries":[{"word":"interconnect","ipa":"/ˌɪntəkəˈnekt/","tag":"verb","definition":"To link systems to each other; it stresses the technical link between networks rather than social contact.","definitionCN":"把系统彼此连接；强调网络之间的技术连接，而非人际交往。"},{"word":"liaison","ipa":"/liˈeɪzən/","tag":"noun","definition":"A working relationship between groups; it stresses coordination rather than personal contacts.","definitionCN":"团体之间的工作关系；强调协调配合，而非私人交往。"},{"word":"collaboration","ipa":"/kəˌlæbəˈreɪʃən/","tag":"noun","definition":"Joint work toward a shared aim; broader than networking, which only builds the links.","definitionCN":"为共同目标而合作；比目标词更宽，目标词只负责建立连接。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real fixed terms, not invented rhymes.","cn":"正常联想：真实的构词成分与真实固定搭配，而不是编造的顺口溜。"},"normal":[{"en":"Net plus work: the word literally says working on a net of links.","cn":"「网」加「工作」：字面就是在一张关系网上做功课。"},{"en":"The family runs network, networked, networker and networking.","cn":"同族词包括网络、已联网的、善经营人脉者与目标词本身。"},{"en":"Fixed phrases mark the social side: networking event, business networking, networking skills.","cn":"固定搭配标出社交一面：人脉活动、商务人脉拓展、社交联络能力。"},{"en":"Fixed phrases mark the technical side: computer networking, networking cable.","cn":"固定搭配标出技术一面：计算机网络组网、网络连接线缆。"},{"en":"A mesh of cords is the oldest picture: threads crossing and holding one another.","cn":"绳线结成的网是最古老的画面：线相互交叉又相互固定。"}],"abstract":[{"en":"Picture a spider web in which every strand also carries a name card.","cn":"想象一张蛛网，每根丝上都挂着一张名片。"},{"en":"Picture a rope bridge whose every plank is held by two separate knots.","cn":"想象一座绳桥，每块木板都由两个独立的结固定。"},{"en":"Picture a choir where each singer knows two others by name and can reach them in a word.","cn":"想象一个合唱队，每位成员都认识另外两位并能一句话找到他们。"}]},"examples":[{"en":"Good networking often begins with a genuine question rather than a sales pitch.","cn":"良好的人脉经营往往从一个真诚的问题开始，而不是推销话术。"},{"en":"The lab offers a course in networking for second-year students.","cn":"实验室为二年级学生开设了一门组网课程。"},{"en":"After the conference she kept networking by email every month.","cn":"会议之后她每月都用邮件继续维系人脉。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「网」加「工作」——在网上做功课，既组网也经营人脉","word":"networking"},"root":"英语「网」与「劳作」复合，再加表示动作的名词词尾；更早的日耳曼语来源存疑。","sensesIntro":{"en":"Eight senses follow one gesture: parts get linked. The parts may be people, computers, organizations, broadcast stations or the threads of a mesh.","cn":"八个义项围绕同一个动作：把部分连接起来。这些部分可以是人、计算机、机构、广播台站，也可以是网线的股股丝线。"},"semanticMap":{"core":{"en":"CORE IMAGE: threads crossing and holding one another, then people and machines linked in the same pattern.","cn":"核心意象：丝线相互交叉、彼此固定，随后人与机器以同样的方式被连接起来。"},"chain":["MESH OF CORDS","WORK OF LINKING","PEOPLE IN CONTACT","MACHINES LINKED","SHARED SIGNAL","WIDER SYSTEM"],"branches":[{"senses":"01","en":"THE SOCIAL CORE: meeting people and keeping contact, which is the sense most learners meet first.","cn":"社交核心：结识他人并保持联系，这是学习者最先遇到的义项。"},{"senses":"02","en":"THE MACHINE CORE: linking computers and devices so data can travel between them.","cn":"机器核心：把计算机与设备连起来，让数据能在其间传输。"},{"senses":"03 · 04","en":"WHAT THE LINKS PRODUCE: a connected condition for offices, and organized cooperation between institutions.","cn":"连接带来的结果：办公室处于联网状态，机构之间形成有组织的合作。"},{"senses":"05 · 06","en":"HOW THE LINKS ARE KEPT: steady follow-up, and the online platforms that now carry most of it.","cn":"连接如何维持：持续的跟进，以及如今承载大部分联络的在线平台。"},{"senses":"07 · 08","en":"THE PATTERN ITSELF: stations sharing one programme, and any structure that spreads like a net.","cn":"图案本身：台站共享同一节目，以及任何像网一样铺开的结构。"}]},"affixes":{"intro":{"en":"Networking is an English compound with a productive action ending; its parts are native English rather than Latin.","cn":"这个词是英语复合词，带一个能产的表示动作的词尾；各部分来自英语本族语，而非拉丁语。"},"latinIntro":{"en":"No Latin root stands behind this compound, so the Latin entry list is empty.","cn":"这个复合词背后没有拉丁词根，因此拉丁词条列表留空。"},"items":[{"word":"net","structure":"Old English noun for a mesh of cords","meaning":"a net; a mesh","meaningCN":"网；网状物","example":"The first half of the compound is the old noun for a net.","exampleCN":"复合词的前半是表示「网」的古名词。"},{"word":"work","structure":"Old English noun for labour","meaning":"work; labour","meaningCN":"工作；劳作","example":"The second half names the activity done on the net.","exampleCN":"后半指在这张网上进行的活动。"},{"word":"network","structure":"net plus work","meaning":"a linked group or system","meaningCN":"相互连接的群体或系统","example":"The linked group itself is a network.","exampleCN":"相互连接的群体本身就叫网络。"},{"word":"-ing","structure":"action noun ending","meaning":"the doing of something","meaningCN":"做某事的过程","example":"The ending turns the linked group into the work of linking.","exampleCN":"这个词尾把「连接的群体」变成「建立连接」的工作。"},{"word":"networking","structure":"network plus the action ending","meaning":"the activity of building links","meaningCN":"建立连接的活动","example":"Networking is the name of that activity.","exampleCN":"目标词就是这种活动的名称。"},{"word":"-ed","structure":"completed-state ending","meaning":"already provided with something","meaningCN":"已经具备某物的","example":"A networked office already has its links in place.","exampleCN":"已联网的办公室已经把连接建好了。"},{"word":"-er","structure":"agent noun ending","meaning":"a person who does the action","meaningCN":"做该动作的人","example":"A networker is a person who builds contacts.","exampleCN":"善经营人脉者就是建立联系人的人。"},{"word":"networked","structure":"network plus the completed-state ending","meaning":"connected into a network","meaningCN":"已接入网络的","example":"The networked devices share one address space.","exampleCN":"已联网的设备共享同一个地址空间。"}],"latinEntries":[],"derivatives":[{"word":"network","pos":"n./v.","zh":"由「网」与「劳作」复合而成，义为「网络；建立网络」"},{"word":"networked","pos":"adj.","zh":"由「建立网络」的动词加已然词尾构成，义为「已联网的」"},{"word":"networker","pos":"n.","zh":"由该动词加施动词尾构成，义为「善于经营人脉的人」"},{"word":"net","pos":"n.","zh":"复合词前半，古英语表示「网」的名词"}]}},{"word":"internet","ipa_uk":"/ˈɪntənet/","ipa_us":"/ˈɪntərnet/","definition_zh":"互联网；因特网；网络接入与线上世界","definition_en":"the worldwide system of interconnected computer networks that uses common protocols to carry data","core_image":"地球表面密布着无数台计算机与海底光缆，数据包沿着这些线路在洲际之间一跳一跳地前进","scene":"深夜的书房里，学生戴上耳机，屏幕上来自另一座城市的课程视频几乎立刻加载完成。The internet carries the lecture across continents in seconds.","sceneCN":"这里指把全球计算机网络连成一体、承载数据传输的系统（第 1 个义项：全球互联网）；句意：互联网在几秒内把这堂课传过多个大洲。","pos":[{"tag":"n.","zh":"互联网；因特网；网络接入"}],"collocations":[{"phrase":"internet access","zh":"互联网接入"},{"phrase":"internet connection","zh":"网络连接"},{"phrase":"internet service","zh":"互联网服务"},{"phrase":"internet traffic","zh":"网络流量"},{"phrase":"internet user","zh":"互联网用户"},{"phrase":"internet address","zh":"网络地址"}],"forms":[{"label":"名词","form":"internet"},{"label":"加定冠词形式","form":"the internet"},{"label":"形容词用法","form":"internet"},{"label":"复合词形式","form":"internet-based"}],"derivatives":[{"word":"internet-based","pos":"adj.","zh":"由该名词加表示「以……为基础」的形容词成分构成，义为「基于互联网的」"},{"word":"internet-enabled","pos":"adj.","zh":"由该名词加表示「使能够」的已完成词尾构成，义为「具备联网功能的」"},{"word":"intranet","pos":"n.","zh":"由表示「内部」的拉丁前缀替换首段构成，义为「机构内部网络」"},{"word":"extranet","pos":"n.","zh":"由表示「外部」的拉丁前缀替换首段构成，义为「对合作方开放的内部网络」"},{"word":"net","pos":"n.","zh":"该词后半的缩略形式，义为「网络」"}],"senses":[{"no":"01","title":"The worldwide network of networks","titleCN":"全球网络之网","definition":"the global system that joins countless local and national networks through shared protocols","definitionCN":"通过共同协议把无数地方性与国家级网络连成一体的全球系统","example":"The internet links universities on every continent.","exampleCN":"互联网把各大洲的大学连接起来。","why":"The name says what it is: a net that sits between other nets and lets them reach one another.","whyCN":"这个名字直说其本质：一张位于其他网络之间、让它们互通的网。"},{"no":"02","title":"A service you subscribe to","titleCN":"订阅的上网服务","definition":"the connection to the global network that a household or business buys from a provider","definitionCN":"家庭或企业向服务商购买、用于接入全球网络的连接服务","example":"The village finally got internet last winter.","exampleCN":"这个村子去年冬天终于通上了网络。","why":"People meet the system through a paid link, so the mass noun also names the service rather than the whole architecture.","whyCN":"人们是通过付费连接接触到这个系统的，因此这个不可数名词也指服务，而不只是整套架构。"},{"no":"03","title":"The online world people inhabit","titleCN":"人们栖居的线上世界","definition":"the space of websites, messages and communities reached through the network","definitionCN":"通过网络访问的网站、信息与社群所构成的空间","example":"She found the answer somewhere on the internet.","exampleCN":"她在网上某处找到了答案。","why":"Once access is routine, the word shifts from the machinery to the place-like experience of being online.","whyCN":"当接入成为日常，这个词便从机器设施转向「在网上」那种空间化的体验。"},{"no":"04","title":"Any interconnection of networks","titleCN":"任意多个网络的互联","definition":"the general technical condition in which separate networks are joined, often written without the capital","definitionCN":"彼此独立的网络被连接起来的一般技术状态，常以小写形式书写","example":"Two research internet links now carry the telescope data.","exampleCN":"两条研究网络互联链路现在承载着望远镜数据。","why":"Before it named one global system, the word was a plain description of interconnecting nets, and that technical sense survives.","whyCN":"在它专指一个全球系统之前，这个词只是「网络互联」的普通描述，这一技术义至今仍在。"},{"no":"05","title":"The medium that carries content","titleCN":"承载内容的媒介","definition":"the network understood as a channel through which media, trade and speech are delivered","definitionCN":"被理解为传送媒体、交易与言论的通道的网络","example":"Radio survived by moving its audience to the internet.","exampleCN":"广播通过把听众转移到互联网上而存活下来。","why":"A network that carries data can be described by what it carries, so the word also names a medium.","whyCN":"承载数据的网络可以从「承载什么」来描述，因此这个词也指一种媒介。"},{"no":"06","title":"The link itself","titleCN":"连接本身","definition":"the active connection between a device and the network, as in having or losing it","definitionCN":"设备与网络之间正在生效的连接，如「有网」或「断网」","example":"My phone lost internet halfway through the call.","exampleCN":"通话到一半时我的手机断了网。","why":"The whole system is only present to a user through a live link, so the word can name that link.","whyCN":"对用户而言，整个系统只通过一条生效的链路显现，因此这个词可以指那条链路。"},{"no":"07","title":"The industry built around it","titleCN":"围绕它形成的产业","definition":"the businesses, platforms and jobs that depend on the network","definitionCN":"依赖该网络运作的企业、平台与岗位","example":"Advertising moved most of its budget to the internet.","exampleCN":"广告业把大部分预算转向了互联网。","why":"An infrastructure with its own economy is naturally named by the same word, as in internet companies.","whyCN":"拥有自身经济形态的基础设施自然沿用同一个词来命名，如网络公司。"},{"no":"08","title":"The store of online material","titleCN":"线上资料的总和","definition":"the accumulated pages, records and data reachable through the network","definitionCN":"通过网络可以访问的网页、记录与数据的累积总和","example":"The whole archive is now on the internet.","exampleCN":"整个档案现在都放在了网上。","why":"If the network holds the material, speakers treat the medium as the store, giving this collective sense.","whyCN":"如果网络承载着这些材料，说话人就会把媒介当作仓库，于是有了这一集合义。"}],"etymology":{"intro":{"en":"Internet is a twentieth-century compound of Latin inter, meaning between, and English net, a clipping of network; the capital letter once marked a single global system.","cn":"这个词是二十世纪的复合词：拉丁语「在……之间」加英语「网络」的缩略；首字母大写曾用来标记那个唯一的全球系统。"},"items":[{"era":"LATIN INTER","en":"Inter meant between or among, and it survives in many English words for things that sit between others.","cn":"这个词缀意为「在……之间」或「在……之中」，在许多表示「位于其间」的英语词中留存。"},{"era":"ENGLISH NET","en":"Net was already a short word for a network, especially a network of computers or communications.","cn":"「网」早已是网络的简短说法，尤其指计算机或通信网络。"},{"era":"ARPANET 1969","en":"The first packet-switching network linked a handful of research sites, and similar networks soon appeared in other countries.","cn":"第一个分组交换网络连接了几个研究站点，类似网络很快在其他国家出现。"},{"era":"COINAGE AROUND 1972","en":"The compound was formed to name the linking of separate networks, and it soon became the ordinary word for the global system.","cn":"人们造出这个复合词来指独立网络的互联，它很快成为指称全球系统的普通词。"},{"era":"COMMON NOUN AND PROPER NOUN","en":"Style guides long insisted on a capital letter for the single global system and a small letter for any interconnection of networks; everyday use now blurs the two.","cn":"旧式规范坚持：指唯一的全球系统时首字母大写，指任意网络互联时小写；日常使用如今已把两者混同。"},{"era":"FIRST USE UNCERTAIN","en":"The exact first use and the identity of the coiner are not settled; the date around 1972 is generally accepted, but earlier and independent formations have been claimed.","cn":"确切的首次使用与造词者尚无定论；约 1972 年这一年代为一般接受，但更早或独立造词的用法也有人主张。"}]},"similar":{"note":{"en":"The first group shares the net idea at different scales; the second group names the online world under other aspects.","cn":"第一组是不同尺度上的「网」；第二组从其他侧面指称线上世界。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"intranet","ipa":"/ɪnˈtrənet/","tag":"inside one organization","definition":"A private network inside an organization, built with the same technology but closed to outsiders.","definitionCN":"机构内部的专用网络，技术相同但对外封闭。"},{"word":"extranet","ipa":"/ˈekstrənet/","tag":"shared with partners","definition":"A private network opened to selected outside partners, sitting between an intranet and the public network.","definitionCN":"向特定外部合作方开放的专用网络，介于内部网络与公共网络之间。"},{"word":"network","ipa":"/ˈnetwɜːk/","tag":"single system","definition":"One linked system; the internet is the network that joins many such systems.","definitionCN":"单个互联系统；而互联网是把许多这样的系统连起来的那张网。"},{"word":"interconnect","ipa":"/ˌɪntəkəˈnekt/","tag":"verb","definition":"To join networks to one another, the action behind the name.","definitionCN":"把网络彼此连接，正是名称背后的动作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cyberspace","ipa":"/ˈsaɪbəspeɪs/","tag":"place-like term","definition":"The online world imagined as a place; it stresses experience and culture rather than cables.","definitionCN":"把线上世界想象成一个场所；强调体验与文化，而非线缆。"},{"word":"web","ipa":"/web/","tag":"layer on top","definition":"The linked pages and services built on the network; it is one layer, not the whole system.","definitionCN":"建立在该网络之上的网页与服务；它只是其中一层，不是整个系统。"},{"word":"online","ipa":"/ˌɒnˈlaɪn/","tag":"state word","definition":"Being connected and active on a network; it describes a state rather than naming the system.","definitionCN":"已连接并在网络上活动；描述状态，而不是命名系统。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Latin and English pieces and real fixed phrases.","cn":"正常联想：真实的拉丁语与英语成分，以及真实固定搭配。"},"normal":[{"en":"Inter means between, so the internet is the net between nets.","cn":"「之间」加上「网」，互联网就是网与网之间的那张网。"},{"en":"The family runs internet, intranet, extranet, interconnect and internetwork.","cn":"同族词包括互联网、内部网络、外部专用网络、互联与网际网络。"},{"en":"Fixed phrases mark access: internet access, internet connection, internet service.","cn":"固定搭配标出接入：互联网接入、网络连接、互联网服务。"},{"en":"Fixed phrases mark scale: internet traffic, internet user, internet address.","cn":"固定搭配标出规模：网络流量、互联网用户、网络地址。"},{"en":"The capital letter used to say that there is only one such global system.","cn":"首字母大写过去用来表示这样的全球系统只有一个。"}],"abstract":[{"en":"Picture a city where every street ends at a station that also leads to every other city.","cn":"想象一座城市，每条街的尽头都有一个通往其他所有城市的车站。"},{"en":"Picture a library whose shelves are in many buildings but share one catalogue.","cn":"想象一座图书馆，书架分散在许多建筑里，却共用一份目录。"},{"en":"Picture a conversation in which every sentence can reach every listener at once.","cn":"想象一场对话，每句话都能同时传到每一位听众那里。"}]},"examples":[{"en":"The internet was designed to keep working even when one route failed.","cn":"互联网的设计目标是即使某条线路失效也能继续工作。"},{"en":"Many rural clinics still lack reliable internet.","cn":"许多乡村诊所仍然缺乏稳定的网络接入。"},{"en":"He taught himself the language entirely on the internet.","cn":"他完全靠在网上自学了这门语言。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「因特」近「之间」加「网」——网与网之间连成的那张网","word":"internet"},"root":"拉丁语「在……之间」加英语「网络」的缩略；约 1972 年组合成词。","sensesIntro":{"en":"Eight senses move from the global architecture to the service, the online world, the plain technical sense, the medium, the active link, the industry and the stored material.","cn":"八个义项从全球架构出发，依次落到服务、线上世界、纯技术义、媒介、生效链路、产业与所存资料。"},"semanticMap":{"core":{"en":"CORE IMAGE: many separate networks joined so that any point can reach any other point.","cn":"核心意象：许多独立网络被连接起来，使任意一点都能到达另一点。"},"chain":["NETWORKS BETWEEN NETWORKS","COMMON PROTOCOLS","DATA PACKETS TRAVEL","GLOBAL COVERAGE","ONLINE WORLD","DAILY UTILITY"],"branches":[{"senses":"01","en":"THE SYSTEM ITSELF: the global network of networks, the sense that anchors all the others.","cn":"系统本身：全球的网络之网，是支撑其余义项的锚点。"},{"senses":"02 · 06","en":"THE LINK A USER HAS: a paid service or a live connection that stands between a device and the system.","cn":"用户拥有的链路：付费服务或生效连接，位于设备与系统之间。"},{"senses":"03","en":"THE PLACE IT FEELS LIKE: the online world of sites, messages and communities.","cn":"它带来的场所感：网站、信息与社群构成的线上世界。"},{"senses":"04","en":"THE TECHNICAL READING: any joining of separate networks, written without the capital.","cn":"技术读法：任意独立网络的互联，通常小写书写。"},{"senses":"05 · 07 · 08","en":"WHAT IT CARRIES AND SUPPORTS: a medium for content, an industry around it, and a store of reachable material.","cn":"它所承载与支撑的：内容媒介、围绕它的产业，以及可访问资料的总和。"}]},"affixes":{"intro":{"en":"Internet is Latin inter plus English net; the prefix is productive, while the base is a native clipping.","cn":"这个词由拉丁语前缀「之间」加英语「网」的缩略构成；前缀能产，词基是英语本族缩略。"},"latinIntro":{"en":"The only Latin element is the prefix inter; the base net is English, so Latin cognates are listed for the prefix alone.","cn":"唯一的拉丁成分是前缀「之间」；词基「网」来自英语，因此只为前缀列出拉丁同族。"},"items":[{"word":"inter-","structure":"Latin prefix meaning between","meaning":"between; among","meaningCN":"在……之间；在……之中","example":"The prefix places the network between other networks.","exampleCN":"这个前缀把这张网放在其他网络之间。"},{"word":"net","structure":"English clipping of network","meaning":"a network","meaningCN":"网络","example":"The base is the short English word for a network.","exampleCN":"词基是英语中「网络」的简短说法。"},{"word":"internet","structure":"inter- plus net","meaning":"the network between networks","meaningCN":"网与网之间的网络","example":"The compound names the joining of separate networks.","exampleCN":"这个复合词指独立网络的互联。"},{"word":"intranet","structure":"intra- plus net","meaning":"a network inside an organization","meaningCN":"机构内部网络","example":"An intranet serves only the staff of one organization.","exampleCN":"内部网络只为一个机构的员工服务。"},{"word":"extranet","structure":"extra- plus net","meaning":"a network opened to selected outsiders","meaningCN":"对特定外部方开放的网络","example":"An extranet lets partners see part of the system.","exampleCN":"外部专用网络让合作方看到系统的一部分。"},{"word":"interconnect","structure":"inter- plus connect","meaning":"to join systems together","meaningCN":"把系统连接起来","example":"Engineers interconnect the two campus networks.","exampleCN":"工程师把两个校园网连接起来。"},{"word":"internetwork","structure":"inter- plus network","meaning":"a system of linked networks","meaningCN":"由多个网络互联而成的系统","example":"The term describes the architecture in general.","exampleCN":"这个词泛指这种互联架构。"},{"word":"internet-based","structure":"internet plus based","meaning":"running on the network","meaningCN":"在该网络上运行的","example":"An internet-based service needs no local server.","exampleCN":"基于互联网的服务不需要本地服务器。"}],"latinEntries":[{"word":"inter","structure":"Latin preposition and prefix","meaning":"between, among","meaningCN":"在……之间；在……之中"},{"word":"intra","structure":"Latin prefix","meaning":"within, inside","meaningCN":"在……之内"},{"word":"extra","structure":"Latin prefix and preposition","meaning":"outside, beyond","meaningCN":"在……之外；超出"}],"derivatives":[{"word":"intranet","pos":"n.","zh":"由表示「内部」的拉丁前缀替换首段构成，义为「机构内部网络」"},{"word":"extranet","pos":"n.","zh":"由表示「外部」的拉丁前缀替换首段构成，义为「对外部合作方开放的网络」"},{"word":"interconnect","pos":"v.","zh":"由表示「之间」的前缀加「连接」的动词构成，义为「使互联」"},{"word":"internet-based","pos":"adj.","zh":"由该名词加表示「以……为基础」的词尾构成，义为「基于互联网的」"}]}},{"word":"internet-based","ipa_uk":"/ˈɪntənet beɪst/","ipa_us":"/ˈɪntərnet beɪst/","definition_zh":"基于互联网的；依托网络运行的；网络版的","definition_en":"operating on, or delivered through, the internet rather than through local or physical means","core_image":"一间空教室里只摆着一块屏幕，不同城市的学生登录同一个页面，课程与作业都沿着网络送达","scene":"山区教学点缺少足够的教师，学生每天对着屏幕跟城里的老师上课，作业也在线提交。An internet-based course reaches pupils who cannot travel to the city.","sceneCN":"这里指依托互联网开展、以网络为运行基础的（第 1 个义项：基于互联网运行的）；句意：一门网络课程让无法进城的学生也能上课。","pos":[{"tag":"adj.","zh":"基于互联网的；网络运行的；网络版的"}],"collocations":[{"phrase":"internet-based service","zh":"基于互联网的服务"},{"phrase":"internet-based learning","zh":"网络化学习"},{"phrase":"internet-based company","zh":"网络公司"},{"phrase":"internet-based platform","zh":"网络平台"},{"phrase":"internet-based communication","zh":"网络通信"},{"phrase":"internet-based application","zh":"网络应用"}],"forms":[{"label":"原级","form":"internet-based"},{"label":"比较级（较少使用）","form":"more internet-based"},{"label":"最高级（较少使用）","form":"most internet-based"},{"label":"连字符可省略写法","form":"internet based"}],"derivatives":[{"word":"internet","pos":"n.","zh":"复合词前半，指全球互联网"},{"word":"base","pos":"n./v.","zh":"复合词后半，义为「基础；以……为基础」"},{"word":"based","pos":"adj.","zh":"由「基础」的名词加表示已然的词尾构成，义为「以……为基础的」"},{"word":"web-based","pos":"adj.","zh":"以前半换成「万维网」的同构词，义为「基于网页的」"}],"senses":[{"no":"01","title":"Running on the global network","titleCN":"在全球网络上运行","definition":"designed to work through the internet rather than on a local machine alone","definitionCN":"设计为通过互联网运行，而不是仅在本机运行","example":"The team built an internet-based tool for remote labs.","exampleCN":"团队为远程实验室开发了一个基于互联网的工具。","why":"The second half says what the thing rests on, so the compound describes a system whose ground is the network.","whyCN":"后半说明它依托什么，因此这个复合词描述一个以网络为基础的体系。"},{"no":"02","title":"Taught through the network","titleCN":"通过网络授课","definition":"describing lessons or courses delivered online instead of in a classroom","definitionCN":"指以在线方式而非课堂方式提供的课程或教学","example":"An internet-based lesson can be replayed at any hour.","exampleCN":"网络课程可以在任何时段重看。","why":"Education is one of the first fields to adopt the compound, because the network replaces the physical room.","whyCN":"教育最早采用这个复合词，因为网络替代了实体教室。"},{"no":"03","title":"Communication carried by the network","titleCN":"由网络承载的通信","definition":"describing messages, calls or meetings that travel over the network","definitionCN":"指通过网络传输的信息、通话或会议","example":"Internet-based messaging replaced most internal memos.","exampleCN":"网络通信取代了大部分内部备忘录。","why":"The compound marks the channel, so any exchange that uses that channel can take the label.","whyCN":"这个复合词标记通道，因此任何使用该通道的交流都能带上这个标签。"},{"no":"04","title":"The online edition of something","titleCN":"某物的网络版","definition":"describing a version that exists online where an offline or printed version also exists","definitionCN":"指同时存在离线版或纸质版时，放在网上的那个版本","example":"The internet-based edition updates faster than the printed one.","exampleCN":"网络版比纸质版更新得更快。","why":"When two versions exist, the compound works as a contrast label for the one that lives on the network.","whyCN":"当两个版本同时存在，这个复合词就充当对照标签，指生活在网络上的那个版本。"},{"no":"05","title":"Business that depends on the network","titleCN":"依赖网络的业务","definition":"describing trade or services whose operation would stop without the network","definitionCN":"指一旦没有网络就停止运转的交易或服务","example":"The firm is entirely internet-based and has no shopfront.","exampleCN":"这家公司完全依靠网络，没有实体店面。","why":"Commerce that cannot run offline is defined by its dependence, hence the compound as a business label.","whyCN":"无法离线经营的商业由其依赖性定义，因此这个复合词成了业务标签。"},{"no":"06","title":"Data drawn from online sources","titleCN":"取自线上来源的数据","definition":"describing information collected or supplied through the network","definitionCN":"指通过网络收集或提供的信息","example":"The survey is internet-based, so responses arrive instantly.","exampleCN":"这项调查基于网络，因此回答会立刻送达。","why":"If the source of data is the network, the whole study is described by that source.","whyCN":"如果数据来源是网络，整项研究就以这一来源来描述。"},{"no":"07","title":"Remote operation over the network","titleCN":"通过网络远程操作","definition":"describing control or access performed from another place through the network","definitionCN":"指通过互联网从另一地点进行的控制或访问","example":"The telescope is internet-based and can be steered from any campus.","exampleCN":"这台望远镜基于网络，可从任何校园操控。","why":"The network removes distance, so remote control becomes another thing that rests on it.","whyCN":"网络消除了距离，因此远程操控也成为依托它的一项事物。"},{"no":"08","title":"Research conducted online","titleCN":"在线开展的研究","definition":"describing a study whose recruitment, data or publication happens through the network","definitionCN":"指招募、数据或发表环节通过网络完成的研究","example":"Internet-based trials reach patients in remote regions.","exampleCN":"网络化试验能覆盖偏远地区的患者。","why":"Research is defined by its method, and when the method runs on the network the compound names the whole project.","whyCN":"研究由其方法定义，当方法在网络上运行时，这个复合词就命名整个项目。"}],"etymology":{"intro":{"en":"Internet-based is a transparent English compound of internet and based; only the prefix inter is Latin, and the exact first use is not recorded.","cn":"这个词是透明的英语复合词，由「互联网」与「以……为基础」构成；只有前缀「之间」来自拉丁语，确切首见年代没有记录。"},"items":[{"era":"LATIN INTER","en":"Inter supplied the between in internet; it is the only Latin piece in the compound.","cn":"拉丁语「之间」提供了「互联网」中的「之间」，也是整个复合词里唯一的拉丁成分。"},{"era":"ENGLISH BASE","en":"Base came from Latin basis through French and Greek, and English turned it into a verb meaning to found something on a support.","cn":"「基础」经法语与希腊语源自拉丁语，英语又把它变成动词，义为「以某物为支撑建立」。"},{"era":"PAST PARTICIPLE AS ADJECTIVE","en":"The completed-state ending turned the verb into an adjective, a pattern already used in web-based and paper-based.","cn":"表示已然的词尾把动词变成形容词，这一模式早已用于「基于网页的」「纸质的」等词。"},{"era":"LATE TWENTIETH CENTURY","en":"As the network spread beyond research labs, the compound became a standard way to mark anything that runs online.","cn":"当网络走出研究实验室，这个复合词就成了标记「在网上运行」的标准说法。"},{"era":"FIRST RECORD UNKNOWN","en":"The first recorded use is not established; the formation is fully transparent, but the date and the first writer are unknown, so only the pattern can be dated with confidence.","cn":"首次有记录的用法尚未确证；构词完全透明，但年代与首位使用者不明，只能确定这一构词模式的大致时期。"}]},"similar":{"note":{"en":"The first group are close compounds built on the same pattern; the second group describes online operation from other angles.","cn":"第一组是同一构词模式下的近亲复合词；第二组从其他角度描述在线运行。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"web-based","ipa":"/ˈweb beɪst/","tag":"same pattern","definition":"Built to run in a browser on the web layer; it names a narrower layer than the whole network.","definitionCN":"为在网页层上的浏览器中运行而建；所指层次比整个网络更窄。"},{"word":"internet","ipa":"/ˈɪntənet/","tag":"the base noun","definition":"The network itself; the compound adds the idea of resting on it.","definitionCN":"指网络本身；复合词则加上「依托于它」的意思。"},{"word":"internet-connected","ipa":"/ˈɪntənet kəˈnektɪd/","tag":"same pattern","definition":"Merely linked to the network; it says nothing about whether the thing runs through it.","definitionCN":"只是接入网络；并不说明该事物是否通过网络运行。"},{"word":"online","ipa":"/ˌɒnˈlaɪn/","tag":"state word","definition":"A one-word state adjective for being connected; the compound is the fuller attributive form.","definitionCN":"表示已连接的单字状态形容词；复合词是更完整的定语形式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"networked","ipa":"/ˈnetwɜːkt/","tag":"connected adjective","definition":"Joined into a network; it describes the wiring, not necessarily internet dependence.","definitionCN":"已接入网络的；描述连接状态，不一定依赖互联网。"},{"word":"remote","ipa":"/rɪˈməʊt/","tag":"distance word","definition":"Operating from a distance; the distance may be bridged by the network but is not named by the word itself.","definitionCN":"从远处操作；距离可由网络跨越，但这个词本身并不点明网络。"},{"word":"digital","ipa":"/ˈdɪdʒɪtəl/","tag":"format word","definition":"Stored or handled as numbers; a digital service may still work offline, so the word is wider.","definitionCN":"以数字形式存储或处理；数字服务仍可离线工作，因此这个词范围更宽。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real prefix, a real base and a productive adjective pattern.","cn":"正常联想：真实前缀、真实词基与能产的形容词模式。"},"normal":[{"en":"Internet plus based: the thing stands on the network as on a foundation.","cn":"「互联网」加「以……为基础」：这个事物像站在地基上一样站在网络上。"},{"en":"The same pattern gives web-based, paper-based and home-based.","cn":"同一模式还造出基于网页的、纸质的、以家为基础的等说法。"},{"en":"Fixed phrases mark services: internet-based service, platform, application.","cn":"固定搭配标出服务：基于互联网的服务、平台、应用。"},{"en":"Fixed phrases mark learning: internet-based learning and courses.","cn":"固定搭配标出教学：网络化学习与网络课程。"},{"en":"The hyphen keeps the two halves together as one modifier before a noun.","cn":"连字符把两半绑成一个整体，放在名词前作定语。"}],"abstract":[{"en":"Picture a house whose floor is a living web rather than wood.","cn":"想象一座房子，地板不是木板，而是一张活的网。"},{"en":"Picture a shop with no walls, only an address that anyone can reach.","cn":"想象一家没有墙的店，只有一个谁都能到达的地址。"},{"en":"Picture a classroom that exists only as a page everyone opens at once.","cn":"想象一间教室只以一个大家同时打开的页面形式存在。"}]},"examples":[{"en":"The hospital replaced its paper forms with an internet-based record system.","cn":"医院用网络化的病历系统取代了纸质表格。"},{"en":"Internet-based tutoring costs less than travelling to a centre.","cn":"网络辅导比赶去中心上课花费更少。"},{"en":"The survey is internet-based, which shortened the collection period.","cn":"这项调查基于网络，缩短了数据收集周期。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「互联网」+「打底」——用网络打底，一切都在网上跑","word":"internet-based"},"root":"英语「互联网」（拉丁语「之间」加英语「网」）加「基础」，再加表示已然的词尾。","sensesIntro":{"en":"Eight senses apply one pattern: the network is the ground. The grounded thing may be a tool, a course, a message, an edition, a business, data, a remote control or a study.","cn":"八个义项套用同一模式：网络是地基。立在地基上的可以是工具、课程、信息、版本、业务、数据、远程操控或一项研究。"},"semanticMap":{"core":{"en":"CORE IMAGE: something stands on the network as a house stands on its foundation.","cn":"核心意象：某物立在网络上，就像房子立在地基上。"},"chain":["A FOUNDATION","THE NETWORK AS GROUND","SOMETHING BUILT ON IT","REMOTE ACCESS","ONLINE DELIVERY","DEPENDENCE"],"branches":[{"senses":"01","en":"THE GENERAL CASE: any tool or system designed to run through the network.","cn":"一般情形：任何设计为通过网络运行的工具或系统。"},{"senses":"02 · 03","en":"DELIVERY: lessons taught online and messages that travel over the network.","cn":"交付：在线讲授的课程与通过网络传输的信息。"},{"senses":"04","en":"THE CONTRAST LABEL: the online edition set beside a printed or offline one.","cn":"对照标签：与纸质版或离线版并置的网络版。"},{"senses":"05 · 08","en":"DEPENDENCE: a business or a study that would stop without the network.","cn":"依赖：没有网络就停摆的业务或研究。"},{"senses":"06 · 07","en":"SOURCES AND HANDS: data supplied online and controls exercised from a distance.","cn":"来源与操作：线上提供的数据，以及从远处实施的操控。"}]},"affixes":{"intro":{"en":"The compound has a Latin prefix, an English clipping and a Latin-derived base, with a past-participle ending doing adjective work.","cn":"这个复合词有一个拉丁前缀、一个英语缩略词基，以及一个源自拉丁语的词基，另有一个充当形容词的过去分词词尾。"},"latinIntro":{"en":"Latin contributes inter and the ancestor of base; the net element is English, so the Latin list covers only the prefix and the base.","cn":"拉丁语贡献了「之间」与「基础」的词源；「网」这一成分来自英语，因此拉丁词条只列前缀与词基。"},"items":[{"word":"inter-","structure":"Latin prefix meaning between","meaning":"between; among","meaningCN":"在……之间；在……之中","example":"The prefix marks the network as a link between others.","exampleCN":"这个前缀把这张网标记为连接其他网络的纽带。"},{"word":"net","structure":"English clipping of network","meaning":"a network","meaningCN":"网络","example":"The middle element names the network in short form.","exampleCN":"中间成分用简短形式指网络。"},{"word":"base","structure":"Latin and Greek basis","meaning":"a foundation; to found on","meaningCN":"基础；以……为基础","example":"The base is the foundation on which the thing stands.","exampleCN":"这个词基就是事物所立的地基。"},{"word":"-ed","structure":"past-participle ending used as an adjective","meaning":"provided with; resting on","meaningCN":"具备……的；以……为依托的","example":"The ending turns the verb into a describing word.","exampleCN":"这个词尾把动词变成描述性词语。"},{"word":"internet-based","structure":"internet plus based","meaning":"resting on the network","meaningCN":"以网络为依托的","example":"The whole compound describes a thing that rests on the network.","exampleCN":"整个复合词描述以网络为依托的事物。"},{"word":"web-based","structure":"web plus based","meaning":"resting on the web layer","meaningCN":"以网页层为依托的","example":"A web-based tool runs inside a browser.","exampleCN":"基于网页的工具在浏览器里运行。"},{"word":"paper-based","structure":"paper plus based","meaning":"resting on paper records","meaningCN":"以纸质记录为依托的","example":"The older office was entirely paper-based.","exampleCN":"较早的办公室完全依赖纸质记录。"},{"word":"internet","structure":"inter- plus net","meaning":"the global network","meaningCN":"全球网络","example":"The first half is the name of the global network.","exampleCN":"前半是这一全球网络的名称。"}],"latinEntries":[{"word":"inter","structure":"Latin preposition and prefix","meaning":"between, among","meaningCN":"在……之间；在……之中"},{"word":"basis","structure":"Latin noun from Greek","meaning":"a foundation, a step","meaningCN":"基础；立足处"},{"word":"bassus","structure":"Late Latin adjective","meaning":"low, thick","meaningCN":"低的；厚的（「基础」一支的后续来源）"}],"derivatives":[{"word":"internet","pos":"n.","zh":"复合词前半，指全球互联网"},{"word":"base","pos":"n./v.","zh":"复合词后半，义为「基础；以……为基础」"},{"word":"based","pos":"adj.","zh":"由「基础」的动词加已然词尾构成，义为「以……为基础的」"},{"word":"web-based","pos":"adj.","zh":"同一构词模式，把前半换成万维网，义为「基于网页的」"}]}},{"word":"connect","ipa_uk":"/kəˈnekt/","ipa_us":"/kəˈnekt/","definition_zh":"连接；接通；使产生联系；建立沟通","definition_en":"to join two things together, or to establish a relationship or link between people or ideas","core_image":"两根电线的铜芯被剥出，一端对准端子插进去，指示灯随即由红转绿","scene":"维修工把路由器的网线插进墙上的端口，指示灯由红转绿，楼上的电脑立刻能上网。A single cable can connect the whole floor to the network.","sceneCN":"这里指把设备用线缆接上、使其进入网络（第 2 个义项：接通设备或线路）；句意：一根网线就能把整层楼接入网络。","pos":[{"tag":"v.","zh":"连接；接通；联系；使关联"}],"collocations":[{"phrase":"connect to","zh":"连接到"},{"phrase":"connect with","zh":"与……建立联系"},{"phrase":"connect the dots","zh":"把线索串起来"},{"phrase":"connect a device","zh":"连接设备"},{"phrase":"connect directly","zh":"直接连接"},{"phrase":"connect online","zh":"在线联通"}],"forms":[{"label":"动词原形","form":"connect"},{"label":"第三人称单数","form":"connects"},{"label":"过去式","form":"connected"},{"label":"过去分词","form":"connected"},{"label":"现在分词","form":"connecting"},{"label":"名词","form":"connection"}],"derivatives":[{"word":"connection","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「连接；联系」"},{"word":"connected","pos":"adj.","zh":"由该动词加已然词尾构成，义为「已连接的」"},{"word":"connector","pos":"n.","zh":"由该动词加施动者词尾构成，义为「连接器」"},{"word":"connective","pos":"adj./n.","zh":"由该动词加表示「起……作用」的词尾构成，义为「连接的；连接成分」"},{"word":"connectivity","pos":"n.","zh":"由形容词词干加表示状态的名词尾构成，义为「连通性」"}],"senses":[{"no":"01","title":"Joining two physical things","titleCN":"把两个实物接在一起","definition":"to attach one object to another so that they form a continuous whole","definitionCN":"把一个物体接到另一个上，使它们成为一个连续整体","example":"Workers connect the pipe to the tank before testing.","exampleCN":"工人在测试前把管道接到储罐上。","why":"The Latin verb meant to bind together, and the first sense is still the literal binding of two ends.","whyCN":"拉丁语原义就是「绑在一起」，第一个义项仍是两根端点的字面绑定。"},{"no":"02","title":"Bringing a device online","titleCN":"把设备接入线路或网络","definition":"to join a device to a power supply, a network or a signal source so that it works","definitionCN":"把设备接到电源、网络或信号源上，使其开始工作","example":"Connect the router before you open the settings page.","exampleCN":"打开设置页面前先把路由器接上。","why":"A device that is attached to a supply starts to work, so the physical joining is also described by its effect.","whyCN":"设备接上供给后开始工作，因此这一物理连接也用其结果来描述。"},{"no":"03","title":"Bringing people into contact","titleCN":"让人与人建立联系","definition":"to introduce people or help them reach one another","definitionCN":"介绍人们相识，或帮助他们彼此取得联系","example":"The event connect researchers who had never met.","exampleCN":"这场活动让此前从未见面的研究者建立了联系。","why":"The binding image moves from wires to people, and the verb now means putting them in touch.","whyCN":"绑缚的画面从线缆转到人身上，这个动词便指让他们取得联系。"},{"no":"04","title":"Linking ideas in the mind","titleCN":"在心里把观念联系起来","definition":"to see or establish a relation between ideas, facts or events","definitionCN":"看出或建立观念、事实与事件之间的关系","example":"Good teachers connect new material to what students already know.","exampleCN":"好老师把新内容与学生已知的东西联系起来。","why":"When two ideas are joined in thought, the same verb describes the mental link rather than a physical one.","whyCN":"当两个观念在思维中被接上，同一个动词就描述心理联系而非物理连接。"},{"no":"05","title":"Making transport times fit","titleCN":"让交通班次衔接","definition":"to arrange journeys so that a passenger can move from one vehicle to the next","definitionCN":"安排行程，使乘客能从一辆车换到下一辆","example":"The new timetable connect the train with the last ferry.","exampleCN":"新时刻表把火车与末班渡轮衔接起来。","why":"Two routes are joined in time rather than in space, and the verb covers that temporal joint.","whyCN":"两条路线是在时间上而非空间上被接上，这个动词涵盖这种时间衔接。"},{"no":"06","title":"Getting a call through","titleCN":"把电话接通","definition":"to complete a telephone link between two parties","definitionCN":"在两方之间建立电话链路","example":"The operator connect the call after a short delay.","exampleCN":"接线员稍作延迟后把电话接通了。","why":"A telephone call is literally a circuit joined end to end, so the verb is used for completing it.","whyCN":"电话呼叫本就是把电路首尾接通，因此完成通话也用这个动词。"},{"no":"07","title":"Reaching someone emotionally","titleCN":"与某人产生情感共鸣","definition":"to make someone feel understood or emotionally involved","definitionCN":"使某人感到被理解或在情感上投入","example":"Her story connect with readers of every age.","exampleCN":"她的故事打动了各个年龄的读者。","why":"When two people feel joined rather than merely introduced, the verb describes an emotional link.","whyCN":"当两人感到被连接而不只是被介绍认识，这个动词就描述情感纽带。"},{"no":"08","title":"Matching or fitting logically","titleCN":"逻辑上相合、接得上","definition":"to be consistent with something else, or to follow naturally from it","definitionCN":"与另一事物保持一致，或由它自然接续","example":"The conclusion does not connect with the evidence given.","exampleCN":"这个结论与所给证据接不上。","why":"Two statements can be joined like two ends, so the verb also judges whether they fit together.","whyCN":"两段陈述可以像两个端点一样被接上，因此这个动词也用来判断它们是否吻合。"}],"etymology":{"intro":{"en":"Connect comes from Latin connectere, a joining of con, together, and nectere, to bind; English took it through French.","cn":"这个词来自拉丁语，由「共同」与「系、绑」合成，意为「绑在一起」，经法语进入英语。"},"items":[{"era":"LATIN COM-","en":"The prefix com- meant together or with, and it is the same element behind many English words of union.","cn":"这个前缀意为「共同、一起」，也是许多表示「合一」的英语词背后的同一成分。"},{"era":"LATIN NECTERE","en":"Nectere meant to bind, tie or fasten, and it supplied the image of two ends held by one knot.","cn":"这个动词意为「系、绑、固定」，提供了「两根端点被一个结系住」的画面。"},{"era":"LATIN CONNECTERE","en":"The compound verb meant to join or fasten together, and it was used for both physical and personal ties.","cn":"这一复合动词意为「连接、系在一起」，既用于实物，也用于人际关系。"},{"era":"ENGLISH THROUGH FRENCH","en":"English adopted the verb in the fifteenth century, and it quickly covered cables, roads, arguments and people.","cn":"英语在十五世纪接受了这个动词，它很快涵盖线缆、道路、论证与人。"},{"era":"DERIVED NOUN","en":"The noun connection was formed from the same stem, naming the joint or the relationship rather than the act.","cn":"名词「连接」由同一词干构成，指接合处或关系，而不是动作本身。"},{"era":"RECONSTRUCTED ROOT","en":"The deeper origin of nectere is reconstructed as a binding root and is not attested directly, so the form is a reconstruction rather than a recorded word.","cn":"「系、绑」更早的来源被重构为一个表示绑缚的词根，并未直接见于文献，因此该形式属于重构而非有记录的词。"}]},"similar":{"note":{"en":"The first group shares the Latin binding stem; the second group names kinds of joining with different force.","cn":"第一组共享拉丁语「绑」的词干；第二组是力度不同的各种连接说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"connection","ipa":"/kəˈnekʃən/","tag":"noun","definition":"The joint or relationship produced by connecting; it names the result.","definitionCN":"连接产生的接合处或关系；指结果。"},{"word":"connected","ipa":"/kəˈnektɪd/","tag":"adjective","definition":"Already joined or in contact; it describes a state rather than an act.","definitionCN":"已经接上或已有联系的；描述状态而非动作。"},{"word":"connector","ipa":"/kəˈnektə/","tag":"device noun","definition":"The part that makes a joint possible, such as a plug or a junction.","definitionCN":"使接合得以发生的部件，如插头或接头。"},{"word":"connective","ipa":"/kəˈnektɪv/","tag":"adjective and noun","definition":"Serving to join things, or a word that joins parts of a sentence.","definitionCN":"起连接作用的，或连接句子成分的词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"link","ipa":"/lɪŋk/","tag":"verb and noun","definition":"To join or associate; it stresses the relationship between the joined parts as much as the joint.","definitionCN":"连接或关联；既强调接合，也同样强调被连接部分之间的关系。"},{"word":"attach","ipa":"/əˈtætʃ/","tag":"verb","definition":"To fasten one thing to another; it is often one-sided, with one part becoming a fixture of the other.","definitionCN":"把一物固定到另一物上；常是一侧附着，一部分成为另一部分的固定配件。"},{"word":"join","ipa":"/dʒɔɪn/","tag":"verb","definition":"To bring or come together; it is the plainest word and says nothing about the kind of link.","definitionCN":"使结合或汇合；最朴素的说法，不说明连接方式。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin pieces and the real derivative family.","cn":"正常联想：真实的拉丁成分与真实的派生词族。"},"normal":[{"en":"Con means together and nectere means bind: to connect is to bind together.","cn":"「共同」加「绑」，连接就是绑在一起。"},{"en":"The family runs connect, connection, connected, connector and connectivity.","cn":"同族词有连接、联系、已连接的、连接器与连通性。"},{"en":"Fixed phrases mark the target: connect to, connect with, connect directly.","cn":"固定搭配标出对象：连接到、与……联系、直接连接。"},{"en":"Fixed phrases mark the mental sense: connect the dots, connect ideas.","cn":"固定搭配标出心理义：把线索串起来、把观念联系起来。"},{"en":"A cable and a conversation use the same verb because both join two separated ends.","cn":"线缆与对话都用同一个动词，因为两者都是把分开的两端接上。"}],"abstract":[{"en":"Picture two islands joined by a single rope that either side can pull.","cn":"想象两座岛由一根绳子连着，哪一边都能拉。"},{"en":"Picture a sentence in which the last word of one clause hands off to the first of the next.","cn":"想象一句话里，前一分句的末词把意思交给下一分句的首词。"},{"en":"Picture two strangers whose eyes meet and who suddenly understand the same joke.","cn":"想象两个陌生人目光相遇，忽然听懂了同一个笑话。"}]},"examples":[{"en":"Connect the sensor to the board before switching on the power.","cn":"接通电源前先把传感器接到板上。"},{"en":"The bridge connects the island to the mainland.","cn":"这座桥把海岛与大陆连接起来。"},{"en":"She used one example to connect theory with practice.","cn":"她用一个例子把理论与实践联系起来。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「可耐接」——两个接口耐得住接在一起 → 连接","word":"connect"},"root":"拉丁语「共同」与「系、绑」合成的动词，意为绑在一起；更早词根为重构形式。","sensesIntro":{"en":"Eight senses all join two ends: objects, devices, people, ideas, timetables, telephone lines, feelings and arguments.","cn":"八个义项都在接上两个端点：实物、设备、人、观念、时刻表、电话线、情感与论证。"},"semanticMap":{"core":{"en":"CORE IMAGE: two separated ends tied by one knot until they act as a single line.","cn":"核心意象：两个分开的端点被同一个结系住，直到它们像一条线一样运作。"},"chain":["TWO ENDS","A KNOT","CONTINUOUS LINE","SIGNAL PASSES","CONTACT MADE","RELATION FORMED"],"branches":[{"senses":"01","en":"THE LITERAL JOINT: two physical things attached into one continuous whole.","cn":"字面接合：两个实物被接成一个连续整体。"},{"senses":"02 · 06","en":"THE LIVE LINK: a device joined to a supply, or a call joined end to end.","cn":"生效链路：设备接到供给上，或通话首尾接通。"},{"senses":"03 · 07","en":"PEOPLE JOINED: strangers introduced, and a story that reaches the feelings.","cn":"人的连接：陌生人被介绍相识，以及打动情感的故事。"},{"senses":"04","en":"IDEAS JOINED: a new fact tied to what is already known.","cn":"观念连接：新事实与已知内容被系在一起。"},{"senses":"05 · 08","en":"JOINED IN TIME AND LOGIC: timetables that fit, and conclusions that follow from evidence.","cn":"在时间与逻辑上接合：班次相互衔接，结论与证据相符。"}]},"affixes":{"intro":{"en":"Connect is a Latin verb with a living prefix and a stem that still breeds nouns and adjectives in English.","cn":"这个词是拉丁动词，带一个仍在使用的前缀，其词干在英语中仍不断生成名词与形容词。"},"latinIntro":{"en":"Latin supplies both the prefix com- and the verb nectere; the Latin noun nexus belongs to the same family, so real cognates can be listed.","cn":"拉丁语提供了前缀「共同」与动词「系、绑」；拉丁名词「纽结」同属这一族，因此可以列出真实同族词。"},"items":[{"word":"com-","structure":"Latin prefix, assimilated form of con-","meaning":"together; with","meaningCN":"共同；一起","example":"The prefix says the binding happens with another end.","exampleCN":"这个前缀说明绑缚是与另一个端点一起发生的。"},{"word":"nectere","structure":"Latin verb","meaning":"to bind, tie, fasten","meaningCN":"系；绑；固定","example":"The stem carries the picture of a knot.","exampleCN":"这个词干带着「打结」的画面。"},{"word":"connectere","structure":"com- plus nectere","meaning":"to join or fasten together","meaningCN":"连接；系在一起","example":"The Latin compound is the direct source of the English verb.","exampleCN":"这一拉丁复合动词是英语动词的直接来源。"},{"word":"connect","structure":"Latin connectere through French","meaning":"to join two things","meaningCN":"把两物接在一起","example":"The verb entered English in the fifteenth century.","exampleCN":"这个动词在十五世纪进入英语。"},{"word":"-ion","structure":"action-result noun ending","meaning":"the act or result of doing","meaningCN":"动作或其结果","example":"The ending turns the verb into the noun for a joint.","exampleCN":"这个词尾把动词变成指接合处的名词。"},{"word":"-ed","structure":"completed-state ending","meaning":"already joined","meaningCN":"已经接上的","example":"A connected device is already in the circuit.","exampleCN":"已连接的设备已经处在电路之中。"},{"word":"-or","structure":"agent noun ending","meaning":"the thing that joins","meaningCN":"起连接作用的东西","example":"A connector joins two cables.","exampleCN":"连接器把两根线缆接起来。"},{"word":"-ive","structure":"adjective ending","meaning":"having the function of","meaningCN":"具有……作用的","example":"A connective word joins two clauses.","exampleCN":"连接词把两个分句接起来。"},{"word":"nexus","structure":"Latin noun from nectere","meaning":"a binding together; a link","meaningCN":"联结；纽带","example":"The Latin noun names the bond itself.","exampleCN":"这个拉丁名词指纽带本身。"}],"latinEntries":[{"word":"nectere","structure":"Latin verb","meaning":"to bind, tie","meaningCN":"系；绑"},{"word":"nexus","structure":"Latin noun from nectere","meaning":"a binding, a link","meaningCN":"联结；纽带"},{"word":"connexio","structure":"Latin noun from connectere","meaning":"a joining together","meaningCN":"连接；接合"}],"derivatives":[{"word":"connection","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「连接；联系」"},{"word":"connected","pos":"adj.","zh":"由该动词加已然词尾构成，义为「已连接的」"},{"word":"connector","pos":"n.","zh":"由该动词加施动者词尾构成，义为「连接器」"},{"word":"connective","pos":"adj./n.","zh":"由该动词加表示功能的词尾构成，义为「连接的；连接成分」"},{"word":"connectivity","pos":"n.","zh":"由形容词词干加表示状态的名词尾构成，义为「连通性」"}]}},{"word":"connection","ipa_uk":"/kəˈnekʃn/","ipa_us":"/kəˈnekʃən/","definition_zh":"连接；联系；人脉；转乘衔接；关联","definition_en":"the state or act of being joined, or the relationship between people, things or ideas","core_image":"两节车厢之间的挂钩咬合，缓冲器吸收冲力，车头一动，后一节便跟着走","scene":"清晨的换乘站里，乘客从一班地铁下来，顺着指示牌走两分钟就上了另一班车。The connection between the two lines takes only two minutes.","sceneCN":"这里指两条线路之间可以转乘的衔接（第 4 个义项：交通班次的衔接）；句意：两条线路之间的换乘只需两分钟。","pos":[{"tag":"n.","zh":"连接；联系；人脉；衔接；关联"}],"collocations":[{"phrase":"in connection with","zh":"关于；与……有关"},{"phrase":"internet connection","zh":"网络连接"},{"phrase":"direct connection","zh":"直接联系"},{"phrase":"connection between","zh":"……之间的联系"},{"phrase":"lose connection","zh":"失去连接"},{"phrase":"family connection","zh":"家族关系"}],"forms":[{"label":"单数","form":"connection"},{"label":"复数","form":"connections"},{"label":"动词原形","form":"connect"},{"label":"形容词","form":"connected"},{"label":"名词（性质）","form":"connectivity"}],"derivatives":[{"word":"connect","pos":"v.","zh":"由该名词回溯的动词形式，义为「连接、接通」"},{"word":"connected","pos":"adj.","zh":"由该动词加已然词尾构成，义为「已连接的」"},{"word":"connective","pos":"adj./n.","zh":"由同一词干加表示功能的词尾构成，义为「连接的；连接成分」"},{"word":"connectivity","pos":"n.","zh":"由形容词词干加表示状态的名词尾构成，义为「连通性」"},{"word":"connector","pos":"n.","zh":"由该动词加施动者词尾构成，义为「连接器」"},{"word":"disconnect","pos":"v.","zh":"由表示「分开」的否定前缀加该动词构成，义为「断开」"}],"senses":[{"no":"01","title":"The place where two parts meet","titleCN":"两部分的接合处","definition":"the joint or point at which two objects are attached","definitionCN":"两个物体被接上的接头或位置","example":"The connection between the pipe and the tank leaks.","exampleCN":"管道与储罐之间的接合处在漏。","why":"The noun ending names the result of the verb, so the first sense is the joint that the act leaves behind.","whyCN":"名词词尾命名动词的结果，因此第一个义项就是动作留下的那个接头。"},{"no":"02","title":"A relation between things","titleCN":"事物之间的联系","definition":"a link of cause, similarity or dependence between two things","definitionCN":"两事物之间在因果、相似或依赖上的联系","example":"Researchers found a connection between sleep and memory.","exampleCN":"研究者发现睡眠与记忆之间存在联系。","why":"Things that are joined in thought form a relation, and the noun covers that abstract joint.","whyCN":"在思维中被接上的事物形成一种关系，这个名词涵盖这种抽象接合。"},{"no":"03","title":"People who can reach one another","titleCN":"能相互找到的人脉","definition":"a person or group one knows and can call on, especially for help","definitionCN":"认识并能求助的人或群体，尤指能提供帮助的","example":"His family connections helped him find a place to stay.","exampleCN":"他的家族关系帮他找到了住处。","why":"The same noun that names a wire names a social link, because both let one end reach the other.","whyCN":"指线缆的名词也指社会关系，因为两者都让一端抵达另一端。"},{"no":"04","title":"A timed link between journeys","titleCN":"行程之间按时刻衔接","definition":"an arrangement that lets a traveller move from one vehicle or route to another","definitionCN":"使旅客能从一种交通工具或一条路线转到另一种的安排","example":"We missed the connection by four minutes.","exampleCN":"我们差四分钟错过了换乘。","why":"Two journeys are joined in time, so the noun names the scheduled joint between them.","whyCN":"两段行程在时间上被接上，因此这个名词指它们之间按时刻表形成的衔接。"},{"no":"05","title":"The live link of a device","titleCN":"设备生效的连接","definition":"the working link between a device and a network, telephone line or supply","definitionCN":"设备与网络、电话线或电源之间正在工作的链路","example":"The laptop dropped its connection during the upload.","exampleCN":"上传过程中笔记本电脑的连断开了。","why":"When the joint is a channel that carries a signal, the noun names the live channel itself.","whyCN":"当接合是一条传送信号的通道时，这个名词就指这条生效的通道。"},{"no":"06","title":"Being related to a matter","titleCN":"与某件事有关","definition":"the relation of a person or thing to an event or question, as in the fixed phrase in connection with","definitionCN":"人或事物与某事件或问题的关联，如固定说法「关于」","example":"He was questioned in connection with the missing files.","exampleCN":"他就文件丢失一事接受了询问。","why":"A joint can be a procedural one between a person and an inquiry, which the fixed phrase makes explicit.","whyCN":"接合也可以是人与调查之间的程序性联系，固定说法把这一点说清。"},{"no":"07","title":"A line that carries current","titleCN":"通电的线路","definition":"a wire or circuit joining a device to a supply or to another device","definitionCN":"把设备接到电源或另一设备的导线或电路","example":"Check the connection at the meter before calling an electrician.","exampleCN":"叫电工之前先检查电表处的接线。","why":"In electrical work the joint is a conductor, so the noun shifts from the meeting point to the line itself.","whyCN":"在电气工作中，接合处就是导体，因此这个名词从交点转向线路本身。"},{"no":"08","title":"Logical coherence","titleCN":"逻辑上的连贯","definition":"the quality of following on from something else in a way that makes sense","definitionCN":"以合乎情理的方式承接另一事物的性质","example":"There is no connection between the two arguments.","exampleCN":"这两个论证之间没有逻辑关联。","why":"Arguments that follow from one another are joined in reasoning, giving the noun this coherence sense.","whyCN":"彼此推出的论证在推理上被接上，于是这个名词有了这种连贯义。"}],"etymology":{"intro":{"en":"Connection comes from Latin connexio, a noun of joining built on connectere; French carried it into English, and the spelling later shifted.","cn":"这个词来自拉丁语表示「连接」的名词，由「绑在一起」的动词构成；经法语进入英语，拼写后来发生转变。"},"items":[{"era":"LATIN NECTERE","en":"The verb nectere meant to bind or fasten, and it is the stem behind both the verb and the noun.","cn":"动词原义为「系、绑、固定」，是动词与名词共同的词干。"},{"era":"LATIN CONNEXIO","en":"The noun added an action-result ending to the compound verb, naming a joining or a joint rather than the act of tying.","cn":"这个名词在复合动词后加表示动作结果的名词尾，指连接或接合处，而不是绑的动作。"},{"era":"FRENCH CONNEXION","en":"Old French took the Latin noun and passed it to English, where it first appeared with the older spelling.","cn":"古法语接过这个拉丁名词再传入英语，最初进入时用的是较旧的拼写。"},{"era":"SPELLING SHIFT","en":"Later writers reshaped the word toward the Latin verb, replacing the old ending with the one heard in words such as correction.","cn":"后来的书写者按拉丁动词改写这个词，用类似「纠正」等词中的词尾替换了旧词尾。"},{"era":"MODERN RANGE","en":"The word spread from physical joints to social contacts, transport timetables, telephone circuits and logical links.","cn":"这个词从物理接合扩展到社会关系、交通时刻、电话电路与逻辑联系。"},{"era":"RECONSTRUCTED ROOT","en":"The deeper source of nectere is reconstructed as a binding root and is not directly attested, so it is a reconstruction rather than a recorded form.","cn":"「系、绑」更早的来源被重构为一个表示绑缚的词根，并未直接见于文献，因此是重构形式而非有记录的形式。"}]},"similar":{"note":{"en":"The first group shares the binding stem and differs in function; the second group names other kinds of link.","cn":"第一组共享「绑」的词干而功能不同；第二组是其他类型的联系。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"connexion","ipa":"/kəˈnekʃən/","tag":"older spelling","definition":"An older British spelling of the same noun, kept by some religious and formal writers.","definitionCN":"同一名词的旧式英式拼写，仍被部分宗教与正式写作者保留。"},{"word":"connector","ipa":"/kəˈnektə/","tag":"device noun","definition":"The physical part that makes a joint, rather than the joint or relation itself.","definitionCN":"使接合得以发生的物理部件，而不是接合处或关系本身。"},{"word":"connected","ipa":"/kəˈnektɪd/","tag":"adjective","definition":"Describing something already joined; it is a state word, not the name of the link.","definitionCN":"描述已接上的状态，是状态词，不是连接本身的名称。"},{"word":"connectivity","ipa":"/ˌkənekˈtɪvəti/","tag":"quality noun","definition":"The degree to which parts can reach one another; it measures the property rather than naming a link.","definitionCN":"各部分相互可达的程度；衡量性质，而不是命名某条连接。"}]},{"heading":"NEAR MEANING","entries":[{"word":"link","ipa":"/lɪŋk/","tag":"noun and verb","definition":"A single element that joins two things; it is often more concrete and countable than connection.","definitionCN":"连接两物的单个环节；通常比目标词更具体、更可数。"},{"word":"association","ipa":"/əˌsəʊsiˈeɪʃən/","tag":"abstract noun","definition":"A mental or statistical relation between things; it stresses co-occurrence rather than a physical joint.","definitionCN":"事物之间心理上或统计上的关系；强调共同出现，而非物理接合。"},{"word":"junction","ipa":"/ˈdʒʌŋkʃən/","tag":"place noun","definition":"A place where routes or lines meet; it is almost always physical and locational.","definitionCN":"路线或线路相交的地点；几乎总是物理且带位置的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Latin stem, the spelling story and the fixed phrases.","cn":"正常联想：拉丁词干、拼写演变与固定搭配。"},"normal":[{"en":"Same stem as connect, but the noun names the joint or the relation, not the act.","cn":"与动词同词干，但名词指接合处或关系，而不是动作。"},{"en":"The family runs connect, connection, connected, connector and connectivity.","cn":"同族词有连接、联系、已连接的、连接器与连通性。"},{"en":"Fixed phrases mark the abstract side: in connection with, connection between.","cn":"固定搭配标出抽象一面：关于、……之间的联系。"},{"en":"Fixed phrases mark the technical side: internet connection, lose connection.","cn":"固定搭配标出技术一面：网络连接、失去连接。"},{"en":"The older spelling with x survives in some formal and religious writing.","cn":"带旧拼写字母的写法仍在部分正式与宗教写作中保留。"}],"abstract":[{"en":"Picture two train carriages whose couplers touch and then move as one.","cn":"想象两节车厢的挂钩相触，随后像一节一样移动。"},{"en":"Picture two dots on a page joined by a pencil line that can be erased at either end.","cn":"想象纸上的两个点被一条铅笔线连着，两端都能擦掉。"},{"en":"Picture a name in an address book that opens a door in another city.","cn":"想象通讯录里的一个名字，能打开另一座城市的一扇门。"}]},"examples":[{"en":"The connection between the two buildings is a narrow footbridge.","cn":"两栋建筑之间的连接是一条窄步行桥。"},{"en":"The study reports a strong connection between diet and mood.","cn":"该研究报告饮食与情绪之间有很强的联系。"},{"en":"She made the connection while reading an old letter.","cn":"她读一封旧信时把线索串了起来。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「可耐克神」——两个接口耐得住、接得神 → 连接、联系","word":"connection"},"root":"拉丁语表示「连接」的名词，出自「共同」与「系、绑」的动词；经法语进入英语。","sensesIntro":{"en":"Eight senses name what a join leaves behind: a joint, a relation, people, a transfer, a channel, a procedural link, a wire, and logical coherence.","cn":"八个义项命名接合留下的东西：接头、关系、人脉、换乘、通道、程序性关联、导线与逻辑连贯。"},"semanticMap":{"core":{"en":"CORE IMAGE: two parts held by one joint so that movement at one end reaches the other.","cn":"核心意象：两部分被一个接头连住，一端的动作能传到另一端。"},"chain":["TWO PARTS","A JOINT","A CHANNEL","PEOPLE REACHABLE","ROUTES ALIGNED","MATTERS RELATED"],"branches":[{"senses":"01 · 07","en":"THE PHYSICAL JOINT: the meeting point of two objects, and the wire that carries current through it.","cn":"物理接合：两个物体的相接处，以及穿过它通电的导线。"},{"senses":"02 · 08","en":"THE ABSTRACT JOINT: a causal or logical relation, including the coherence of an argument.","cn":"抽象接合：因果或逻辑关系，包括论证的连贯性。"},{"senses":"03","en":"PEOPLE WHO CAN REACH EACH OTHER: contacts and family ties that open doors.","cn":"能相互找到的人：能打开门路的人脉与亲属关系。"},{"senses":"04","en":"JOURNEYS JOINED IN TIME: a scheduled transfer from one route to another.","cn":"按时间接上的行程：从一条路线到另一条路线的计划换乘。"},{"senses":"05 · 06","en":"THE LIVE AND PROCEDURAL LINK: a working device channel, and the phrase that ties a person to an inquiry.","cn":"生效链路与程序关联：正在工作的设备通道，以及把人牵涉进某项调查的说法。"}]},"affixes":{"intro":{"en":"Connection is a Latin-derived noun with a prefix, a binding stem and two layers of endings.","cn":"这个词是源自拉丁语的名词，带一个前缀、一个表示绑缚的词干，以及两层词尾。"},"latinIntro":{"en":"Latin supplies com-, nectere and the noun connexio; real cognates therefore appear in the Latin list.","cn":"拉丁语提供了前缀「共同」、动词「系、绑」与名词「连接」，因此拉丁词条中列出真实同族词。"},"items":[{"word":"com-","structure":"Latin prefix, assimilated form of con-","meaning":"together; with","meaningCN":"共同；一起","example":"The prefix marks the joining of two ends.","exampleCN":"这个前缀标记两个端点的接合。"},{"word":"nectere","structure":"Latin verb","meaning":"to bind, fasten","meaningCN":"系；绑；固定","example":"The stem supplies the knot in the image.","exampleCN":"这个词干提供了画面中的那个结。"},{"word":"connexio","structure":"Latin noun from connectere","meaning":"a joining; a joint","meaningCN":"连接；接合处","example":"The Latin noun is the direct source of the English word.","exampleCN":"这个拉丁名词是英语词的直接来源。"},{"word":"-ion","structure":"action-result noun ending","meaning":"the act or result of joining","meaningCN":"连接的动作或结果","example":"The ending turns the verb into a name for the joint.","exampleCN":"这个词尾把动词变成指接合处的名词。"},{"word":"connection","structure":"connexio through French","meaning":"the state of being joined","meaningCN":"被连接的状态","example":"The noun entered English with an older spelling.","exampleCN":"这个名词以较旧的拼写进入英语。"},{"word":"connected","structure":"connect plus the completed-state ending","meaning":"already joined","meaningCN":"已连接的","example":"The connected parts now move together.","exampleCN":"已连接的部件现在一起运动。"},{"word":"-or","structure":"agent noun ending","meaning":"the thing that joins","meaningCN":"起连接作用的东西","example":"A connector makes the joint possible.","exampleCN":"连接器使接合成为可能。"},{"word":"-ity","structure":"state noun ending","meaning":"the quality of being linked","meaningCN":"相连的性质","example":"Connectivity measures how easily parts reach one another.","exampleCN":"连通性衡量各部分相互可达的容易程度。"},{"word":"dis-","structure":"Latin prefix of separation","meaning":"apart; away","meaningCN":"分开；离开","example":"Disconnect undoes the joint.","exampleCN":"断开就是撤销那个接合。"}],"latinEntries":[{"word":"nectere","structure":"Latin verb","meaning":"to bind, tie","meaningCN":"系；绑"},{"word":"connexio","structure":"Latin noun from connectere","meaning":"a joining together","meaningCN":"连接；接合"},{"word":"nexus","structure":"Latin noun from nectere","meaning":"a binding, a link","meaningCN":"联结；纽带"}],"derivatives":[{"word":"connect","pos":"v.","zh":"由该名词回溯的动词形式，义为「连接、接通」"},{"word":"connected","pos":"adj.","zh":"由该动词加已然词尾构成，义为「已连接的」"},{"word":"connective","pos":"adj./n.","zh":"由同一词干加表示功能的词尾构成，义为「连接的；连接成分」"},{"word":"connectivity","pos":"n.","zh":"由形容词词干加表示状态的名词尾构成，义为「连通性」"},{"word":"connector","pos":"n.","zh":"由该动词加施动者词尾构成，义为「连接器」"},{"word":"disconnect","pos":"v.","zh":"由表示分开的前缀加该动词构成，义为「断开」"}]}},{"word":"wireless","ipa_uk":"/ˈwaɪələs/","ipa_us":"/ˈwaɪərləs/","definition_zh":"无线的；无线电的；无线网络；无线设备","definition_en":"using radio waves rather than wires to carry signals, or a system or device that works in this way","core_image":"屋顶上一根细天线对着天空，屋里桌面上没有一根线，音箱却在播放音乐","scene":"客厅的电视柜后没有一根多余的线，音箱和手柄都靠看不见的波与主机相连。A wireless setup removes the tangle of cables behind the desk.","sceneCN":"这里指不用导线、靠无线电波传输信号的（第 1 个义项：无线的）；句意：无线方案省去了桌后缠成一团的线缆。","pos":[{"tag":"adj.","zh":"无线的；无线电的"},{"tag":"n.","zh":"无线网络；无线电设备"}],"collocations":[{"phrase":"wireless network","zh":"无线网络"},{"phrase":"wireless connection","zh":"无线连接"},{"phrase":"wireless device","zh":"无线设备"},{"phrase":"wireless technology","zh":"无线技术"},{"phrase":"wireless internet","zh":"无线互联网"},{"phrase":"wireless communication","zh":"无线通信"}],"forms":[{"label":"原级","form":"wireless"},{"label":"比较级","form":"more wireless"},{"label":"最高级","form":"most wireless"},{"label":"副词","form":"wirelessly"}],"derivatives":[{"word":"wire","pos":"n.","zh":"复合词词干，古英语表示「金属线」的名词"},{"word":"wired","pos":"adj.","zh":"由「线」的名词加已然词尾构成，义为「有线的、接线的」"},{"word":"wiring","pos":"n.","zh":"由「布线」的动词加动作名词尾构成，义为「线路系统」"},{"word":"wirelessly","pos":"adv.","zh":"由该形容词加副词词尾构成，义为「以无线方式」"}],"senses":[{"no":"01","title":"Carrying signals without wires","titleCN":"不用导线传输信号","definition":"describing a system that sends or receives signals through the air rather than along cables","definitionCN":"指通过空气而不是沿电缆发送或接收信号的系统","example":"The new headset is completely wireless.","exampleCN":"这款新耳机完全是无线的。","why":"The word is the noun for a metal thread plus a suffix meaning without, so it literally describes what the system lacks.","whyCN":"这个词由「金属线」的名词加表示「没有」的词尾构成，字面就描述了系统所缺少的东西。"},{"no":"02","title":"Radio communication as a field","titleCN":"无线电通信这一领域","definition":"the technology or practice of sending signals by radio waves","definitionCN":"用无线电波发送信号的技术或实践","example":"Wireless began with telegraphy between ships.","exampleCN":"无线电通信始于船舶之间的电报。","why":"Because early radio was simply communication without wires, the adjective became the name of the whole field.","whyCN":"由于早期无线电就是「没有线的通信」，这个形容词便成了整个领域的名称。"},{"no":"03","title":"A local network without cables","titleCN":"无需线缆的本地网络","definition":"a network, especially a local one, that devices join through radio links","definitionCN":"设备通过无线电链路接入的网络，尤指局域网","example":"The cafe offers free wireless to its customers.","exampleCN":"这家咖啡馆向顾客提供免费无线网络。","why":"A network is named by the medium that carries it, so the adjective alone can stand for the wireless network.","whyCN":"网络以承载它的媒介命名，因此这个形容词单独使用就能指无线网络。"},{"no":"04","title":"A device that needs no cable","titleCN":"不需要线缆的设备","definition":"a device, such as a speaker or a mouse, that connects by radio","definitionCN":"通过无线电连接的设备，如音箱或鼠标","example":"He bought a wireless speaker for the kitchen.","exampleCN":"他给厨房买了一个无线音箱。","why":"The adjective can shift to the noun it modifies, so the device itself is called wireless.","whyCN":"形容词可以转指它所修饰的名词，因此设备本身就被称作无线的。"},{"no":"05","title":"Early telegraphy by radio","titleCN":"早期的无线电电报","definition":"the historical service of sending coded messages by radio instead of cable","definitionCN":"历史上通过无线电而非电缆发送编码信息的业务","example":"The ship's wireless operator stayed awake all night.","exampleCN":"船上的无线电报务员整夜未眠。","why":"The noun form named the equipment and the service, a usage that survives in maritime and historical writing.","whyCN":"名词形式指设备与业务，这一用法在海事与历史写作中仍有留存。"},{"no":"06","title":"The technology of radio transmission","titleCN":"无线电传输技术","definition":"the engineering methods that move data through the air","definitionCN":"让数据通过空气传输的工程方法","example":"Wireless research now focuses on low power and high density.","exampleCN":"无线技术研究如今聚焦低功耗与高密度。","why":"A technology defined by the absence of wires is naturally named by that same absence.","whyCN":"一项以「没有线」为特征的技术，自然就用这一特征命名。"},{"no":"07","title":"Audio without a cable","titleCN":"无需线缆的音频","definition":"describing sound equipment that receives audio by radio","definitionCN":"指通过无线电接收音频的声音设备","example":"The wireless earbuds pair with the phone in seconds.","exampleCN":"无线耳塞几秒内就与手机配对。","why":"Consumer audio adopted the word early, so the adjective became the ordinary label for cable-free sound gear.","whyCN":"消费音频很早就采用这个词，因此它成了无线音频设备的日常标签。"},{"no":"08","title":"Free of physical ties","titleCN":"不受实体线缆束缚","definition":"describing a situation in which no cable restricts movement or placement","definitionCN":"指没有线缆限制移动或摆放的情形","example":"A wireless office lets people take the laptop anywhere.","exampleCN":"无线办公室让人可以把笔记本电脑带到任何地方。","why":"The literal absence of wires extends to the freedom of movement that absence allows.","whyCN":"字面上的「没有线」延伸到由此获得的移动自由。"}],"etymology":{"intro":{"en":"Wireless is a native English formation of wire plus the suffix -less, meaning without; radio gave it its modern sense in the 1890s.","cn":"这个词是英语本族构词：名词「金属线」加表示「没有」的词尾；十九世纪九十年代无线电赋予它现代意义。"},"items":[{"era":"OLD ENGLISH WIR","en":"Wir named a thread of metal, and it is the same word English still uses for a conductor or a telegram.","cn":"古英语中这个词指金属细丝，至今仍用来指导线或电报。"},{"era":"SUFFIX -LESS","en":"The suffix means without or lacking, and it has formed English adjectives for many centuries.","cn":"这个词尾意为「没有、缺乏」，数百年来一直在构成英语形容词。"},{"era":"WIRELESS TELEGRAPHY","en":"When messages were sent through the air instead of along a cable, the plain description wireless telegraphy was shortened to wireless.","cn":"当信息改为通过空气而非电缆传送时，原本的描述性说法被缩略为这个词。"},{"era":"MARCONI AND SHIPS","en":"Ship and coastal stations made the noun familiar, and the operator on board was called the wireless operator.","cn":"船舶与海岸电台让这个名词广为熟知，船上的报务员就被称为无线电报务员。"},{"era":"BROADCAST AND NETWORK","en":"Broadcasting and later local computer networks extended the word from telegraphy to any cable-free link.","cn":"广播以及后来的本地计算机网络把这个词从电报扩展到任何无需线缆的链路。"},{"era":"FIRST PUBLICATION UNCERTAIN","en":"The first published use of the shortened noun is generally placed in the 1890s, but the exact year and writer are not settled.","cn":"缩略名词的首次发表一般定在十九世纪九十年代，但确切年份与作者尚无定论。"}]},"similar":{"note":{"en":"The first group shares the wire idea; the second group names cable-free or radio-based alternatives.","cn":"第一组共享「线」这一概念；第二组是无需线缆或以无线电为基础的相邻说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"wired","ipa":"/ˈwaɪəd/","tag":"opposite adjective","definition":"Connected by cables; it is the direct contrast to the target word.","definitionCN":"通过电缆连接的；是目标词的直接反义说法。"},{"word":"wireline","ipa":"/ˈwaɪəlaɪn/","tag":"industry adjective","definition":"Describing cable-based telecom networks, used mainly in engineering and regulation.","definitionCN":"描述以电缆为基础的电信网络，主要用于工程与监管语境。"},{"word":"wire","ipa":"/waɪə/","tag":"base noun","definition":"A metal conductor; the thing the suffix removes from the target word.","definitionCN":"金属导体；正是词尾从目标词中去掉的那个东西。"},{"word":"wirelessly","ipa":"/ˈwaɪələsli/","tag":"adverb","definition":"In a cable-free way; it modifies an action rather than describing a system.","definitionCN":"以无需线缆的方式；修饰动作，而不是描述系统。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cordless","ipa":"/ˈkɔːdləs/","tag":"device adjective","definition":"Without a cord, usually said of tools and phones powered by a battery.","definitionCN":"没有软线，通常指用电池供电的工具与电话。"},{"word":"radio","ipa":"/ˈreɪdiəʊ/","tag":"medium noun","definition":"The medium of radio waves; it names the carrier that makes wireless possible.","definitionCN":"无线电波这一媒介；命名的是使无线成为可能的载体。"},{"word":"mobile","ipa":"/ˈməʊbaɪl/","tag":"movement adjective","definition":"Able to move or be moved; it stresses movement rather than the absence of cables.","definitionCN":"能够移动或可被移动；强调移动，而不是没有线缆。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real native base, a real suffix and real technical phrases.","cn":"正常联想：真实的英语本族词基、真实词尾与真实技术搭配。"},"normal":[{"en":"Wire plus less: the word simply says without wire.","cn":"「线」加「没有」：这个词就是字面地说「没有线」。"},{"en":"The family runs wire, wired, wiring, wireless and wirelessly.","cn":"同族词有线、有线的、布线、无线的与以无线方式。"},{"en":"Fixed phrases mark the network: wireless network, wireless connection, wireless internet.","cn":"固定搭配标出网络：无线网络、无线连接、无线互联网。"},{"en":"Fixed phrases mark the device: wireless device, wireless speaker, wireless earbuds.","cn":"固定搭配标出设备：无线设备、无线音箱、无线耳塞。"},{"en":"Ship radios made the word famous, and the wireless operator was a real job title.","cn":"船用电台让这个词出名，无线电报务员曾是真实职位名。"}],"abstract":[{"en":"Picture a kite whose string has been cut but which still answers a whistle.","cn":"想象一只风筝，线被剪断了，却仍能回应一声口哨。"},{"en":"Picture a room where every object can whisper to every other without touching.","cn":"想象一间屋子，每件东西都能不接触地互相低语。"},{"en":"Picture a bridge made only of air, yet people cross it.","cn":"想象一座只由空气构成的桥，人们却能走过去。"}]},"examples":[{"en":"The wireless network covers the whole library.","cn":"无线网络覆盖了整个图书馆。"},{"en":"She prefers wireless headphones when she runs.","cn":"她跑步时更喜欢用无线耳机。"},{"en":"Early wireless operators worked through the night in stormy weather.","cn":"早期的无线电报务员在暴风雨天气里通宵工作。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「歪儿」少一点——线歪了、索性不要线，于是无线的","word":"wireless"},"root":"英语「金属线」加表示「没有」的形容词词尾；与拉丁语无关。","sensesIntro":{"en":"Eight senses turn one absence, no wires, into a medium, a field, a network, a device, a service, a technology, an audio label and a kind of freedom.","cn":"八个义项把同一个「没有线」变成一种媒介、一个领域、一张网络、一件设备、一项业务、一门技术、一个音频标签与一种自由。"},"semanticMap":{"core":{"en":"CORE IMAGE: a signal travelling through the air where a cable used to be.","cn":"核心意象：信号在原本该有线缆的地方穿过空气行进。"},"chain":["NO WIRE","RADIO WAVES","SIGNAL IN AIR","DEVICE FREE","LOCAL NETWORK","MOBILE LIFE"],"branches":[{"senses":"01","en":"THE DEFINING ABSENCE: a system that carries signals without cables.","cn":"决定性缺失：不用线缆传输信号的系统。"},{"senses":"02 · 05 · 06","en":"THE FIELD AND ITS HISTORY: radio telegraphy, its operators, and the engineering that grew from it.","cn":"领域及其历史：无线电电报、报务员，以及由此生长的工程技术。"},{"senses":"03","en":"THE NETWORK: a local system whose members join through radio links.","cn":"网络：成员通过无线电链路接入的本地系统。"},{"senses":"04 · 07","en":"THE HARDWARE: speakers, earbuds, mice and other devices that need no cable.","cn":"硬件：音箱、耳塞、鼠标等无需线缆的设备。"},{"senses":"08","en":"THE FREEDOM: placement and movement no longer constrained by a cord.","cn":"自由：摆放与移动不再受线缆约束。"}]},"affixes":{"intro":{"en":"Wireless is a native English adjective from a noun plus a privative suffix; no Latin element is involved.","cn":"这个词是英语本族形容词，由名词加表示「剥夺」的词尾构成，不涉及拉丁成分。"},"latinIntro":{"en":"Neither the base nor the suffix is Latin, so the Latin entry list is empty.","cn":"词基与词尾都并非来自拉丁语，因此拉丁词条列表留空。"},"items":[{"word":"wire","structure":"Old English noun wir","meaning":"a thread of metal","meaningCN":"金属线","example":"The base names the conductor that the system lacks.","exampleCN":"词基指系统所缺少的导体。"},{"word":"-less","structure":"English privative suffix","meaning":"without; lacking","meaningCN":"没有；缺乏","example":"The suffix turns a noun into an adjective of absence.","exampleCN":"这个词尾把名词变成表示「缺失」的形容词。"},{"word":"wireless","structure":"wire plus -less","meaning":"without wires","meaningCN":"没有线缆的","example":"The compound adjective is the ordinary label for cable-free systems.","exampleCN":"这个复合形容词是无需线缆系统的日常标签。"},{"word":"wired","structure":"wire plus the completed-state ending","meaning":"connected by cables","meaningCN":"以电缆连接的","example":"A wired link is the direct contrast.","exampleCN":"有线链路是它的直接对照。"},{"word":"wiring","structure":"wire plus the action noun ending","meaning":"a system of installed cables","meaningCN":"已安装的线路系统","example":"The wiring of the building was replaced last year.","exampleCN":"这栋楼的线路系统去年被更换了。"},{"word":"wirelessly","structure":"wireless plus the adverb ending","meaning":"in a cable-free way","meaningCN":"以无需线缆的方式","example":"The data travels wirelessly between the two rooms.","exampleCN":"数据在两个房间之间无线传输。"},{"word":"wireline","structure":"wire plus line","meaning":"a cable-based telecom network","meaningCN":"以电缆为基础的电信网络","example":"Wireline service still reaches many rural homes.","exampleCN":"有线电信服务仍覆盖许多乡村家庭。"},{"word":"cordless","structure":"cord plus -less","meaning":"without a flexible cord","meaningCN":"没有软线的","example":"A cordless drill is a close cousin of the target word.","exampleCN":"无绳电钻是目标词的近亲说法。"}],"latinEntries":[],"derivatives":[{"word":"wire","pos":"n.","zh":"复合词词基，古英语表示「金属线」的名词"},{"word":"wired","pos":"adj.","zh":"由「线」的名词加已然词尾构成，义为「有线的、接线的」"},{"word":"wiring","pos":"n.","zh":"由「布线」的动词加动作名词尾构成，义为「线路系统」"},{"word":"wirelessly","pos":"adv.","zh":"由该形容词加副词词尾构成，义为「以无线方式」"}]}},{"word":"signal processing","ipa_uk":"/ˈsɪɡnəl ˈprəʊsesɪŋ/","ipa_us":"/ˈsɪɡnəl ˈprɑːsesɪŋ/","definition_zh":"信号处理；对信号进行分析、变换与信息提取的技术","definition_en":"the analysis and transformation of signals such as sound, images or sensor readings in order to extract or improve information","core_image":"示波器屏幕上一条杂乱的曲线经过滤波器后变得平滑，噪声被削掉，真正的心跳波形显露出来","scene":"工程师把麦克风录到的嘈杂人声导入软件，滤掉低频轰鸣后，说话声变得清晰可辨。Signal processing cleans the recording before anyone transcribes it.","sceneCN":"这里指用算法对采集到的信号做滤波、变换等信息提取（第 1 个义项：信号的分析与变换）；句意：信号处理先把录音净化，再由人转写。","pos":[{"tag":"n.","zh":"信号处理；信号分析与变换"}],"collocations":[{"phrase":"digital signal processing","zh":"数字信号处理"},{"phrase":"signal processing algorithm","zh":"信号处理算法"},{"phrase":"audio signal processing","zh":"音频信号处理"},{"phrase":"image signal processing","zh":"图像信号处理"},{"phrase":"signal processing technique","zh":"信号处理技术"},{"phrase":"real-time signal processing","zh":"实时信号处理"}],"forms":[{"label":"名词（不可数）","form":"signal processing"},{"label":"定语用法","form":"signal-processing"},{"label":"相关动词短语","form":"process a signal"},{"label":"施动名词","form":"signal processor"}],"derivatives":[{"word":"signal","pos":"n./v.","zh":"复合词前半，源自拉丁语「记号」，义为「信号；发信号」"},{"word":"process","pos":"v./n.","zh":"复合词后半，源自拉丁语「前进、过程」，义为「处理；过程」"},{"word":"processor","pos":"n.","zh":"由「处理」的动词加施动者词尾构成，义为「处理器」"},{"word":"processing","pos":"n.","zh":"由该动词加动作名词尾构成，义为「处理过程」"},{"word":"signal processor","pos":"n.","zh":"由前半名词加「处理器」复合，义为「信号处理器」"}],"senses":[{"no":"01","title":"Working on signals in general","titleCN":"对信号的一般处理","definition":"the field that transforms measured signals to remove noise or reveal information","definitionCN":"对测得的信号进行变换，以去除噪声或揭示信息的领域","example":"Signal processing turns a noisy recording into something usable.","exampleCN":"信号处理把嘈杂的录音变成可用的材料。","why":"A signal is a varying quantity carrying information, and processing is the set of operations performed on it.","whyCN":"信号是承载信息的变动量，而「处理」就是对它施加的一系列运算。"},{"no":"02","title":"Digital signal processing","titleCN":"数字信号处理","definition":"the branch that converts signals into numbers and operates on them with algorithms","definitionCN":"把信号转成数字并用算法运算的分支","example":"Digital signal processing made cheap hearing aids possible.","exampleCN":"数字信号处理使廉价助听器成为可能。","why":"Once a signal is sampled into numbers, the processing becomes arithmetic, and the branch gets its own name.","whyCN":"信号一旦被采样成数字，处理就变成算术运算，这一分支便有了自己的名称。"},{"no":"03","title":"Analog signal processing","titleCN":"模拟信号处理","definition":"the branch that works on continuous electrical signals with circuits rather than software","definitionCN":"用电路而非软件处理连续电信号的分支","example":"Analog signal processing still handles the first stage of the radio.","exampleCN":"模拟信号处理仍负责收音机的第一级。","why":"Before sampling, the signal stays continuous, so processing is done by physical circuits and earns a parallel name.","whyCN":"在采样之前信号仍是连续的，处理由物理电路完成，因此有了并行的名称。"},{"no":"04","title":"Processing sound and speech","titleCN":"处理声音与语音","definition":"the application of these methods to audio, voice and music","definitionCN":"把这些方法用于音频、语音与音乐","example":"Signal processing removes the hum from the interview.","exampleCN":"信号处理去掉了采访录音中的嗡鸣。","why":"Sound is a signal in time, so the general methods apply directly and the field names the application.","whyCN":"声音是随时间变化的信号，因此一般方法可直接套用，领域便以应用命名。"},{"no":"05","title":"Processing pictures","titleCN":"处理图像","definition":"the application of these methods to images, video and medical scans","definitionCN":"把这些方法用于图像、视频与医学扫描","example":"Signal processing sharpened the blurred scan.","exampleCN":"信号处理让模糊的扫描图像变清晰了。","why":"An image is a two-dimensional signal, so the same operations extend from time to space.","whyCN":"图像是二维信号，因此同样的运算从时间维度扩展到空间维度。"},{"no":"06","title":"Processing in communication","titleCN":"通信中的信号处理","definition":"the use of these methods to encode, compress, transmit and recover messages","definitionCN":"用这些方法对信息进行编码、压缩、传输与恢复","example":"Signal processing keeps the satellite link readable in rain.","exampleCN":"信号处理让卫星链路在雨天仍可读。","why":"Every message that travels must be shaped and repaired, and that work is a major branch of the field.","whyCN":"每个传输的信息都必须被整形与修复，这项工作构成该领域的一大分支。"},{"no":"07","title":"Processing sensor and radar returns","titleCN":"处理传感器与雷达回波","definition":"the use of these methods on measurements from instruments, including radar and sonar","definitionCN":"把这些方法用于仪器测量，包括雷达与声呐","example":"Signal processing separates the plane from the ground clutter.","exampleCN":"信号处理把飞机回波与地面杂波分开。","why":"Instruments return weak and noisy readings, so processing is what turns a return into a detection.","whyCN":"仪器返回的读数微弱且嘈杂，处理正是把回波变成检测结果的关键。"},{"no":"08","title":"Processing as it happens","titleCN":"即时进行的处理","definition":"the branch that completes the work fast enough to keep pace with a live signal","definitionCN":"以足够快的速度完成处理、跟得上实时信号的分支","example":"Real-time signal processing cancels the echo during the call.","exampleCN":"实时信号处理在通话过程中消除回声。","why":"When delay matters, speed becomes the defining constraint, and the field names that constraint as a sense.","whyCN":"当延迟变得关键，速度就成了决定性约束，领域便以这一约束命名一个义项。"}],"etymology":{"intro":{"en":"Signal processing joins Latin signum, a mark, and Latin processus, a forward course, into a twentieth-century technical term.","cn":"这个术语把拉丁语「记号」与拉丁语「前进、过程」组合起来，是二十世纪的技术名词。"},"items":[{"era":"LATIN SIGNUM","en":"Signum meant a mark or a sign, and it gave English signal for a measurable indication.","cn":"这个词意为「记号、标志」，为英语提供了表示可测量指示的「信号」一词。"},{"era":"LATIN PROCEDERE","en":"Procedere meant to go forward, and its noun processus named a course or a procedure.","cn":"这个动词意为「向前走」，其名词形式指过程或程序。"},{"era":"ENGLISH SIGNAL","en":"English signal first named a visible sign and later any varying quantity that carries information.","cn":"英语「信号」最初指可见的标志，后来指任何承载信息的变动量。"},{"era":"ENGLISH PROCESS","en":"Process named a series of actions, and as a verb it came to mean to handle something according to a method.","cn":"「过程」指一系列动作，作动词时意为按某种方法处理某物。"},{"era":"TWENTIETH CENTURY TERM","en":"As radio, radar and recording matured, the two words were combined into a name for the whole body of techniques.","cn":"随着无线电、雷达与录音技术成熟，两个词被组合起来，成为整套技术的名称。"},{"era":"FIRST RECORD UNKNOWN","en":"The first appearance of the exact compound is not recorded, so the term is dated only to the middle decades of the twentieth century.","cn":"这一确切复合词的首见没有记录，只能把术语定在二十世纪中叶的数十年间。"}]},"similar":{"note":{"en":"The first group shares the two Latin stems; the second group names neighbouring technical activities.","cn":"第一组共享两个拉丁词干；第二组是相邻的技术活动。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"signal","ipa":"/ˈsɪɡnəl/","tag":"base noun","definition":"The varying quantity that carries information; processing is what is done to it.","definitionCN":"承载信息的变动量；处理就是对它施加的操作。"},{"word":"processor","ipa":"/ˈprəʊsesə/","tag":"device noun","definition":"A device or program that carries out processing, including a signal processor.","definitionCN":"执行处理的设备或程序，包括信号处理器。"},{"word":"processing","ipa":"/ˈprəʊsesɪŋ/","tag":"activity noun","definition":"The activity of handling something by a method, without the signal element.","definitionCN":"按方法处理某物的活动，不含「信号」这一要素。"},{"word":"sign","ipa":"/saɪn/","tag":"source noun","definition":"The older everyday word for a mark; signal is its technical descendant.","definitionCN":"表示「标记」的更早日常词；「信号」是它在技术上的后裔。"}]},{"heading":"NEAR MEANING","entries":[{"word":"filtering","ipa":"/ˈfɪltərɪŋ/","tag":"operation","definition":"Removing unwanted parts of a signal by frequency or condition; one major operation within the field.","definitionCN":"按频率或条件去掉信号中不需要的部分；是该领域内的一项主要操作。"},{"word":"data analysis","ipa":"/ˈdeɪtə əˈnæləsɪs/","tag":"wider field","definition":"Extracting conclusions from data of any kind; wider than signals alone.","definitionCN":"从任何种类的数据中得出结论；范围比仅处理信号更宽。"},{"word":"modulation","ipa":"/ˌmɒdjʊˈleɪʃən/","tag":"communication step","definition":"Imposing information on a carrier wave; a step inside communication processing.","definitionCN":"把信息加载到载波上；是通信处理中的一个步骤。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: two real Latin stems and real engineering phrases.","cn":"正常联想：两个真实拉丁词干与真实工程搭配。"},"normal":[{"en":"Signal is a mark that carries information, and processing is the set of steps applied to it.","cn":"信号是承载信息的记号，处理就是施加于它的一套步骤。"},{"en":"The family runs signal, process, processor, processing and signal processor.","cn":"同族词有信号、过程、处理器、处理过程与信号处理器。"},{"en":"Fixed phrases mark the digital branch: digital signal processing and its algorithms.","cn":"固定搭配标出数字分支：数字信号处理及其算法。"},{"en":"Fixed phrases mark the applications: audio, image, radar and real-time processing.","cn":"固定搭配标出应用：音频、图像、雷达与实时处理。"},{"en":"The oscilloscope is the standard picture: a messy trace becoming a clean waveform.","cn":"示波器是标准画面：杂乱的曲线变成干净的波形。"}],"abstract":[{"en":"Picture a muddy stream passing through a sieve until only clear water remains.","cn":"想象一条浑浊的水流穿过筛子，最后只剩清水。"},{"en":"Picture a noisy room where one listener can pick out a single voice.","cn":"想象一间嘈杂的房间，一位听者能挑出唯一的一个声音。"},{"en":"Picture a letter rewritten in code and then restored without a smudge.","cn":"想象一封信被改写成密码，又毫无污损地还原。"}]},"examples":[{"en":"Signal processing is the first step in any acoustic study.","cn":"信号处理是任何声学研究的第一步。"},{"en":"The team applied signal processing to the telescope's raw data.","cn":"团队对望远镜的原始数据做了信号处理。"},{"en":"Modern hearing aids rely on real-time signal processing.","cn":"现代助听器依靠实时信号处理。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「信号」+「过筛子」——把信号过一遍筛子，留下有用的部分","word":"signal processing"},"root":"拉丁语「记号」加拉丁语「过程」；二十世纪组合成技术术语。","sensesIntro":{"en":"Eight senses divide the field by method and use: general, digital, analog, audio, image, communication, radar, and real-time.","cn":"八个义项按方法与用途划分这一领域：一般、数字、模拟、音频、图像、通信、雷达与实时。"},"semanticMap":{"core":{"en":"CORE IMAGE: a muddy trace entering a filter and leaving as a clean waveform.","cn":"核心意象：一条浑浊的波形进入滤波器，出来时变成干净的波形。"},"chain":["RAW SIGNAL","NOISE","FILTER","TRANSFORM","INFORMATION","DECISION"],"branches":[{"senses":"01","en":"THE WHOLE FIELD: any transformation of a measured signal.","cn":"整个领域：对测得信号所做的任何变换。"},{"senses":"02 · 03","en":"TWO IMPLEMENTATIONS: sampled numbers handled by algorithms, and continuous circuits handled in hardware.","cn":"两种实现：用算法处理采样后的数字，以及用硬件处理连续电路。"},{"senses":"04 · 05","en":"TWO DIMENSIONS: sound in time, and images in space.","cn":"两个维度：时间上的声音，与空间上的图像。"},{"senses":"06","en":"MESSAGES THAT MUST SURVIVE THE TRIP: encoding, compression and recovery in communication.","cn":"必须活着到达的信息：通信中的编码、压缩与恢复。"},{"senses":"07 · 08","en":"WEAK RETURNS AND FAST DEADLINES: radar echoes turned into detections, and work done while the signal is still live.","cn":"微弱回波与紧迫时限：把雷达回波变成检测，以及在信号仍在进行时完成处理。"}]},"affixes":{"intro":{"en":"Signal processing is a two-stem Latin compound; both stems still form English words and have real Latin cognates.","cn":"这个术语是双词干的拉丁复合词；两个词干至今都在构成英语词，并有真实的拉丁同族词。"},"latinIntro":{"en":"Both halves are Latin, so the Latin list can hold the nouns and verbs behind them.","cn":"两半都来自拉丁语，因此拉丁词条可以列出它们背后的名词与动词。"},"items":[{"word":"signum","structure":"Latin noun","meaning":"a mark, a sign","meaningCN":"记号；标志","example":"The first stem supplies the idea of a mark that carries meaning.","exampleCN":"第一个词干提供「承载意义的记号」这一概念。"},{"word":"procedere","structure":"Latin verb","meaning":"to go forward","meaningCN":"向前走；推进","example":"The second stem supplies the idea of a forward course of steps.","exampleCN":"第二个词干提供「一步步向前推进」的概念。"},{"word":"processus","structure":"Latin noun from procedere","meaning":"a course, a procedure","meaningCN":"过程；程序","example":"The noun names the series of operations.","exampleCN":"这个名词指一系列操作。"},{"word":"signal","structure":"signum through French","meaning":"a sign or a measurable indication","meaningCN":"标志或可测量的指示","example":"A signal is the quantity being worked on.","exampleCN":"信号就是被处理的那个量。"},{"word":"process","structure":"processus through French","meaning":"to handle by a method","meaningCN":"按方法处理","example":"To process a signal is to apply steps to it.","exampleCN":"处理信号就是对其施加一系列步骤。"},{"word":"-ing","structure":"action noun ending","meaning":"the doing of the action","meaningCN":"动作的进行","example":"The ending turns the verb into the name of the activity.","exampleCN":"这个词尾把动词变成活动的名称。"},{"word":"-or","structure":"agent noun ending","meaning":"the thing that performs","meaningCN":"执行该动作的装置","example":"A processor performs the operations.","exampleCN":"处理器执行这些运算。"},{"word":"signal-processing","structure":"compound used attributively","meaning":"serving to process signals","meaningCN":"用于处理信号的","example":"A signal-processing board sits inside the receiver.","exampleCN":"一块信号处理板装在接收机内部。"}],"latinEntries":[{"word":"signum","structure":"Latin noun","meaning":"a mark, a sign","meaningCN":"记号；标志"},{"word":"procedere","structure":"Latin verb","meaning":"to go forward","meaningCN":"向前走；推进"},{"word":"processus","structure":"Latin noun from procedere","meaning":"a course, a procedure","meaningCN":"过程；程序"}],"derivatives":[{"word":"signal","pos":"n./v.","zh":"复合词前半，源自拉丁语「记号」，义为「信号；发信号」"},{"word":"process","pos":"v./n.","zh":"复合词后半，源自拉丁语「前进、过程」，义为「处理；过程」"},{"word":"processor","pos":"n.","zh":"由「处理」的动词加施动者词尾构成，义为「处理器」"},{"word":"processing","pos":"n.","zh":"由该动词加动作名词尾构成，义为「处理过程」"},{"word":"signal processor","pos":"n.","zh":"由前半名词加「处理器」复合，义为「信号处理器」"}]}},{"word":"interface","ipa_uk":"/ˈɪntəfeɪs/","ipa_us":"/ˈɪntərfeɪs/","definition_zh":"界面；接口；接触面；相互作用；连接","definition_en":"a surface or point where two things meet, or the means by which a user or system communicates with another","core_image":"两块不同的材料在一条清晰的分界线上贴合，一侧是金属，一侧是液体，交界处微微泛起反应的光","scene":"设计师把按钮、搜索框和图标排在一屏之内，用户手指一点就能完成操作。A clear interface makes the software feel simple.","sceneCN":"这里指用户与软件之间交互的屏幕层（第 1 个义项：人机界面）；句意：清晰的界面让软件用起来很简单。","pos":[{"tag":"n.","zh":"界面；接口；接触面；相互作用"},{"tag":"v.","zh":"连接；对接"}],"collocations":[{"phrase":"user interface","zh":"用户界面"},{"phrase":"graphical user interface","zh":"图形用户界面"},{"phrase":"interface between","zh":"……之间的交界面"},{"phrase":"application programming interface","zh":"应用程序编程接口"},{"phrase":"interface design","zh":"界面设计"},{"phrase":"interface with","zh":"与……对接"}],"forms":[{"label":"单数","form":"interface"},{"label":"复数","form":"interfaces"},{"label":"第三人称单数","form":"interfaces"},{"label":"过去式","form":"interfaced"},{"label":"过去分词","form":"interfaced"},{"label":"现在分词","form":"interfacing"}],"derivatives":[{"word":"interfacial","pos":"adj.","zh":"由该名词加表示「属于」的形容词尾构成，义为「界面的、界面上的」"},{"word":"interfacing","pos":"n./adj.","zh":"由该动词加动作词尾构成，义为「对接；对接的」"},{"word":"interfaced","pos":"adj.","zh":"由该动词加已然词尾构成，义为「已对接的」"},{"word":"interfacially","pos":"adv.","zh":"由形容词加副词词尾构成，义为「在界面层面」"}],"senses":[{"no":"01","title":"The screen between user and machine","titleCN":"用户与机器之间的屏幕层","definition":"the part of a system that a person sees and operates, such as buttons, menus and windows","definitionCN":"系统中被人看见并操作的部分，如按钮、菜单与窗口","example":"The interface puts the search box at the top of the page.","exampleCN":"这个界面把搜索框放在页面顶部。","why":"The word names the meeting surface, and in software that surface is what the user touches.","whyCN":"这个词命名相接的表面，在软件中那个表面就是用户所触的部分。"},{"no":"02","title":"The point where two systems join","titleCN":"两个系统相接的接口","definition":"a standard connection through which one system or component talks to another","definitionCN":"一个系统或组件与另一个对话时所依据的标准连接","example":"The two programs share a narrow interface.","exampleCN":"这两个程序共用一个窄接口。","why":"Two systems meet at a defined boundary, and the standards at that boundary are called the interface.","whyCN":"两个系统在一条明确的边界相接，边界上的标准就称为接口。"},{"no":"03","title":"The boundary between two materials","titleCN":"两种材料之间的分界面","definition":"the surface where two substances or phases meet","definitionCN":"两种物质或物相相接的表面","example":"Water and oil form a sharp interface.","exampleCN":"水与油形成清晰的界面。","why":"In physics the word keeps its literal sense: a surface where one phase ends and another begins.","whyCN":"在物理学中这个词保留字面义：一种物相结束、另一种开始的表面。"},{"no":"04","title":"The joint between two parts","titleCN":"两个部件之间的接合处","definition":"the place where two machine parts or structures meet and act on each other","definitionCN":"两个机械部件或结构相接并相互作用的位置","example":"Engineers checked the interface for wear.","exampleCN":"工程师检查了接合处是否磨损。","why":"Machines also have meeting surfaces where force is transferred, so the word extends to mechanical joints.","whyCN":"机器同样有传递力的相接表面，因此这个词扩展到机械接合处。"},{"no":"05","title":"The channel of interaction","titleCN":"相互作用的通道","definition":"the means by which two parties or fields interact and exchange influence","definitionCN":"两方或两个领域相互作用、交换影响的方式","example":"The conference became an interface between research and industry.","exampleCN":"这场会议成了研究与产业之间的交流通道。","why":"If two worlds meet, the meeting surface can be social or institutional, not only physical.","whyCN":"若两个世界相遇，相接的表面可以是社会的或机构的，而不只是物理的。"},{"no":"06","title":"The agreed protocol","titleCN":"约定的接口规范","definition":"a documented set of rules that lets independently built systems work together","definitionCN":"一套成文规则，使独立构建的系统能够协同工作","example":"The interface is published so other teams can build on it.","exampleCN":"接口规范已公布，其他团队可以据此开发。","why":"A boundary needs rules if both sides are built separately, and the rules themselves take the name.","whyCN":"若两侧分别构建，边界就需要规则，而这些规则本身也沿用这个名称。"},{"no":"07","title":"The graphical front end","titleCN":"图形化前端","definition":"a visual interface built from windows, icons and pointers rather than typed commands","definitionCN":"由窗口、图标与指针构成、而非键入命令的视觉界面","example":"The graphical interface replaced the command line for most users.","exampleCN":"对多数用户而言，图形界面取代了命令行。","why":"Drawing rather than typing changes the meeting surface, so the graphical kind gets its own label.","whyCN":"用画而不是打字改变了相接的表面，因此图形化的那一类有了自己的标签。"},{"no":"08","title":"To join two systems","titleCN":"作为动词：使两系统对接","definition":"to connect one system or device to another so that they can work together","definitionCN":"把一个系统或设备接到另一个上，使它们协同工作","example":"The clinic interface the new records system with the old one.","exampleCN":"诊所把新的病历系统与旧系统对接起来。","why":"The noun became a verb meaning to create such a meeting surface, a common shift in technical English.","whyCN":"这个名词转为动词，意为建立这样一个相接表面，这是技术英语中常见的转类。"}],"etymology":{"intro":{"en":"Interface is Latin inter, between, plus English face from Latin facies, a form or surface; the computing sense is twentieth-century.","cn":"这个词由拉丁语「在……之间」与英语「面」（源自拉丁语「外形、表面」）构成；计算机义项是二十世纪的。"},"items":[{"era":"LATIN INTER","en":"Inter meant between, and it marks the word as naming something that lies between two sides.","cn":"这个词素意为「在……之间」，标记该词命名位于两侧之间的东西。"},{"era":"LATIN FACIES","en":"Facies meant form, appearance or surface, and it is the source of English face.","cn":"这个词意为外形、外观或表面，是英语「面」的来源。"},{"era":"NINETEENTH CENTURY PHYSICS","en":"The noun was coined for the surface where two bodies or phases meet, a sense still used in chemistry and physics.","cn":"这个名词最初指两个物体或物相相接的表面，这一义项至今仍用于化学与物理。"},{"era":"COMPUTING SENSE","en":"In the 1960s the word was applied to the boundary between hardware and software, and then to what a user sees.","cn":"二十世纪六十年代，这个词被用于硬件与软件的边界，随后又指用户所看到的部分。"},{"era":"VERB USE","en":"Engineers turned the noun into a verb meaning to connect systems at such a boundary.","cn":"工程师把这个名词转为动词，意为在这样的边界上连接系统。"},{"era":"FIRST COMPUTING USE UNCERTAIN","en":"The first use of the computing sense is often dated to the 1960s, but the exact paper and author are not settled.","cn":"计算机义项的首见常被定在二十世纪六十年代，但确切文献与作者尚无定论。"}]},"similar":{"note":{"en":"The first group shares the face or boundary idea; the second group names other meeting points between systems.","cn":"第一组共享「面」或「边界」的概念；第二组是系统之间其他类型的相接点。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"interfacial","ipa":"/ˌɪntəˈfeɪʃəl/","tag":"adjective","definition":"Relating to a boundary between phases; it describes the surface rather than naming it.","definitionCN":"与物相之间的边界有关的；描述该表面，而不是命名它。"},{"word":"surface","ipa":"/ˈsɜːfɪs/","tag":"base noun","definition":"The outer face of a body; the target word adds the idea of lying between two bodies.","definitionCN":"物体的外表面；目标词加上「位于两物之间」的意思。"},{"word":"face","ipa":"/feɪs/","tag":"source noun","definition":"The front or outer side; it is the English descendant of the Latin word inside interface.","definitionCN":"正面或外侧；是目标词内部那个拉丁词的英语后裔。"},{"word":"interfacing","ipa":"/ˈɪntəfeɪsɪŋ/","tag":"activity noun","definition":"The act of joining systems; it names the process rather than the boundary.","definitionCN":"把系统连接起来的动作；命名过程而不是边界。"}]},{"heading":"NEAR MEANING","entries":[{"word":"boundary","ipa":"/ˈbaʊndəri/","tag":"general noun","definition":"A line that separates two regions; it is wider and does not imply interaction.","definitionCN":"分隔两个区域的界线；范围更宽，且不暗示相互作用。"},{"word":"gateway","ipa":"/ˈɡeɪtweɪ/","tag":"network noun","definition":"A point that admits traffic into another network; a functional kind of interface.","definitionCN":"让流量进入另一网络的入口；是一种功能性的接口。"},{"word":"portal","ipa":"/ˈpɔːtəl/","tag":"web noun","definition":"A single page that gathers access to many services; it is a user-facing entry point, not a boundary standard.","definitionCN":"汇集多种服务入口的单一页面；是面向用户的入口，而非边界标准。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: two real Latin pieces and the modern technical phrases.","cn":"正常联想：两个真实拉丁成分与现代技术搭配。"},"normal":[{"en":"Inter means between and face means surface: the surface between two sides.","cn":"「之间」加「面」，就是两侧之间的那个面。"},{"en":"The family runs interface, interfacial, interfacing and interfaced.","cn":"同族词有界面、界面的、对接与已对接的。"},{"en":"Fixed phrases mark the user side: user interface and graphical user interface.","cn":"固定搭配标出用户一侧：用户界面与图形用户界面。"},{"en":"Fixed phrases mark the system side: application programming interface, interface design.","cn":"固定搭配标出系统一侧：应用程序编程接口、界面设计。"},{"en":"Chemistry keeps the oldest sense: the sharp line where water meets oil.","cn":"化学保留了最古老的义项：水与油相接的那条清晰界线。"}],"abstract":[{"en":"Picture a doorway that belongs to neither room but serves both.","cn":"想象一扇门，不属于任何一个房间，却为两边服务。"},{"en":"Picture two languages agreeing on a single hand signal at a border.","cn":"想象两种语言在边境约定同一个手势。"},{"en":"Picture a membrane through which two liquids exchange a single colour.","cn":"想象一层薄膜，两种液体隔着它交换一种颜色。"}]},"examples":[{"en":"The interface hides the complexity of the database behind simple buttons.","cn":"界面用简单的按钮把数据库的复杂性藏了起来。"},{"en":"A well-documented interface lets two teams work independently.","cn":"一个有良好文档的接口让两个团队可以独立工作。"},{"en":"The study examined the interface between climate and agriculture.","cn":"这项研究考察了气候与农业之间的相互作用。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「因特面」——互联网之间的那个面 → 界面、接口","word":"interface"},"root":"拉丁语「在……之间」加拉丁语「外形、表面」；十九世纪末指两物的交界面。","sensesIntro":{"en":"Eight senses all name a meeting surface: user screen, system boundary, material boundary, mechanical joint, channel of interaction, agreed protocol, graphical front end, and the verb of joining.","cn":"八个义项都指一个相接表面：用户屏幕、系统边界、材料分界、机械接合、交流通道、约定规范、图形前端，以及表示连接的动词。"},"semanticMap":{"core":{"en":"CORE IMAGE: a clear line where two different sides touch and exchange something.","cn":"核心意象：一条清晰的界线，两侧不同的事物在此相触并交换某物。"},"chain":["TWO SIDES","SHARED BOUNDARY","CONTACT POINT","USER AND MACHINE","SCREEN","PROTOCOL"],"branches":[{"senses":"01 · 07","en":"THE VISIBLE MEETING SURFACE: what a user sees, including the graphical version built from windows and icons.","cn":"可见的相接表面：用户所见的部分，包括由窗口与图标构成的图形版本。"},{"senses":"02 · 06","en":"THE RULED BOUNDARY: the standard connection and the documented rules that let separate systems work together.","cn":"有规则的边界：标准连接与成文规则，使彼此独立的系统协同工作。"},{"senses":"03 · 04","en":"THE PHYSICAL BOUNDARY: where two materials or machine parts meet.","cn":"物理边界：两种材料或机械部件相接之处。"},{"senses":"05","en":"THE SOCIAL CHANNEL: a meeting surface between fields, institutions or groups.","cn":"社会通道：领域、机构或群体之间的相接表面。"},{"senses":"08","en":"THE ACT OF JOINING: turning the meeting surface into a working connection.","cn":"连接的动作：把相接表面变成可工作的连接。"}]},"affixes":{"intro":{"en":"Interface is a hybrid of a Latin prefix and an English noun of Latin origin; both parts still build words.","cn":"这个词是拉丁前缀与源自拉丁语的英语名词的混合体；两部分至今都在构词。"},"latinIntro":{"en":"Latin supplies the prefix inter and the noun facies behind face, so real cognates appear in the list.","cn":"拉丁语提供了前缀「之间」与「面」背后的名词，因此列表中列出真实同族词。"},"items":[{"word":"inter-","structure":"Latin prefix meaning between","meaning":"between; among","meaningCN":"在……之间；在……之中","example":"The prefix places the surface between two sides.","exampleCN":"这个前缀把该表面放在两侧之间。"},{"word":"face","structure":"English noun from Latin facies","meaning":"a surface; an appearance","meaningCN":"表面；外观","example":"The second half supplies the surface in the image.","exampleCN":"后半提供了画面中的那个表面。"},{"word":"facies","structure":"Latin noun","meaning":"form, appearance, surface","meaningCN":"外形；外观；表面","example":"The Latin noun stands behind the English face.","exampleCN":"这个拉丁名词是英语「面」的来源。"},{"word":"interface","structure":"inter- plus face","meaning":"the surface between two sides","meaningCN":"两侧之间的表面","example":"The noun first named a physical boundary.","exampleCN":"这个名词最初指物理边界。"},{"word":"-ial","structure":"adjective ending","meaning":"relating to","meaningCN":"与……有关的","example":"Interfacial describes what happens at the boundary.","exampleCN":"「界面的」描述边界上发生的事。"},{"word":"-ing","structure":"action noun ending","meaning":"the act of joining","meaningCN":"连接的动作","example":"Interfacing is the work of making systems talk.","exampleCN":"「对接」是让系统对话的工作。"},{"word":"-ed","structure":"completed-state ending","meaning":"already joined","meaningCN":"已经对接的","example":"The interfaced modules share one clock.","exampleCN":"已对接的模块共享一个时钟。"},{"word":"surface","structure":"Latin superficies through French","meaning":"the outer face of a body","meaningCN":"物体的外表面","example":"Surface is the everyday word for one side of the boundary.","exampleCN":"「表面」是边界一侧的日常说法。"}],"latinEntries":[{"word":"inter","structure":"Latin preposition and prefix","meaning":"between, among","meaningCN":"在……之间；在……之中"},{"word":"facies","structure":"Latin noun","meaning":"form, appearance, surface","meaningCN":"外形；外观；表面"},{"word":"superficies","structure":"Latin noun","meaning":"the outer surface","meaningCN":"外表面"}],"derivatives":[{"word":"interfacial","pos":"adj.","zh":"由该名词加表示「属于」的形容词尾构成，义为「界面的、界面上的」"},{"word":"interfacing","pos":"n./adj.","zh":"由该动词加动作词尾构成，义为「对接；对接的」"},{"word":"interfaced","pos":"adj.","zh":"由该动词加已然词尾构成，义为「已对接的」"},{"word":"interfacially","pos":"adv.","zh":"由形容词加副词词尾构成，义为「在界面层面」"}]}},{"word":"automated","ipa_uk":"/ˈɔːtəmeɪtɪd/","ipa_us":"/ˈɔːtəmeɪtɪd/","definition_zh":"自动化的；自动运行的；由机器自动完成的","definition_en":"made to operate by machines or software with little or no human control","core_image":"深夜的车间里没有人，机械臂按程序依次抓取、焊接、放下，传送带不停地把成品送走","scene":"仓库的夜里只亮着几盏指示灯，分拣机器人按订单把包裹送进不同的滑道。An automated warehouse keeps working long after the staff have gone home.","sceneCN":"这里指由机器按程序自行运转、几乎不需要人操作的（第 1 个义项：自动运行的）；句意：自动化仓库在员工回家后仍持续运转。","pos":[{"tag":"adj.","zh":"自动化的；自动运行的"}],"collocations":[{"phrase":"automated system","zh":"自动化系统"},{"phrase":"automated process","zh":"自动化流程"},{"phrase":"automated warehouse","zh":"自动化仓库"},{"phrase":"fully automated","zh":"全自动的"},{"phrase":"automated driving","zh":"自动驾驶"},{"phrase":"automated response","zh":"自动回复"}],"forms":[{"label":"原级","form":"automated"},{"label":"动词原形","form":"automate"},{"label":"现在分词","form":"automating"},{"label":"名词","form":"automation"},{"label":"名词（自动装置）","form":"automaton"}],"derivatives":[{"word":"automate","pos":"v.","zh":"由该形容词回溯的动词形式，义为「使自动化」"},{"word":"automation","pos":"n.","zh":"由该动词加动作名词尾构成，义为「自动化」"},{"word":"automatic","pos":"adj.","zh":"由同一希腊词根构成，义为「自动的」"},{"word":"automatically","pos":"adv.","zh":"由「自动的」加副词词尾构成，义为「自动地」"},{"word":"automaton","pos":"n.","zh":"由希腊语「自行动作者」借入，义为「自动装置」"}],"senses":[{"no":"01","title":"Running by itself","titleCN":"自行运转","definition":"describing a machine or system that carries out its work without an operator","definitionCN":"指无需操作员即可完成工作的机器或系统","example":"The automated line runs through the night.","exampleCN":"这条自动化生产线通宵运转。","why":"The word is the past participle of a verb meaning to make self-acting, so it describes something already set to run itself.","whyCN":"这个词是「使自行运作」这一动词的过去分词，因此描述已被设定为自行运转的事物。"},{"no":"02","title":"Governed by a control system","titleCN":"由控制系统支配","definition":"describing equipment whose actions are directed by sensors and controllers rather than hands","definitionCN":"指动作由传感器与控制器而非人手指挥的设备","example":"An automated valve closes when the pressure rises.","exampleCN":"压力升高时，自动阀门会关闭。","why":"A control loop replaces the human hand, so the word also marks the system that does the governing.","whyCN":"控制回路替代了人手，因此这个词也标记执行支配的那个系统。"},{"no":"03","title":"Needing no human labour","titleCN":"不需要人力","definition":"describing a procedure completed without human effort or intervention","definitionCN":"指无需人力或人工干预即可完成的流程","example":"The automated check takes a second per file.","exampleCN":"自动检查每个文件只花一秒。","why":"If a task has no human step, its name shifts to the absence of labour, which is the practical meaning of automation.","whyCN":"若一项任务没有人的步骤，其名称就转向「没有人力」，这正是自动化的实际含义。"},{"no":"04","title":"Factory work done by machines","titleCN":"由机器完成的工厂作业","definition":"describing production in which machines handle materials and tools","definitionCN":"指由机器处理材料与工具的生产方式","example":"The automated plant employs half the staff it once did.","exampleCN":"这座自动化工厂的员工数只有过去的一半。","why":"Manufacturing was the first large field to adopt the word, so it became the standard label for machine-run production.","whyCN":"制造业最早大规模采用这个词，因此它成了机器化生产的标准标签。"},{"no":"05","title":"Mechanical and unthinking","titleCN":"机械而无意识的","definition":"describing behaviour that is repeated without thought, as if performed by a machine","definitionCN":"指不加思考地重复、仿佛由机器执行的行为","example":"His automated reply never changed a word.","exampleCN":"他那机械的回复一个字都没变过。","why":"When human actions copy machine regularity, the same word describes the loss of thought.","whyCN":"当人的行为复制机器的规律性，同一个词就描述思考的缺失。"},{"no":"06","title":"Generated without a person","titleCN":"无人参与而生成","definition":"describing a report, message or record produced by software rather than written by hand","definitionCN":"指由软件而非手工撰写的报告、信息或记录","example":"The automated report arrives every Monday at six.","exampleCN":"自动报告每周一六点送达。","why":"Output produced without an author is described by the same participle, extending the word from motion to text.","whyCN":"没有作者产出的内容也用同一个分词描述，把这个词从运动扩展到文本。"},{"no":"07","title":"Self-driving vehicles","titleCN":"自动驾驶车辆","definition":"describing a vehicle that steers and brakes without a human driver","definitionCN":"指无需人类驾驶即可转向与刹车的车辆","example":"The automated shuttle follows a fixed loop.","exampleCN":"这辆自动驾驶摆渡车沿固定环线行驶。","why":"Driving is a continuous control task, so a machine that takes it over is described by the same word.","whyCN":"驾驶是持续的控制任务，因此接管它的机器也用同一个词描述。"},{"no":"08","title":"Data handled by software","titleCN":"由软件处理的数据","definition":"describing data work such as sorting, checking or formatting done by a program","definitionCN":"指由程序完成的分拣、核对或格式化等数据工作","example":"Automated sorting cut the backlog in half.","exampleCN":"自动分拣把积压减少了一半。","why":"Software can repeat a data step far faster than people, so the participle also labels machine-run data work.","whyCN":"软件能比人快得多地重复数据步骤，因此这个分词也标记机器完成的数据工作。"}],"etymology":{"intro":{"en":"Automated descends from Greek autos, self, through automaton and automatic; the verb automate and its participle are modern.","cn":"这个词经「自动装置」「自动的」上溯到希腊语「自己」；动词与分词形式则是现代产物。"},"items":[{"era":"GREEK AUTOS","en":"Autos meant self, and its combining form auto- still begins many English words about self-action.","cn":"这个词意为「自己」，其组合形式至今出现在许多表示「自行」的英语词开头。"},{"era":"GREEK AUTOMATOS","en":"Automatos meant self-acting or self-moving, and it described things that move without an outside push.","cn":"这个词意为「自行动作、自行移动」，描述无需外力推动就会动的东西。"},{"era":"AUTOMATON","en":"English borrowed automaton in the seventeenth century for a machine that seems to move itself, such as a clockwork figure.","cn":"英语在十七世纪借入「自动装置」一词，指看似自行运动的机器，如发条人偶。"},{"era":"AUTOMATIC","en":"The adjective automatic extended the idea from clockwork toys to any mechanism that works by itself.","cn":"形容词「自动的」把这一观念从发条玩具扩展到任何自行工作的机械。"},{"era":"AUTOMATE AND AUTOMATION","en":"In the mid-twentieth century industry formed the verb automate and the noun automation for replacing human operation with machines.","cn":"二十世纪中叶，工业界造出动词「使自动化」与名词「自动化」，指用机器替代人工操作。"},{"era":"FIRST RECORD UNCERTAIN","en":"The first recorded use of the verb automate is generally placed in the mid-twentieth century, but the exact date and source are not established.","cn":"动词的首见一般定在二十世纪中叶，但确切年代与出处尚未确证。"}]},"similar":{"note":{"en":"The first group shares the self-acting stem; the second group describes machine-run work with other emphases.","cn":"第一组共享「自行动作」的词干；第二组以其他侧重描述机器完成的工作。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"automatic","ipa":"/ˌɔːtəˈmætɪk/","tag":"adjective","definition":"Working by itself; it is the older and broader adjective, while the target word often implies a process already converted.","definitionCN":"自行工作的；是更早更宽的形容词，而目标词常暗示流程已被改造完成。"},{"word":"automate","ipa":"/ˈɔːtəmeɪt/","tag":"verb","definition":"To convert a process to machine operation; the target word is its completed participle.","definitionCN":"把流程改为机器操作；目标词是它的已完成分词。"},{"word":"automation","ipa":"/ˌɔːtəˈmeɪʃən/","tag":"noun","definition":"The process or state of replacing human work with machines.","definitionCN":"用机器替代人工的过程或状态。"},{"word":"automatically","ipa":"/ˌɔːtəˈmætɪkli/","tag":"adverb","definition":"In a self-acting way; it modifies the action rather than describing the system.","definitionCN":"以自行运作的方式；修饰动作，而不是描述系统。"}]},{"heading":"NEAR MEANING","entries":[{"word":"mechanized","ipa":"/mɪˈkænɪzd/","tag":"adjective","definition":"Equipped with machinery; it stresses the machines themselves more than the removal of human control.","definitionCN":"配备了机械的；更强调机器本身，而不是人控制的消失。"},{"word":"unmanned","ipa":"/ˌʌnˈmænd/","tag":"adjective","definition":"Operating without a crew; it is used mainly of vehicles and craft.","definitionCN":"无乘员运行的；主要用于交通工具与飞行器。"},{"word":"programmed","ipa":"/ˈprəʊɡræmd/","tag":"adjective","definition":"Set in advance by instructions; it stresses the instructions rather than the absence of people.","definitionCN":"由指令预先设定的；强调指令，而不是人的缺席。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek root and the real automation family.","cn":"正常联想：真实的希腊词根与真实的自动化词族。"},"normal":[{"en":"Autos means self, so automated means made to act by itself.","cn":"「自己」加动作，自动化的就是被设定为自行运作的。"},{"en":"The family runs automate, automated, automation, automatic and automatically.","cn":"同族词有使自动化、自动化的、自动化、自动的与自动地。"},{"en":"Fixed phrases mark the system: automated system, automated process, fully automated.","cn":"固定搭配标出系统：自动化系统、自动化流程、全自动的。"},{"en":"Fixed phrases mark the application: automated warehouse, automated driving, automated response.","cn":"固定搭配标出应用：自动化仓库、自动驾驶、自动回复。"},{"en":"The clockwork figure is the ancestor image: a body that moves without being pushed.","cn":"发条人偶是祖先画面：没有被推却会动的人形。"}],"abstract":[{"en":"Picture a factory where the lights stay on but no footsteps are heard.","cn":"想象一座工厂，灯一直亮着，却听不到脚步声。"},{"en":"Picture a hand that writes the same letter a thousand times without ever looking up.","cn":"想象一只手写同一个字母一千遍，从不抬头。"},{"en":"Picture a clock that winds itself whenever the weight falls.","cn":"想象一座钟，重锤下落时它就给自己上弦。"}]},"examples":[{"en":"The automated gate opens only for registered cars.","cn":"自动闸门只对登记过的车辆开放。"},{"en":"Fully automated factories still need engineers for repairs.","cn":"全自动工厂仍需工程师维修。"},{"en":"The automated email went to thousands of customers by mistake.","cn":"那封自动邮件被误发给了数千名客户。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「奥托」自己会动——奥托是个不用人推的机器 → 自动化的","word":"automated"},"root":"希腊语「自己」加表示「自行动作」的希腊语形式；经「自动装置」「自动的」进入英语。","sensesIntro":{"en":"Eight senses follow self-action from machines to control systems, labour, factories, human habit, generated text, driving and data work.","cn":"八个义项沿着「自行动作」展开：机器、控制系统、人力、工厂、人的习惯、生成的文本、驾驶与数据工作。"},"semanticMap":{"core":{"en":"CORE IMAGE: a mechanism that begins to work without a hand on it.","cn":"核心意象：一台没有手去触碰却开始工作的机械。"},"chain":["SELF","SELF-ACTING","MACHINE","PROGRAM","NO OPERATOR","CONTINUOUS RUN"],"branches":[{"senses":"01 · 04","en":"THE MACHINE ITSELF: a line or a plant that runs without an operator.","cn":"机器本身：无需操作员即可运转的生产线或工厂。"},{"senses":"02","en":"THE GOVERNOR: sensors and controllers that steer the equipment.","cn":"支配者：操纵设备的传感器与控制器。"},{"senses":"03 · 08","en":"THE WORK WITHOUT HANDS: procedures and data steps completed by software.","cn":"无需人手的工作：由软件完成的流程与数据步骤。"},{"senses":"05","en":"THE HUMAN IMITATION: behaviour repeated without thought, like a machine.","cn":"人的模仿：不加思考地重复、形同机器的行为。"},{"senses":"06 · 07","en":"SELF-PRODUCED OUTPUT AND SELF-DRIVEN MOVEMENT: generated reports, and vehicles that steer themselves.","cn":"自生成的产出与自驱动的移动：自动生成的报告，以及自行转向的车辆。"}]},"affixes":{"intro":{"en":"Automated is a Greek-rooted word wearing English endings; its stem reaches English through three separate borrowings.","cn":"这个词以希腊语为词根，披着英语词尾；其词干通过三次独立借入进入英语。"},"latinIntro":{"en":"The root is Greek, not Latin; Latin contributed only the shape of the adjective ending, so no Latin cognate of the root is listed.","cn":"词根来自希腊语而非拉丁语；拉丁语只提供了形容词词尾的形式，因此不列出该词根的拉丁同族词。"},"items":[{"word":"autos","structure":"Greek pronoun used as a combining form","meaning":"self","meaningCN":"自己","example":"The root supplies the self in self-acting.","exampleCN":"这个词根提供「自行」中的那个「自」。"},{"word":"automatos","structure":"Greek adjective","meaning":"self-acting, self-moving","meaningCN":"自行动作的；自行移动的","example":"The adjective describes what moves without an outside push.","exampleCN":"这个形容词描述无需外力推动就会动的东西。"},{"word":"automaton","structure":"Greek noun borrowed into English","meaning":"a self-moving machine","meaningCN":"自行运动的机器","example":"The clockwork figure was the first English automaton.","exampleCN":"发条人偶是英语中最早的自动装置。"},{"word":"automatic","structure":"automatos plus the adjective ending","meaning":"working by itself","meaningCN":"自行工作的","example":"The adjective widened the idea beyond toys.","exampleCN":"这个形容词把观念扩展到玩具之外。"},{"word":"automate","structure":"back-formed verb from automation","meaning":"to make a process self-acting","meaningCN":"使流程自动运行","example":"Factories automate the steps people used to repeat.","exampleCN":"工厂把人过去重复的步骤自动化。"},{"word":"-ed","structure":"past-participle ending","meaning":"already made to act","meaningCN":"已被设定为运作的","example":"The ending marks a process already converted.","exampleCN":"这个词尾标记流程已被改造完成。"},{"word":"-ion","structure":"action noun ending","meaning":"the process of converting","meaningCN":"改造的过程","example":"Automation names the whole change, not one machine.","exampleCN":"「自动化」指整个转变，而不是某一台机器。"},{"word":"-ally","structure":"adverb ending","meaning":"in the stated manner","meaningCN":"以所述方式","example":"The system restarts automatically after a fault.","exampleCN":"系统在故障后自动重启。"}],"latinEntries":[],"derivatives":[{"word":"automate","pos":"v.","zh":"由该形容词回溯的动词形式，义为「使自动化」"},{"word":"automation","pos":"n.","zh":"由该动词加动作名词尾构成，义为「自动化」"},{"word":"automatic","pos":"adj.","zh":"由同一希腊词根构成，义为「自动的」"},{"word":"automatically","pos":"adv.","zh":"由「自动的」加副词词尾构成，义为「自动地」"},{"word":"automaton","pos":"n.","zh":"由希腊语「自行动作者」借入，义为「自动装置」"}]}},{"word":"artificial intelligence","ipa_uk":"/ˌɑːtɪfɪʃl ɪnˈtelɪdʒəns/","ipa_us":"/ˌɑːrtɪfɪʃl ɪnˈtelɪdʒəns/","definition_zh":"人工智能；人工智能系统与技术","definition_en":"the field of building computer systems that perform tasks requiring intelligence, such as reasoning, learning or language use","core_image":"实验室里，屏幕上的程序正在辨认照片中的猫，它不断调整内部权重，判断越来越准","scene":"研究者把上万张标注好的图片喂给程序，几轮训练后，它已能在新照片里认出同样的动物。Artificial intelligence here means a system that learns from examples.","sceneCN":"这里指能从样例中学习并完成识别等智能任务的技术系统（第 1 个义项：人工智能技术与系统）；句意：此处的人工智能指从样例中学习的系统。","pos":[{"tag":"n.","zh":"人工智能；智能系统"}],"collocations":[{"phrase":"artificial intelligence research","zh":"人工智能研究"},{"phrase":"artificial intelligence system","zh":"人工智能系统"},{"phrase":"artificial general intelligence","zh":"通用人工智能"},{"phrase":"artificial intelligence technology","zh":"人工智能技术"},{"phrase":"applied artificial intelligence","zh":"应用人工智能"},{"phrase":"artificial intelligence model","zh":"人工智能模型"}],"forms":[{"label":"全称","form":"artificial intelligence"},{"label":"缩略形式","form":"AI"},{"label":"定语用法","form":"artificial-intelligence"},{"label":"复数（指多个系统）","form":"artificial intelligences"}],"derivatives":[{"word":"artificial","pos":"adj.","zh":"复合词前半，源自拉丁语「技艺」，义为「人工的」"},{"word":"artificially","pos":"adv.","zh":"由「人工的」加副词词尾构成，义为「人工地」"},{"word":"intelligence","pos":"n.","zh":"复合词后半，源自拉丁语「理解」，义为「智力、情报」"},{"word":"intelligent","pos":"adj.","zh":"由同一词干加形容词尾构成，义为「聪明的」"},{"word":"intelligently","pos":"adv.","zh":"由「聪明的」加副词词尾构成，义为「聪明地」"}],"senses":[{"no":"01","title":"The field and its technology","titleCN":"学科与技术","definition":"the research field and body of methods that make machines perform intelligent tasks","definitionCN":"使机器完成智能任务的研究领域与方法体系","example":"Artificial intelligence grew out of early computing and logic.","exampleCN":"人工智能从早期计算与逻辑学中发展而来。","why":"The name joins what is made by art with the capacity to understand, and the pair names a whole discipline.","whyCN":"这个名称把「人工制造」与「理解能力」结合，二者合起来命名一整门学科。"},{"no":"02","title":"A working system or program","titleCN":"可运行的系统或程序","definition":"a particular computer system that carries out tasks such as recognition, planning or dialogue","definitionCN":"执行识别、规划或对话等任务的特定计算机系统","example":"The hospital's artificial intelligence flags risky scans overnight.","exampleCN":"医院的人工智能系统连夜标出有风险的扫描。","why":"The field name transfers to any product of the field, so one program can be called an artificial intelligence.","whyCN":"领域名称转移到该领域的任一产物，因此单个程序也能被称为人工智能。"},{"no":"03","title":"Machine capability itself","titleCN":"机器智能能力本身","definition":"the capacity of a machine to reason, learn or understand, considered as a property","definitionCN":"机器推理、学习或理解的能力，被看作一种属性","example":"The debate asks whether artificial intelligence can ever be general.","exampleCN":"争论在于人工智能能否达到通用水平。","why":"Speakers often abstract the field into a single capability, the way one speaks of intelligence in people.","whyCN":"说话人常把整个领域抽象成一种能力，就像谈论人的智力一样。"},{"no":"04","title":"The industry and its market","titleCN":"产业与市场","definition":"the companies, products and investment gathered around these technologies","definitionCN":"围绕这些技术形成的公司、产品与投资","example":"Artificial intelligence now attracts a large share of venture money.","exampleCN":"人工智能如今吸引了很大一部分风险投资。","why":"An active technology with its own market is named by the same phrase, as with any industry label.","whyCN":"拥有自身市场的活跃技术沿用同一说法命名，如同任何产业标签。"},{"no":"05","title":"General intelligence in a machine","titleCN":"机器中的通用智能","definition":"a hypothetical system able to handle any intellectual task a person can","definitionCN":"一种假想系统，能处理人可以完成的任何智力任务","example":"Artificial intelligence researchers disagree about when general systems will arrive.","exampleCN":"人工智能研究者对通用系统何时到来意见不一。","why":"If the phrase can name a capability, it can also name the strongest version of that capability.","whyCN":"若这个说法能命名一种能力，也就能命名该能力最强的版本。"},{"no":"06","title":"Narrow, task-specific systems","titleCN":"专用、任务限定的系统","definition":"systems built for one domain, such as translation or medical imaging, with no wider understanding","definitionCN":"为单一领域如翻译或医学影像而建、没有更广理解力的系统","example":"Most artificial intelligence in use today is narrow.","exampleCN":"如今在用的绝大多数人工智能都是专用型的。","why":"The same phrase covers the modest systems that actually exist, not only the ambitious ones.","whyCN":"同一个说法也涵盖现实中存在的、规模有限的系统，而不只是宏大设想的系统。"},{"no":"07","title":"Everyday applications","titleCN":"日常应用","definition":"consumer features such as assistants, recommendations and filters that rely on these methods","definitionCN":"依赖这些方法的语音助手、推荐与筛选等消费功能","example":"Artificial intelligence decides which posts appear at the top of the feed.","exampleCN":"人工智能决定哪些帖子出现在信息流顶部。","why":"Once the methods reach ordinary products, the phrase becomes a label for the experience rather than the research.","whyCN":"当方法进入普通产品，这个说法就成了对体验的标签，而不只是研究。"},{"no":"08","title":"An embodied agent","titleCN":"具身的智能体","definition":"a named agent, such as a robot or a software assistant, treated as an intelligent actor","definitionCN":"被当作智能行动者的具名主体，如机器人或软件助手","example":"The artificial intelligence negotiates prices with another agent.","exampleCN":"这个智能体与另一个智能体谈价格。","why":"When a system acts with goals and memory, speakers treat it as an agent rather than a tool.","whyCN":"当系统带着目标与记忆行动，说话人就把它当作行动者而不是工具。"}],"etymology":{"intro":{"en":"Artificial intelligence joins Latin artificium, craftsmanship, and Latin intelligentia, understanding; the phrase became a discipline name in 1956.","cn":"这个短语把拉丁语「技艺之作」与「理解」结合；1956 年它成为一门学科的名称。"},"items":[{"era":"LATIN ARS","en":"Ars meant skill or craft, and it is the source of the first half of artificial.","cn":"这个词意为技艺或手艺，是「人工的」前半部分的来源。"},{"era":"LATIN FACERE","en":"Facere meant to make, and with ars it produced artifex, a maker, and artificium, a made thing.","cn":"这个词意为「做、制作」，与「技艺」结合产生「制作者」与「制作物」。"},{"era":"LATIN INTELLIGERE","en":"Intelligere meant to understand, built from inter, between, and legere, to choose or gather.","cn":"这个词意为「理解」，由「之间」与「挑选、收集」构成。"},{"era":"ENGLISH ARTIFICIAL","en":"English artificial first meant made by craft rather than by nature, a sense it still carries.","cn":"英语「人工的」最初指由技艺而非自然造成，这一义项延续至今。"},{"era":"DARTMOUTH 1956","en":"A summer workshop at Dartmouth College adopted the phrase for the new field of machine reasoning and learning.","cn":"达特茅斯学院的一次暑期研讨会采用这个短语，命名机器推理与学习的新领域。"},{"era":"COINAGE ATTRIBUTION UNCERTAIN","en":"The workshop is generally credited with fixing the term, but credit for first coining it is shared among several participants and is not fully settled.","cn":"该研讨会一般被认为确立了这一术语，但「谁最先造出它」的功劳由数位参与者共享，尚无定论。"}]},"similar":{"note":{"en":"The first group shares one half of the phrase; the second group names neighbouring machine-intelligence ideas.","cn":"第一组共享短语的一半；第二组是相邻的机器智能概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"artificial","ipa":"/ˌɑːtɪˈfɪʃl/","tag":"first half","definition":"Made by craft rather than nature; alone it says nothing about intelligence.","definitionCN":"由技艺而非自然造成；单独使用时并不涉及智能。"},{"word":"intelligence","ipa":"/ˌɪnˈtelɪdʒəns/","tag":"second half","definition":"The capacity to understand and reason; in other contexts it also means gathered information.","definitionCN":"理解与推理的能力；在其他语境中也指收集到的情报。"},{"word":"intelligent","ipa":"/ˌɪnˈtelɪdʒənt/","tag":"adjective","definition":"Having the capacity to understand; the phrase names the machine version of this quality.","definitionCN":"具备理解能力的；短语命名的是这一品质在机器上的版本。"},{"word":"artificially","ipa":"/ˌɑːtɪˈfɪʃli/","tag":"adverb","definition":"By craft rather than nature; it modifies an action, not a system.","definitionCN":"以人工方式而非自然方式；修饰动作，而不是系统。"}]},{"heading":"NEAR MEANING","entries":[{"word":"machine intelligence","ipa":"/məˈʃiːn ɪnˈtelɪdʒəns/","tag":"parallel term","definition":"Intelligence in machines, a phrase that stresses the hardware rather than the made-by-craft contrast.","definitionCN":"机器中的智能，强调硬件，而不是「人工制造」这一对照。"},{"word":"automation","ipa":"/ˌɔːtəˈmeɪʃən/","tag":"wider practice","definition":"Replacing human operation with machines; it need not involve learning or reasoning.","definitionCN":"用机器替代人工操作；不一定涉及学习或推理。"},{"word":"cognitive computing","ipa":"/ˈkɒɡnɪtɪv kəmˈpjuːtɪŋ/","tag":"industry term","definition":"Computing built to imitate human perception and reasoning, a commercial cousin of the academic phrase.","definitionCN":"模仿人类感知与推理的计算方式，是学术说法在商业上的近亲。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: two real Latin stems and the real discipline history.","cn":"正常联想：两个真实拉丁词干与真实的学科史。"},"normal":[{"en":"Artificial means made by craft, intelligence means the power to understand: made understanding.","cn":"「人工的」意为由技艺造成，「智力」意为理解能力，合起来就是「造出来的理解力」。"},{"en":"The family runs artificial, artificially, intelligence, intelligent and intelligently.","cn":"同族词有人工的、人工地、智力、聪明的与聪明地。"},{"en":"Fixed phrases mark the goal: artificial general intelligence and narrow systems.","cn":"固定搭配标出目标：通用人工智能与专用系统。"},{"en":"Fixed phrases mark the work: artificial intelligence research, systems, models and applications.","cn":"固定搭配标出工作：人工智能研究、系统、模型与应用。"},{"en":"A 1956 summer workshop at Dartmouth gave the field its public name.","cn":"1956 年达特茅斯的一次暑期研讨会给了这个领域公开的名称。"}],"abstract":[{"en":"Picture a clay figure that begins to answer questions about the clay.","cn":"想象一个泥塑人形，开始回答关于泥土的问题。"},{"en":"Picture a mirror that does not reflect a face but predicts the next expression.","cn":"想象一面镜子不映出脸，却预测下一个表情。"},{"en":"Picture a library that reads its own shelves and suggests what to add.","cn":"想象一座图书馆会读自己的书架，并建议该添什么书。"}]},"examples":[{"en":"Artificial intelligence has changed how medical images are screened.","cn":"人工智能改变了医学影像的筛查方式。"},{"en":"The course covers both artificial intelligence and its ethical limits.","cn":"这门课程同时涵盖人工智能及其伦理边界。"},{"en":"Many artificial intelligence systems fail when the data shift.","cn":"许多人工智能系统在数据分布变化时失效。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「人工」造出来的「智力」——机器学会看懂、听懂、想明白","word":"artificial intelligence"},"root":"拉丁语「技艺之作」加拉丁语「理解」；1956 年成为学科名。","sensesIntro":{"en":"Eight senses move from the discipline to a program, a capability, an industry, the general dream, narrow reality, daily applications and an acting agent.","cn":"八个义项从学科出发，依次落到程序、能力、产业、通用设想、专用现实、日常应用与行动主体。"},"semanticMap":{"core":{"en":"CORE IMAGE: a made thing that begins to recognize, reason and learn.","cn":"核心意象：一件被造出来的东西开始识别、推理与学习。"},"chain":["MADE BY CRAFT","CAPACITY TO UNDERSTAND","MACHINE","DATA AND PATTERNS","DECISION","INTELLIGENT BEHAVIOUR"],"branches":[{"senses":"01","en":"THE DISCIPLINE: the field and its methods, the anchor sense.","cn":"学科：领域及其方法，是锚定义项。"},{"senses":"02 · 08","en":"THE THING THAT ACTS: a working program, and an agent treated as an actor with goals.","cn":"行动的实体：可运行的程序，以及被当作有目标的行动者的智能体。"},{"senses":"03 · 05","en":"THE CAPABILITY AND ITS STRONGEST FORM: machine intelligence in general, and the hypothetical general system.","cn":"能力及其最强形式：一般的机器智能，以及假想的通用系统。"},{"senses":"04 · 07","en":"THE MARKET AND THE EVERYDAY: an industry, and the consumer features it quietly powers.","cn":"市场与日常：一个产业，以及它在背后默默驱动的消费功能。"},{"senses":"06","en":"THE HONEST PRESENT: narrow systems built for one task and no wider understanding.","cn":"诚实的当下：为单一任务而建、没有更广理解的专用系统。"}]},"affixes":{"intro":{"en":"The phrase is built entirely from Latin stems, with English adjective and noun endings.","cn":"这个短语完全由拉丁词干构成，外面是英语的形容词与名词词尾。"},"latinIntro":{"en":"Both halves are Latin in origin, so the Latin list holds the real source nouns and verbs.","cn":"两半都源自拉丁语，因此拉丁词条列出真实的来源名词与动词。"},"items":[{"word":"ars","structure":"Latin noun","meaning":"skill, craft","meaningCN":"技艺；手艺","example":"The first half begins with the Latin word for craft.","exampleCN":"前半部分始于拉丁语表示「技艺」的词。"},{"word":"facere","structure":"Latin verb","meaning":"to make, to do","meaningCN":"制作；做","example":"With craft, it produced the maker and the made thing.","exampleCN":"与「技艺」结合，产生了制作者与制作物。"},{"word":"artificium","structure":"Latin noun from artifex","meaning":"a made thing; craftsmanship","meaningCN":"制作物；技艺","example":"The noun is the direct ancestor of artificial.","exampleCN":"这个名词是「人工的」的直接祖先。"},{"word":"intelligere","structure":"inter- plus legere","meaning":"to understand","meaningCN":"理解","example":"The verb literally pictures choosing between things.","exampleCN":"这个动词字面上描绘在事物之间作挑选。"},{"word":"intelligentia","structure":"Latin noun from intelligere","meaning":"understanding, intelligence","meaningCN":"理解；智力","example":"The second half supplies the capacity to understand.","exampleCN":"后半提供理解的能力。"},{"word":"-al","structure":"adjective ending","meaning":"relating to","meaningCN":"与……有关的","example":"The ending turns the craft noun into an adjective.","exampleCN":"这个词尾把技艺名词变成形容词。"},{"word":"-ence","structure":"noun ending of state","meaning":"the state or quality","meaningCN":"状态或性质","example":"The ending turns the verb into a noun of capacity.","exampleCN":"这个词尾把动词变成表示能力的名词。"},{"word":"artificial intelligence","structure":"the two Latin stems combined in English","meaning":"machine intelligence made by craft","meaningCN":"由技艺造出的机器智能","example":"The phrase was fixed as a field name in 1956.","exampleCN":"这个短语在 1956 年被定为领域名称。"},{"word":"AI","structure":"initial letters of the phrase","meaning":"the shortened field name","meaningCN":"该领域名称的缩略","example":"The abbreviation appears in both research and products.","exampleCN":"这一缩略形式在研究与本产品中都出现。"},{"word":"artificially","structure":"artificial plus the adverb ending","meaning":"by craft, not by nature","meaningCN":"以人工方式，而非自然地","example":"The adverb marks the contrast with natural things.","exampleCN":"这个副词标记与自然事物的对照。"}],"latinEntries":[{"word":"ars","structure":"Latin noun","meaning":"skill, craft","meaningCN":"技艺；手艺"},{"word":"artificium","structure":"Latin noun","meaning":"craftsmanship; a made thing","meaningCN":"技艺；制作物"},{"word":"intelligentia","structure":"Latin noun","meaning":"understanding, intelligence","meaningCN":"理解；智力"},{"word":"intelligere","structure":"Latin verb","meaning":"to understand","meaningCN":"理解"}],"derivatives":[{"word":"artificial","pos":"adj.","zh":"复合词前半，源自拉丁语「技艺」，义为「人工的」"},{"word":"artificially","pos":"adv.","zh":"由「人工的」加副词词尾构成，义为「人工地」"},{"word":"intelligence","pos":"n.","zh":"复合词后半，源自拉丁语「理解」，义为「智力、情报」"},{"word":"intelligent","pos":"adj.","zh":"由同一词干加形容词尾构成，义为「聪明的」"},{"word":"intelligently","pos":"adv.","zh":"由「聪明的」加副词词尾构成，义为「聪明地」"}]}},{"word":"machine learning","ipa_uk":"/məˈʃiːn ˈlɜːnɪŋ/","ipa_us":"/məˈʃiːn ˈlɜːrnɪŋ/","definition_zh":"机器学习；让程序从数据中总结规律并自行改进的方法","definition_en":"the branch of computing in which programs improve their performance by learning patterns from data rather than by following fixed instructions","core_image":"一摞标注着「垃圾邮件」与「正常邮件」的信件被送进程序，程序反复调整分类边界，直到新邮件也能被正确分开","scene":"系统先看了几千封已标记的邮件，随后开始自动把可疑邮件拦在收件箱外。Machine learning improves the filter without anyone rewriting its rules.","sceneCN":"这里指让程序从标注数据中总结规律、自行改进的技术（第 1 个义项：机器学习方法）；句意：机器学习让过滤器无需人工改写规则就变得更准。","pos":[{"tag":"n.","zh":"机器学习；数据驱动的学习方法"}],"collocations":[{"phrase":"machine learning model","zh":"机器学习模型"},{"phrase":"machine learning algorithm","zh":"机器学习算法"},{"phrase":"supervised machine learning","zh":"监督式机器学习"},{"phrase":"machine learning system","zh":"机器学习系统"},{"phrase":"machine learning research","zh":"机器学习研究"},{"phrase":"machine learning technique","zh":"机器学习技术"}],"forms":[{"label":"名词（不可数）","form":"machine learning"},{"label":"定语用法","form":"machine-learning"},{"label":"相关名词","form":"learner"},{"label":"相关复合形容词","form":"machine-learned"}],"derivatives":[{"word":"machine","pos":"n.","zh":"复合词前半，源自拉丁语「机械」，义为「机器」"},{"word":"learn","pos":"v.","zh":"复合词后半的词根，古英语意为「获得知识」"},{"word":"learner","pos":"n.","zh":"由「学习」的动词加施动者词尾构成，义为「学习者」"},{"word":"learning","pos":"n.","zh":"由「学习」的动词加动作名词尾构成，义为「学习过程」"},{"word":"machine-learned","pos":"adj.","zh":"由前半名词与「已学习」的分词复合，义为「机器习得的」"}],"senses":[{"no":"01","title":"The discipline of learning from data","titleCN":"从数据中学习的学科","definition":"the field that studies how programs can improve from examples, data or experience","definitionCN":"研究程序如何从样例、数据或经验中改进的领域","example":"Machine learning sits between statistics and computer science.","exampleCN":"机器学习处在统计学与计算机科学之间。","why":"A machine does not learn by instruction alone, so the phrase names the branch where data does the teaching.","whyCN":"机器的学习不能只靠指令，因此这个短语命名「由数据来教」的那一分支。"},{"no":"02","title":"A trained model or system","titleCN":"训练好的模型或系统","definition":"a particular model or deployed system produced by this method","definitionCN":"用这种方法产出的特定模型或已部署系统","example":"The machine learning model flags unusual transactions.","exampleCN":"这个机器学习模型标记异常交易。","why":"The field name transfers to its products, so a trained model is called a machine learning model.","whyCN":"领域名称转移到其产物，因此训练好的模型被称为机器学习模型。"},{"no":"03","title":"The process of improving from examples","titleCN":"从样例中改进的过程","definition":"the act of adjusting a model as more examples are seen","definitionCN":"随着看到更多样例而调整模型的行为","example":"Machine learning happens in cycles of prediction and correction.","exampleCN":"机器学习在预测与纠错的循环中发生。","why":"The phrase also names the activity itself, because the improvement is what the program is doing.","whyCN":"这个短语也指活动本身，因为「改进」正是程序在做的事。"},{"no":"04","title":"Supervised learning","titleCN":"监督式学习","definition":"learning from examples that carry the correct answer","definitionCN":"从带有正确答案的样例中学习","example":"Supervised machine learning needs carefully labelled data.","exampleCN":"监督式机器学习需要仔细标注的数据。","why":"When every example comes with an answer, the program learns under supervision, and the branch name makes that explicit.","whyCN":"当每个样例都附带答案，程序就在「监督」下学习，分支名称把这一点说明。"},{"no":"05","title":"Unsupervised learning","titleCN":"无监督式学习","definition":"learning patterns from examples that carry no answer","definitionCN":"从没有答案的样例中学习规律","example":"Unsupervised machine learning grouped the customers by behaviour.","exampleCN":"无监督式机器学习按行为把顾客分了组。","why":"Without labels the program must find its own structure, so the contrast with supervision gives this sense its name.","whyCN":"没有标签时程序必须自行发现结构，与「监督」的对照便给了这一义项名称。"},{"no":"06","title":"Reinforcement learning","titleCN":"强化学习","definition":"learning by acting and receiving rewards or penalties","definitionCN":"通过行动并接受奖励或惩罚而学习","example":"Reinforcement machine learning taught the robot to walk.","exampleCN":"强化式机器学习教会了机器人走路。","why":"When the signal is a reward rather than an answer, learning happens through trial, and the third branch is named.","whyCN":"当信号是奖励而不是答案，学习通过试错发生，于是有了第三个分支名称。"},{"no":"07","title":"Applied products and features","titleCN":"实际应用与功能","definition":"consumer or industrial uses built on these methods","definitionCN":"建立在这些方法上的消费或工业用途","example":"Machine learning now ranks most of what we read online.","exampleCN":"机器学习如今决定了我们在网上读到的大部分内容的排序。","why":"Once the method powers products, the phrase becomes a label for the application rather than the research.","whyCN":"当方法驱动产品，这个短语就成了应用的标签，而不只是研究。"},{"no":"08","title":"The training pipeline","titleCN":"训练流程","definition":"the end-to-end procedure of collecting data, training and evaluating a model","definitionCN":"收集数据、训练与评估模型的端到端流程","example":"The team rebuilt its machine learning pipeline around clean data.","exampleCN":"团队围绕干净数据重建了机器学习流程。","why":"A working system needs more than an algorithm, so the phrase also covers the whole pipeline that produces it.","whyCN":"一个可用系统不只需要算法，因此这个短语也涵盖产出它的整套流程。"}],"etymology":{"intro":{"en":"Machine learning joins Latin machina, a device, and Old English leornian, to learn; the phrase was coined in the twentieth century for programs that improve from data.","cn":"这个短语把拉丁语「机械」与古英语「学习」结合；二十世纪用它命名从数据中改进的程序。"},"items":[{"era":"GREEK MEKHANE","en":"The Greek word for a device or contrivance passed into Latin as machina.","cn":"希腊语中表示装置或巧妙构造的词传入拉丁语，成为「机械」。"},{"era":"LATIN MACHINA","en":"Machina named a structure or engine, and English machine descends from it through French.","cn":"这个词指结构或机械，英语「机器」经法语由它而来。"},{"era":"OLD ENGLISH LEORNIAN","en":"Leornian meant to gain knowledge, and learning has named that process for over a thousand years.","cn":"这个词意为获得知识，「学习」一词指这一过程已有一千多年。"},{"era":"MID-TWENTIETH CENTURY","en":"Researchers studying pattern recognition and games began to speak of machines that learn from experience.","cn":"研究模式识别与博弈的学者开始谈论「从经验中学习的机器」。"},{"era":"SAMUEL 1959","en":"A widely cited checkers program was described as a machine learning procedure, fixing the phrase in computing.","cn":"一个被广泛引用的跳棋程序被描述为机器学习过程，这个短语由此在计算机领域固定下来。"},{"era":"ATTRIBUTION UNCERTAIN","en":"The 1959 attribution is generally accepted but not fully settled, since several groups used similar wording in the same decade.","cn":"1959 年这一归属为一般接受，但尚无定论，因为同一十年里还有数个团队使用类似说法。"}]},"similar":{"note":{"en":"The first group shares one half of the phrase; the second group names neighbouring data-driven methods.","cn":"第一组共享短语的一半；第二组是相邻的数据驱动方法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"machine","ipa":"/məˈʃiːn/","tag":"first half","definition":"A device that performs work; alone it says nothing about learning.","definitionCN":"执行工作的装置；单独使用时不涉及学习。"},{"word":"learning","ipa":"/ˈlɜːnɪŋ/","tag":"second half","definition":"The process of gaining knowledge; in the phrase it is the machine that does it.","definitionCN":"获得知识的过程；在短语中执行它的是机器。"},{"word":"learner","ipa":"/ˈlɜːnə/","tag":"person or model noun","definition":"One that learns; in this field it can also name the model being trained.","definitionCN":"学习的主体；在这一领域也可指被训练的模型。"},{"word":"machine-learned","ipa":"/məˈʃiːn lɜːnd/","tag":"adjective","definition":"Produced by machine learning; it describes the result rather than the field.","definitionCN":"由机器学习产出的；描述结果而不是领域。"}]},{"heading":"NEAR MEANING","entries":[{"word":"deep learning","ipa":"/diːp ˈlɜːnɪŋ/","tag":"subfield","definition":"Machine learning with many-layered networks; a part of the wider field, not a synonym.","definitionCN":"使用多层网络的机器学习；是更广领域的一部分，并非同义词。"},{"word":"data mining","ipa":"/ˈdeɪtə ˈmaɪnɪŋ/","tag":"neighbouring practice","definition":"Searching large datasets for patterns; it may use learning but aims at discovery rather than prediction.","definitionCN":"在大数据集中寻找规律；可能使用学习，但目标是发现而非预测。"},{"word":"statistical modeling","ipa":"/stəˈtɪstɪkl ˈmɒdəlɪŋ/","tag":"older discipline","definition":"Describing data with probability models; it supplies much of the theory behind learning.","definitionCN":"用概率模型描述数据；为学习提供大量理论基础。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: two real stems and real branch names.","cn":"正常联想：两个真实词干与真实分支名称。"},"normal":[{"en":"Machine plus learning: the machine is the student, and data is the teacher.","cn":"「机器」加「学习」：机器是学生，数据是老师。"},{"en":"The family runs machine, learn, learner, learning and machine-learned.","cn":"同族词有机器、学习、学习者、学习过程与机器习得的。"},{"en":"Fixed phrases mark the product: machine learning model, system, technique.","cn":"固定搭配标出产物：机器学习模型、系统、技术。"},{"en":"Three branch names mark the kinds: supervised, unsupervised and reinforcement.","cn":"三个分支名称标出类型：监督式、无监督式与强化式。"},{"en":"A spam filter is the everyday picture: it improves without anyone rewriting its rules.","cn":"垃圾邮件过滤器是日常画面：没人改写规则，它却越来越准。"}],"abstract":[{"en":"Picture a student who never receives a rulebook, only worked examples.","cn":"想象一个学生从没拿到规则手册，只拿到做过的例题。"},{"en":"Picture a scale that recalibrates itself each time a known weight is placed on it.","cn":"想象一台秤，每次放上已知重物就自我校准。"},{"en":"Picture a gardener who learns the soil by watching what survives.","cn":"想象一位园丁通过观察什么活下来而了解土壤。"}]},"examples":[{"en":"Machine learning turned the raw logs into a usable warning system.","cn":"机器学习把原始日志变成了可用的预警系统。"},{"en":"The course assumes no prior machine learning background.","cn":"这门课程假定学生没有机器学习基础。"},{"en":"Machine learning models degrade when the world changes quickly.","cn":"当外部世界变化很快时，机器学习模型会退化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「机器」也在「学习」——不用人教规则，靠看例子自己长本事","word":"machine learning"},"root":"拉丁语「机械」（源自希腊语「装置」）加古英语「学习」；二十世纪中叶成为术语。","sensesIntro":{"en":"Eight senses move from the discipline to its models, its process, three learning modes, its applications and its training pipeline.","cn":"八个义项从学科出发，依次落到模型、过程、三种学习方式、应用与训练流程。"},"semanticMap":{"core":{"en":"CORE IMAGE: a program that adjusts itself after seeing examples, with no rulebook rewritten by hand.","cn":"核心意象：程序看过样例后自我调整，没有人手改写规则手册。"},"chain":["DATA","EXAMPLES","PATTERN","MODEL","PREDICTION","IMPROVEMENT"],"branches":[{"senses":"01","en":"THE DISCIPLINE: the field that studies learning from data.","cn":"学科：研究从数据中学习的领域。"},{"senses":"02 · 03","en":"THE MODEL AND THE ACT: a trained system, and the ongoing cycle of prediction and correction.","cn":"模型与行为：训练好的系统，以及预测与纠错的持续循环。"},{"senses":"04 · 05 · 06","en":"THE THREE MODES: answers supplied, no answers supplied, and rewards earned by acting.","cn":"三种方式：提供答案、不提供答案，以及通过行动获得奖励。"},{"senses":"07","en":"THE APPLIED FACE: products and features powered by the methods.","cn":"应用面孔：由这些方法驱动的产品与功能。"},{"senses":"08","en":"THE PIPELINE: collecting, training and evaluating from end to end.","cn":"流程：从收集、训练到评估的端到端工作。"}]},"affixes":{"intro":{"en":"Machine learning combines a Latin-derived noun with a native English verb noun; both halves are live English words.","cn":"这个短语把源自拉丁语的名词与英语本族的动词名词结合；两半都是活跃的英语词。"},"latinIntro":{"en":"Only machine is Latin in origin; learn is native English, so the Latin list is limited to the machine line.","cn":"只有「机器」源自拉丁语；「学习」是英语本族词，因此拉丁词条只限「机器」这一支。"},"items":[{"word":"machina","structure":"Latin noun from Greek mekhane","meaning":"a device, an engine","meaningCN":"装置；机械","example":"The first half names the device that learns.","exampleCN":"前半命名进行学习的装置。"},{"word":"machine","structure":"machina through French","meaning":"a device that performs work","meaningCN":"执行工作的装置","example":"The English noun is the everyday word for an engine.","exampleCN":"这个英语名词是「机械」的日常说法。"},{"word":"learn","structure":"Old English verb leornian","meaning":"to gain knowledge","meaningCN":"获得知识","example":"The second half names what the device does.","exampleCN":"后半命名装置所做的事。"},{"word":"learning","structure":"learn plus the action noun ending","meaning":"the process of gaining knowledge","meaningCN":"获得知识的过程","example":"The noun names the process, not the person.","exampleCN":"这个名词指过程，而不是人。"},{"word":"-er","structure":"agent noun ending","meaning":"one that learns","meaningCN":"进行学习的主体","example":"A learner can be a person or a model.","exampleCN":"学习者可以是人，也可以是模型。"},{"word":"machine learning","structure":"machine plus learning","meaning":"learning done by a machine","meaningCN":"由机器进行的学习","example":"The compound names the whole field.","exampleCN":"这个复合词命名整个领域。"},{"word":"machine-learning","structure":"attributive form of the compound","meaning":"used before a noun","meaningCN":"作定语使用的形式","example":"A machine-learning course teaches both theory and practice.","exampleCN":"一门机器学习课程同时讲授理论与实践。"},{"word":"machine-learned","structure":"machine plus the learned participle","meaning":"produced by machine learning","meaningCN":"由机器学习产出的","example":"The machine-learned ranking improved the search results.","exampleCN":"机器习得的排序改善了搜索结果。"}],"latinEntries":[{"word":"machina","structure":"Latin noun from Greek","meaning":"a device, an engine","meaningCN":"装置；机械"},{"word":"mekhane","structure":"Greek noun","meaning":"a contrivance, a device","meaningCN":"巧妙装置；器械"},{"word":"mechanicus","structure":"Latin adjective from Greek","meaning":"of machines, mechanical","meaningCN":"机械的；与机械有关的"}],"derivatives":[{"word":"machine","pos":"n.","zh":"复合词前半，源自拉丁语「机械」，义为「机器」"},{"word":"learn","pos":"v.","zh":"复合词后半的词根，古英语意为「获得知识」"},{"word":"learner","pos":"n.","zh":"由「学习」的动词加施动者词尾构成，义为「学习者」"},{"word":"learning","pos":"n.","zh":"由「学习」的动词加动作名词尾构成，义为「学习过程」"},{"word":"machine-learned","pos":"adj.","zh":"由前半名词与「已学习」的分词复合，义为「机器习得的」"}]}},{"word":"learning algorithm","ipa_uk":"/ˈlɜːnɪŋ ˈælɡərɪðəm/","ipa_us":"/ˈlɜːrnɪŋ ˈælɡərɪðəm/","definition_zh":"学习算法；指导模型从数据中更新参数的规则","definition_en":"a procedure that adjusts a model's parameters so that its performance improves as it sees more data","core_image":"黑板上写着一串重复的更新步骤：读一个样本、算误差、改一点权重，再读下一个，循环往复","scene":"工程师换掉原来的更新规则后，同样的数据只用了三分之一的轮次就把误差降到目标值。A better learning algorithm reaches the target with fewer passes.","sceneCN":"这里指决定模型如何从数据中更新参数的步骤规则（第 1 个义项：更新参数的算法）；句意：更好的学习算法用更少的轮次就达到目标。","pos":[{"tag":"n.","zh":"学习算法；模型更新规则"}],"collocations":[{"phrase":"supervised learning algorithm","zh":"监督式学习算法"},{"phrase":"online learning algorithm","zh":"在线学习算法"},{"phrase":"training algorithm","zh":"训练算法"},{"phrase":"efficient learning algorithm","zh":"高效学习算法"},{"phrase":"learning algorithm design","zh":"学习算法设计"},{"phrase":"unsupervised learning algorithm","zh":"无监督式学习算法"}],"forms":[{"label":"单数","form":"learning algorithm"},{"label":"复数","form":"learning algorithms"},{"label":"相关动词","form":"learn"},{"label":"相关名词","form":"learner"},{"label":"形容词用法","form":"algorithmic"}],"derivatives":[{"word":"learning","pos":"n.","zh":"复合词前半，由「学习」的动词加动作名词尾构成，义为「学习过程」"},{"word":"algorithm","pos":"n.","zh":"复合词后半，源自阿拉伯语数学家之名，义为「算法」"},{"word":"algorithmic","pos":"adj.","zh":"由「算法」加表示「属于」的形容词尾构成，义为「算法的」"},{"word":"learner","pos":"n.","zh":"由「学习」的动词加施动者词尾构成，义为「学习者」"}],"senses":[{"no":"01","title":"The rule for updating parameters","titleCN":"更新参数的规则","definition":"a step-by-step method that changes a model's internal values so that its output becomes more accurate","definitionCN":"逐步改变模型内部数值、使输出更准确的方法","example":"A learning algorithm decides how far each weight moves.","exampleCN":"学习算法决定每个权重移动多远。","why":"An algorithm is a finite procedure, and here its job is to turn error into a specific correction.","whyCN":"算法是有限步骤，而在这里它的任务是把误差变成一个具体的修正。"},{"no":"02","title":"The general class of such methods","titleCN":"这类方法的总称","definition":"the whole family of procedures used to train machine learning models","definitionCN":"用于训练机器学习模型的整套方法族","example":"The paper compares five learning algorithm families.","exampleCN":"这篇论文比较了五个学习算法族。","why":"Many procedures share this job, so the phrase also names the class rather than a single method.","whyCN":"完成这一任务的方法很多，因此这个短语也命名整个类别，而不只是单一方法。"},{"no":"03","title":"A named training procedure","titleCN":"具名的训练步骤","definition":"a particular named method, such as gradient descent or a decision-tree builder","definitionCN":"某个具名方法，如梯度下降或决策树构建法","example":"The course introduces one learning algorithm at a time.","exampleCN":"课程每次只介绍一种学习算法。","why":"Each named procedure is an algorithm in the strict sense, and the phrase applies to the individual as well as the class.","whyCN":"每个具名步骤都是严格意义上的算法，这个短语既适用于类别，也适用于个体。"},{"no":"04","title":"An online updating method","titleCN":"在线更新方法","definition":"a procedure that updates the model as each new example arrives rather than in one batch","definitionCN":"每个新样例到来就更新模型、而非一次性批处理的方法","example":"An online learning algorithm adapts to the morning traffic.","exampleCN":"在线学习算法会适应早高峰的路况。","why":"When data arrives continuously, the update rule must run continuously, so this variant gets its own label.","whyCN":"当数据持续到来，更新规则也必须持续运行，因此这一变体有了自己的标签。"},{"no":"05","title":"A supervised training method","titleCN":"监督式训练方法","definition":"a procedure that uses labelled examples to reduce the gap between prediction and answer","definitionCN":"利用带标签样例缩小预测与答案差距的方法","example":"The supervised learning algorithm needed only a thousand labels.","exampleCN":"这个监督式学习算法只需要一千个标签。","why":"The available signal is the correct answer, and the algorithm's update is built around that comparison.","whyCN":"可用信号是正确答案，算法的更新正是围绕这一比较构建的。"},{"no":"06","title":"An unsupervised training method","titleCN":"无监督式训练方法","definition":"a procedure that finds structure in data without supplied answers","definitionCN":"在没有提供答案的情况下于数据中寻找结构的方法","example":"The unsupervised learning algorithm grouped the readings by shape.","exampleCN":"无监督式学习算法按形状把读数分了组。","why":"With no answer to compare against, the update must reward internal structure instead, giving a separate branch.","whyCN":"没有可比较的答案，更新就只能奖励内部结构，于是形成独立分支。"},{"no":"07","title":"The learning rule inside a method","titleCN":"方法内部的学习规则","definition":"the specific update formula that a larger method uses at each step","definitionCN":"更大方法在每一步使用的具体更新公式","example":"The learning algorithm inside the system was changed last week.","exampleCN":"系统内部的学习算法上周被更换了。","why":"A large method may contain several rules, and the phrase can point to the one rule that drives learning.","whyCN":"一个大方法可能包含多条规则，这个短语可以专指驱动学习的那一条。"},{"no":"08","title":"The optimization step","titleCN":"优化意义上的学习步骤","definition":"the part of training that searches for parameter values with lower error","definitionCN":"训练中寻找误差更低参数值的那一部分","example":"This learning algorithm trades speed for a smaller final error.","exampleCN":"这个学习算法以速度换取更小的最终误差。","why":"Training can be seen as minimizing error, and the algorithm is the search procedure that does it.","whyCN":"训练可被视为最小化误差，而算法就是完成这一搜索的步骤。"}],"etymology":{"intro":{"en":"Learning algorithm pairs the Old English verb for learning with algorithm, a name that reached Europe from a ninth-century Arabic mathematician.","cn":"这个短语把古英语的「学习」与「算法」配对，而「算法」之名来自九世纪一位阿拉伯数学家。"},"items":[{"era":"OLD ENGLISH LEORNIAN","en":"Leornian meant to gain knowledge or skill, and learning names the process it produced.","cn":"这个词意为获得知识或技能，「学习」命名由此产生的过程。"},{"era":"ARABIC AL-KHWARIZMI","en":"The surname of a ninth-century scholar of algebra became a byword for calculation in medieval Europe.","cn":"九世纪一位代数学者的姓氏，在中世纪欧洲成了「计算」的代称。"},{"era":"MEDIEVAL LATIN ALGORISMUS","en":"European writers Latinised the name for the decimal system and written calculation, and the form travelled through French.","cn":"欧洲书写者把这个名字拉丁化，用来指十进制与笔算，其形式又经法语传播。"},{"era":"ENGLISH ALGORISM AND ALGORITHM","en":"English first used a form closer to the Arabic name, and later restored a spelling that looked more Greek.","cn":"英语最初使用更接近阿拉伯语原名的形式，后来又改回一个看起来更像希腊语的拼写。"},{"era":"MODERN SENSE","en":"In modern computing an algorithm is any finite procedure, so a procedure that improves a model is a learning algorithm.","cn":"在现代计算中，算法指任何有限步骤，因此改进模型的过程就叫学习算法。"},{"era":"RECONSTRUCTED BORROWING CHAIN","en":"The transmission path of the name is generally accepted, but the exact chain of borrowings and spellings is reconstructed from several medieval variants.","cn":"这个名字的传播路径为一般接受，但确切的借入与拼写链条是根据若干中世纪变体推定的。"}]},"similar":{"note":{"en":"The first group shares one half of the phrase; the second group names nearby training concepts.","cn":"第一组共享短语的一半；第二组是相邻的训练概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"algorithm","ipa":"/ˈælɡərɪðəm/","tag":"second half","definition":"Any finite procedure; alone it need not involve learning.","definitionCN":"任何有限步骤；单独使用时不涉及学习。"},{"word":"algorithmic","ipa":"/ˌælɡəˈrɪðmɪk/","tag":"adjective","definition":"Relating to an algorithm; it describes the method rather than the activity of learning.","definitionCN":"与算法有关的；描述方法，而不是学习活动。"},{"word":"algorism","ipa":"/ˈælɡərɪzəm/","tag":"historical form","definition":"The older English name for written calculation with Arabic numerals.","definitionCN":"英语中较早的、指用阿拉伯数字笔算的名称。"},{"word":"logarithm","ipa":"/ˈlɒɡərɪðəm/","tag":"look-alike","definition":"A mathematical function; it looks similar but comes from Greek words for ratio and number.","definitionCN":"一种数学函数；拼写相似，但来自希腊语表示「比」与「数」的词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"training procedure","ipa":"/ˈtreɪnɪŋ prəˈsiːdʒə/","tag":"plain description","definition":"The steps used to fit a model; a plain-language equivalent of the term.","definitionCN":"拟合模型所用的步骤；是该术语的平实说法。"},{"word":"optimization rule","ipa":"/ˌɒptɪmaɪˈzeɪʃən ruːl/","tag":"narrower term","definition":"A rule for reducing error; it is the mathematical core of many learning algorithms.","definitionCN":"降低误差的规则；是许多学习算法的数学核心。"},{"word":"model update","ipa":"/ˈmɒdl ˈʌpdeɪt/","tag":"step name","definition":"The single change made in one round; a learning algorithm is the rule that produces such changes.","definitionCN":"一轮中所作的单次改动；学习算法就是产生这些改动的规则。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real learning stem and the real history of algorithm.","cn":"正常联想：真实的学习词干与真实的算法词源。"},"normal":[{"en":"Learning gives the goal, algorithm gives the steps: a rule that makes a model improve.","cn":"「学习」给目标，「算法」给步骤：一条让模型变好的规则。"},{"en":"The family runs learn, learner, learning, algorithm and algorithmic.","cn":"同族词有学习、学习者、学习过程、算法与算法的。"},{"en":"Fixed phrases mark the setting: supervised, unsupervised, online and efficient.","cn":"固定搭配标出场景：监督式、无监督式、在线与高效。"},{"en":"Fixed phrases mark the work: training algorithm and learning algorithm design.","cn":"固定搭配标出工作：训练算法与学习算法设计。"},{"en":"The name algorithm comes from a scholar's surname, not from a Greek root.","cn":"「算法」之名来自一位学者的姓氏，而不是希腊词根。"}],"abstract":[{"en":"Picture a recipe that tastes the soup and then adjusts the salt by itself.","cn":"想象一份食谱会尝汤，然后自行调整盐量。"},{"en":"Picture a staircase where each step is placed a little lower after every stumble.","cn":"想象一段楼梯，每次绊一下就把下一级放低一点。"},{"en":"Picture a hand that corrects its aim after every arrow, without being told the rule.","cn":"想象一只手每射一箭就修正准头，却没人告诉它规则。"}]},"examples":[{"en":"The learning algorithm adjusts the weights after every batch.","cn":"学习算法在每批数据后调整权重。"},{"en":"A simpler learning algorithm often generalizes better.","cn":"更简单的学习算法往往泛化得更好。"},{"en":"They published the learning algorithm so others could reproduce the result.","cn":"他们公布了学习算法，好让其他人复现结果。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「学习」+「算法」——给机器一套越练越准的步骤","word":"learning algorithm"},"root":"古英语「学习」加中世纪拉丁语的算法之名（源自阿拉伯语学者姓氏）；二十世纪组合成术语。","sensesIntro":{"en":"Eight senses divide the term by role: the update rule, the class, a named method, online, supervised, unsupervised, an inner rule and an optimization step.","cn":"八个义项按角色划分：更新规则、类别、具名方法、在线、监督式、无监督式、内部规则与优化步骤。"},"semanticMap":{"core":{"en":"CORE IMAGE: a repeated loop that reads one example, measures error and nudges the weights.","cn":"核心意象：一个反复循环，读一个样例、量出误差、把权重挪一点。"},"chain":["DATA","SAMPLE","ERROR","UPDATE","PARAMETER","BETTER MODEL"],"branches":[{"senses":"01 · 07","en":"THE RULE ITSELF: the update formula, whether seen as the whole method or one inner step.","cn":"规则本身：更新公式，既可视为整个方法，也可视为其中一个内部步骤。"},{"senses":"02 · 03","en":"CLASS AND INSTANCE: the whole family of procedures, and one named method within it.","cn":"类别与个体：整套方法族，以及其中的某个具名方法。"},{"senses":"04","en":"CONTINUOUS DATA: updating as each example arrives.","cn":"持续数据：每个样例到来就更新。"},{"senses":"05 · 06","en":"TWO SIGNALS: a correct answer to compare against, or structure found without answers.","cn":"两种信号：可比较的正确答案，或没有答案时发现的结构。"},{"senses":"08","en":"THE SEARCH: reducing error by moving through parameter values.","cn":"搜索：在参数值空间中移动以降低误差。"}]},"affixes":{"intro":{"en":"The phrase joins a native English learning noun with algorithm, a name of Arabic origin that entered Europe through Latin.","cn":"这个短语把英语本族的「学习」名词与「算法」结合，后者源自阿拉伯语，经拉丁语进入欧洲。"},"latinIntro":{"en":"The algorithm half reached English through Medieval Latin, but its root is a personal name rather than a Latin word; the list therefore records the Latin stage only.","cn":"「算法」一半经中世纪拉丁语进入英语，但其根源是人名而非拉丁词；因此列表只记录拉丁语这一阶段。"},"items":[{"word":"learn","structure":"Old English verb leornian","meaning":"to gain knowledge","meaningCN":"获得知识","example":"The first half names the goal of the procedure.","exampleCN":"前半命名这一过程的目标。"},{"word":"learning","structure":"learn plus the action noun ending","meaning":"the process of gaining knowledge","meaningCN":"获得知识的过程","example":"The noun names the process the algorithm serves.","exampleCN":"这个名词指算法所服务的过程。"},{"word":"algorithm","structure":"Medieval Latin algorismus from Arabic","meaning":"a procedure for calculation","meaningCN":"计算步骤","example":"The second half names the finite procedure.","exampleCN":"后半命名有限步骤。"},{"word":"algorism","structure":"older English form of the same name","meaning":"written calculation with Arabic numerals","meaningCN":"用阿拉伯数字的笔算","example":"The older form survives in histories of arithmetic.","exampleCN":"较旧的形式仍见于算术史著作。"},{"word":"-ic","structure":"adjective ending","meaning":"relating to","meaningCN":"与……有关的","example":"Algorithmic describes a method built from steps.","exampleCN":"「算法的」描述由步骤构成的方法。"},{"word":"-er","structure":"agent noun ending","meaning":"one that learns","meaningCN":"进行学习的主体","example":"A learner is the model being trained.","exampleCN":"学习者就是被训练的模型。"},{"word":"learning algorithm","structure":"learning plus algorithm","meaning":"the procedure that makes a model improve","meaningCN":"使模型改进的步骤","example":"The compound names the method that turns error into correction.","exampleCN":"这个复合词命名「把误差变成修正」的方法。"},{"word":"training algorithm","structure":"training plus algorithm","meaning":"the procedure used to fit a model","meaningCN":"用于拟合模型的步骤","example":"Training algorithm is the close synonym used in engineering.","exampleCN":"「训练算法」是工程上常用的近义说法。"}],"latinEntries":[{"word":"algorismus","structure":"Medieval Latin noun from Arabic","meaning":"the Arabic numeral system and its calculation","meaningCN":"阿拉伯数字系统及其计算法"},{"word":"algorismi","structure":"Medieval Latin genitive of the name","meaning":"of al-Khwarizmi","meaningCN":"花拉子米的（属格形式）"},{"word":"arithmetica","structure":"Latin noun from Greek","meaning":"the art of counting","meaningCN":"计算之术"}],"derivatives":[{"word":"learning","pos":"n.","zh":"复合词前半，由「学习」的动词加动作名词尾构成，义为「学习过程」"},{"word":"algorithm","pos":"n.","zh":"复合词后半，源自阿拉伯语数学家之名，义为「算法」"},{"word":"algorithmic","pos":"adj.","zh":"由「算法」加表示「属于」的形容词尾构成，义为「算法的」"},{"word":"learner","pos":"n.","zh":"由「学习」的动词加施动者词尾构成，义为「学习者」"}]}},{"word":"neural network","ipa_uk":"/ˈnjʊərəl ˈnetwɜːk/","ipa_us":"/ˈnʊrəl ˈnetwɜːrk/","definition_zh":"神经网络；由多层相连单元构成的计算模型","definition_en":"a computing model made of layers of connected units that transform data and adjust their connections through training","core_image":"三层圆圈排成矩阵，前一层的每个节点都伸出细线连到下一层，信号沿线条一层层传过去","scene":"屏幕上三列圆点用细线相连，输入一张手写数字的图片后，最右侧的输出节点亮起，标出正确的号码。A trained neural network recognizes the digit from patterns in its pixels.","sceneCN":"这里指由多层相连单元组成、可经训练调整连接权重的计算模型（第 1 个义项：人工神经网络模型）；句意：训练好的神经网络根据像素规律认出这个数字。","pos":[{"tag":"n.","zh":"神经网络；多层计算模型"}],"collocations":[{"phrase":"artificial neural network","zh":"人工神经网络"},{"phrase":"convolutional neural network","zh":"卷积神经网络"},{"phrase":"deep neural network","zh":"深度神经网络"},{"phrase":"neural network model","zh":"神经网络模型"},{"phrase":"neural network training","zh":"神经网络训练"},{"phrase":"recurrent neural network","zh":"循环神经网络"}],"forms":[{"label":"单数","form":"neural network"},{"label":"复数","form":"neural networks"},{"label":"形容词","form":"neural"},{"label":"基础名词","form":"neuron"},{"label":"定语用法","form":"neural-network"}],"derivatives":[{"word":"neuron","pos":"n.","zh":"源自希腊语「神经」，义为「神经元」"},{"word":"neural","pos":"adj.","zh":"由「神经」加形容词尾构成，义为「神经的」"},{"word":"neurone","pos":"n.","zh":"同一名词的英式变体拼写，义为「神经元」"},{"word":"neurally","pos":"adv.","zh":"由「神经的」加副词词尾构成，义为「在神经层面」"},{"word":"networking","pos":"n.","zh":"由「网络」加动作名词尾构成，义为「组网、联网」"}],"senses":[{"no":"01","title":"The artificial computing model","titleCN":"人工计算模型","definition":"a model of layered units that learns by adjusting the strength of its connections","definitionCN":"由多层单元构成、通过调整连接强度而学习的模型","example":"The neural network learns to separate cats from dogs.","exampleCN":"这个神经网络学会把猫与狗分开。","why":"The name borrows the brain's wiring diagram, but the units are mathematical and the connections are numbers.","whyCN":"这个名字借用了大脑的接线图，但单元是数学量，连接是数字。"},{"no":"02","title":"The layered structure itself","titleCN":"分层结构本身","definition":"the arrangement of input, hidden and output layers connected by weighted links","definitionCN":"输入层、隐藏层与输出层通过带权连接构成的排布","example":"The neural network has three hidden layers.","exampleCN":"这个神经网络有三个隐藏层。","why":"The word network points to the pattern of links, so the architecture itself is named by the phrase.","whyCN":"「网络」一词指向连接图案，因此架构本身就用这个短语命名。"},{"no":"03","title":"A biological nerve network","titleCN":"生物神经网络","definition":"the actual network of neurons in a brain or nervous system","definitionCN":"大脑或神经系统中真实的神经元网络","example":"The neural network of the retina processes light before the brain sees it.","exampleCN":"视网膜的神经网络在大脑看见之前先处理光信号。","why":"The computing term borrowed an existing biological phrase, and the original sense remains in physiology.","whyCN":"计算术语借用了已有的生物说法，原义在生理学中仍然保留。"},{"no":"04","title":"A deep network","titleCN":"深度网络","definition":"a network with many layers, able to learn increasingly abstract features","definitionCN":"层数很多、能学习越来越抽象特征的网络","example":"The deep neural network detects faces at several scales.","exampleCN":"这个深度神经网络在多个尺度上检测人脸。","why":"Depth is the number of layers, so a network with many layers takes the ordinary adjective for depth.","whyCN":"深度就是层数，因此层数多的网络就用表示「深」的普通形容词。"},{"no":"05","title":"A convolutional network","titleCN":"卷积网络","definition":"a network that slides small filters across an image to detect local patterns","definitionCN":"在图像上滑动小滤波器、检测局部图案的网络","example":"The convolutional neural network finds edges before shapes.","exampleCN":"卷积神经网络先找边缘，再找形状。","why":"The operation that defines this family is convolution, and the phrase carries that operation as its label.","whyCN":"定义这一族的运算就是卷积，短语便以该运算为标签。"},{"no":"06","title":"A recurrent network","titleCN":"循环网络","definition":"a network that carries its own previous state forward, suited to sequences","definitionCN":"把自身先前状态带到下一步、适合序列数据的网络","example":"The recurrent neural network reads the sentence word by word.","exampleCN":"循环神经网络逐词读入句子。","why":"When links run backward in time as well as forward, the network recurs, and the name marks that loop.","whyCN":"当连接不仅向前也回到先前时刻，网络就形成循环，名称标记这一回路。"},{"no":"07","title":"Layers, units and weights","titleCN":"层、单元与权重","definition":"the internal parts of the model considered as a set of numbered connections","definitionCN":"把模型内部视为一组带数值的连接","example":"The neural network stores millions of weights after training.","exampleCN":"训练后这个神经网络存储了数百万个权重。","why":"The same phrase can name the parts rather than the whole, because the parts are what carry the learned knowledge.","whyCN":"同一个短语也可指部件而非整体，因为承载所学知识的正是这些部件。"},{"no":"08","title":"Training the network","titleCN":"训练网络","definition":"the process of adjusting a network's weights until its output is useful","definitionCN":"调整网络权重直到输出可用的过程","example":"Neural network training took three days on one machine.","exampleCN":"神经网络训练在一台机器上花了三天。","why":"A network is not useful until trained, so the phrase also names the training activity as a stage.","whyCN":"网络在训练之前无法使用，因此这个短语也把训练活动命名成一个阶段。"}],"etymology":{"intro":{"en":"Neural network combines Greek neuron, a nerve, with the English compound network; the computing sense dates from the 1940s.","cn":"这个短语把希腊语「神经」与英语复合词「网络」结合；计算机义项始于二十世纪四十年代。"},"items":[{"era":"GREEK NEURON","en":"Neuron meant a sinew, cord or nerve, and it is the source of neuron and neural in modern science.","cn":"这个词意为筋、索或神经，是现代科学中「神经元」「神经的」的来源。"},{"era":"OLD ENGLISH NETWORK","en":"Network named a mesh of cords and later any linked system, including telegraph and telephone systems.","cn":"「网络」原指绳线结成的网，后来指任何相连的系统，包括电报与电话系统。"},{"era":"NINETEENTH CENTURY PHYSIOLOGY","en":"Physiologists described the interwoven fibres of the nervous system as a network of nerves.","cn":"生理学家把神经系统交织的纤维描述为神经的网络。"},{"era":"MCCULLOCH AND PITTS 1943","en":"Two researchers modelled a nerve cell as a simple logical unit, and layers of such units became a computing network.","cn":"两位研究者把神经细胞建模为简单的逻辑单元，这样的单元分层排列便成了计算网络。"},{"era":"PERCEPTRON AND DEEP LEARNING","en":"The perceptron brought trainable weights into the phrase, and later deep networks made it a household term.","cn":"感知机把可训练的权重带入这个短语，后来的深度网络又让它家喻户晓。"},{"era":"FIRST RECORD UNCERTAIN","en":"The first use of the exact English phrase for an artificial model is generally placed in the 1940s, but the precise paper is not settled.","cn":"这个确切英语短语用于人工模型的首见一般定在二十世纪四十年代，但具体文献尚无定论。"}]},"similar":{"note":{"en":"The first group shares one half of the phrase; the second group names neighbouring model families.","cn":"第一组共享短语的一半；第二组是相邻的模型族。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"neuron","ipa":"/ˈnjʊərɒn/","tag":"unit noun","definition":"A single nerve cell or a single model unit; the network is many of these joined.","definitionCN":"单个神经细胞或单个模型单元；网络就是许多这样的单元相连。"},{"word":"neural","ipa":"/ˈnjʊərəl/","tag":"adjective","definition":"Relating to nerves; it describes the kind of network rather than the network itself.","definitionCN":"与神经有关的；描述网络的种类，而不是网络本身。"},{"word":"network","ipa":"/ˈnetwɜːk/","tag":"second half","definition":"A linked system; in the phrase the links are weighted connections.","definitionCN":"相互连接的系统；在短语中这些连接是带权的。"},{"word":"networking","ipa":"/ˈnetwɜːkɪŋ/","tag":"activity noun","definition":"The activity of linking machines or people; it is unrelated to the model.","definitionCN":"连接机器或人的活动；与这种模型无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"deep learning model","ipa":"/diːp ˈlɜːnɪŋ ˈmɒdl/","tag":"wider class","definition":"A model trained with many layers; most such models are neural networks, but the term stresses depth.","definitionCN":"用多层训练的模型；多数这类模型是神经网络，但该说法强调深度。"},{"word":"perceptron","ipa":"/pəˈseptrɒn/","tag":"early model","definition":"An early single-layer classifier with adjustable weights, the ancestor of the modern network.","definitionCN":"早期带可调权重的单层分类器，是现代网络的祖先。"},{"word":"connectionist model","ipa":"/kəˈnekʃənɪst ˈmɒdl/","tag":"theory label","definition":"A model that computes through connections rather than explicit rules; a broader theoretical label.","definitionCN":"通过连接而非显式规则计算的模型；是更宽的理论标签。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real Greek root, a real English compound and real architecture names.","cn":"正常联想：真实希腊词根、真实英语复合词与真实架构名称。"},"normal":[{"en":"Neural points to nerves, network points to links: a net of nerve-like units.","cn":"「神经」指向神经，「网络」指向连接：一张由类神经单元结成的网。"},{"en":"The family runs neuron, neural, neurone, neurally and networking.","cn":"同族词有神经元、神经的、神经元变体、在神经层面与组网。"},{"en":"Fixed phrases mark the architecture: artificial, deep, convolutional and recurrent.","cn":"固定搭配标出架构：人工的、深度的、卷积的与循环的。"},{"en":"Fixed phrases mark the work: neural network model, training and weights.","cn":"固定搭配标出工作：神经网络模型、训练与权重。"},{"en":"Three columns of circles joined by lines are the standard diagram.","cn":"三列圆圈用线相连，是最标准的示意图。"}],"abstract":[{"en":"Picture a crowd where each person listens to a few neighbours and passes a whisper on.","cn":"想象一群人，每人都听几位邻居说话，再把耳语传下去。"},{"en":"Picture a lens made of many small lenses, each slightly adjusting the image.","cn":"想象一枚由许多小透镜组成的镜头，每一片都略微修正图像。"},{"en":"Picture a loom whose threads tighten or loosen until the pattern comes out right.","cn":"想象一台织机，纱线不断收紧或放松，直到图案正确。"}]},"examples":[{"en":"The neural network was trained on ten years of weather records.","cn":"这个神经网络用十年的天气记录训练而成。"},{"en":"A small neural network can run on a phone.","cn":"一个小型神经网络可以在手机上运行。"},{"en":"The team compared a neural network with a simple rule-based system.","cn":"团队把神经网络与简单的规则系统作了比较。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「神经」+「网络」——照大脑接线方式搭起的计算网","word":"neural network"},"root":"希腊语「神经」加英语「网」与「劳作」的复合词；二十世纪四十年代用于计算模型。","sensesIntro":{"en":"Eight senses run from the artificial model and its structure to the biological original, depth, convolution, recurrence, internal weights and training.","cn":"八个义项从人工模型及其结构出发，依次到生物原型、深度、卷积、循环、内部权重与训练。"},"semanticMap":{"core":{"en":"CORE IMAGE: layers of small units joined by weighted lines, passing a signal from left to right.","cn":"核心意象：一层层小单元由带权线相连，信号从左向右传递。"},"chain":["NEURON","CONNECTION","LAYER","WEIGHT","SIGNAL","LEARNED OUTPUT"],"branches":[{"senses":"01 · 02","en":"THE MODEL AND ITS SHAPE: the learning system, and the layered architecture that makes it work.","cn":"模型与其形状：学习系统，以及使其运作的分层架构。"},{"senses":"03","en":"THE BIOLOGICAL ORIGINAL: the real nerve network that supplied the name.","cn":"生物原型：提供名称的真实神经网。"},{"senses":"04 · 05 · 06","en":"THREE ARCHITECTURES: many layers, sliding filters, and state carried through time.","cn":"三种架构：多层、滑动滤波，以及沿时间携带的状态。"},{"senses":"07","en":"THE INNER PARTS: layers, units and the numerical weights that hold what was learned.","cn":"内部部件：层、单元与承载所学内容的数值权重。"},{"senses":"08","en":"THE MAKING OF IT: training, the stage that turns an architecture into a useful model.","cn":"它的制造：训练，即把架构变成可用模型的阶段。"}]},"affixes":{"intro":{"en":"The phrase joins a Greek noun and an English compound; neural brings the Greek line, network the native English line.","cn":"这个短语把希腊名词与英语复合词结合；「神经的」带来希腊语线索，「网络」带来英语本族线索。"},"latinIntro":{"en":"The first half is Greek and the second is English, so no Latin root is listed; Latin appears only in the adjective ending of neural.","cn":"前半是希腊语，后半是英语，因此不列拉丁词根；拉丁语只出现在「神经的」的形容词词尾形式上。"},"items":[{"word":"neuron","structure":"Greek noun","meaning":"a sinew, cord, nerve","meaningCN":"筋；索；神经","example":"The first half supplies the nerve in the name.","exampleCN":"前半提供了名称中的「神经」。"},{"word":"neural","structure":"neuron plus an adjective ending","meaning":"relating to nerves","meaningCN":"与神经有关的","example":"The adjective describes the kind of units used.","exampleCN":"这个形容词描述所用单元的种类。"},{"word":"net","structure":"Old English noun for a mesh","meaning":"a net; a mesh","meaningCN":"网；网状物","example":"The second half begins with the old word for a net.","exampleCN":"后半始于表示「网」的古词。"},{"word":"work","structure":"Old English noun for labour","meaning":"work; a made structure","meaningCN":"工作；造出的结构","example":"Together with net it produced the word for a linked system.","exampleCN":"与「网」结合，产生了指相连系统的词。"},{"word":"network","structure":"net plus work","meaning":"a linked system","meaningCN":"相互连接的系统","example":"The second half names the pattern of connections.","exampleCN":"后半命名连接的图案。"},{"word":"-al","structure":"adjective ending","meaning":"relating to","meaningCN":"与……有关的","example":"The ending turns the nerve noun into an adjective.","exampleCN":"这个词尾把「神经」名词变成形容词。"},{"word":"neural network","structure":"neural plus network","meaning":"a network of nerve-like units","meaningCN":"由类神经单元构成的网","example":"The compound names the computing model.","exampleCN":"这个复合词命名该计算模型。"},{"word":"neural-network","structure":"attributive form","meaning":"used before a noun","meaningCN":"作定语使用的形式","example":"A neural-network layer can be exported as a file.","exampleCN":"一个神经网络层可以导出为文件。"}],"latinEntries":[],"derivatives":[{"word":"neuron","pos":"n.","zh":"源自希腊语「神经」，义为「神经元」"},{"word":"neural","pos":"adj.","zh":"由「神经」加形容词尾构成，义为「神经的」"},{"word":"neurone","pos":"n.","zh":"同一名词的英式变体拼写，义为「神经元」"},{"word":"neurally","pos":"adv.","zh":"由「神经的」加副词词尾构成，义为「在神经层面」"},{"word":"networking","pos":"n.","zh":"由「网络」加动作名词尾构成，义为「组网、联网」"}]}},{"word":"robotics","ipa_uk":"/rəʊˈbɒtɪks/","ipa_us":"/roʊˈbɑːtɪks/","definition_zh":"机器人学；机器人技术；机器人产业","definition_en":"the branch of technology that designs, builds and operates robots","core_image":"车间里几台不同形状的机械臂按同一套程序协同工作，一旁的工程师在平板上调整抓取角度","scene":"比赛场上，学生给四足机器狗输入路线，它自己避开障碍，把小球送到终点。Modern robotics combines mechanics, electronics and software.","sceneCN":"这里指设计、制造与操控机器人的技术领域（第 1 个义项：机器人技术）；句意：现代机器人技术结合了机械、电子与软件。","pos":[{"tag":"n.","zh":"机器人学；机器人技术；机器人产业"}],"collocations":[{"phrase":"industrial robotics","zh":"工业机器人技术"},{"phrase":"robotics company","zh":"机器人公司"},{"phrase":"robotics research","zh":"机器人研究"},{"phrase":"service robotics","zh":"服务机器人技术"},{"phrase":"robotics competition","zh":"机器人竞赛"},{"phrase":"robotics engineer","zh":"机器人工程师"}],"forms":[{"label":"学科名词（不可数）","form":"robotics"},{"label":"基础名词","form":"robot"},{"label":"形容词","form":"robotic"},{"label":"副词","form":"robotically"}],"derivatives":[{"word":"robot","pos":"n.","zh":"源自捷克语「苦役」，义为「机器人」"},{"word":"robotic","pos":"adj.","zh":"由「机器人」加形容词尾构成，义为「机器人的、机械的」"},{"word":"robotically","pos":"adv.","zh":"由「机器人的」加副词词尾构成，义为「以机械方式」"},{"word":"robotize","pos":"v.","zh":"由「机器人」加动词词尾构成，义为「使机器人化」"},{"word":"robotization","pos":"n.","zh":"由该动词加动作名词尾构成，义为「机器人化」"}],"senses":[{"no":"01","title":"The field of robot technology","titleCN":"机器人技术这一领域","definition":"the engineering field that studies how robots are designed, controlled and used","definitionCN":"研究机器人如何设计、控制与使用的工程领域","example":"Robotics draws on mechanics, electronics and software.","exampleCN":"机器人技术融合机械、电子与软件。","why":"The subject ending turns the noun for a robot into the name of the discipline that studies it.","whyCN":"表示学科的结尾把「机器人」这一名词变成研究它的学科名称。"},{"no":"02","title":"The robot industry","titleCN":"机器人产业","definition":"the companies, factories and market that produce and sell robots","definitionCN":"生产与销售机器人的公司、工厂与市场","example":"Robotics has become a major employer in the region.","exampleCN":"机器人产业已成为该地区的重要雇主。","why":"A discipline with commercial products is also named by its field term, so the word can mean the industry.","whyCN":"拥有商业产品的学科也以领域名称指称，因此这个词可以指产业。"},{"no":"03","title":"Designing and building robots","titleCN":"机器人的设计与制造","definition":"the practical work of creating robot bodies, joints and drives","definitionCN":"创造机器人本体、关节与驱动的实际工作","example":"Robotics begins with a frame that can carry its own motors.","exampleCN":"机器人技术从一副能承载自身电机的框架开始。","why":"The field is not only theory, so the same word covers the hands-on making of machines.","whyCN":"这一领域不只是理论，因此同一个词也涵盖亲手制造机器的工作。"},{"no":"04","title":"Industrial robot technology","titleCN":"工业机器人技术","definition":"the branch concerned with arms, grippers and production lines","definitionCN":"关注机械臂、夹爪与生产线的分支","example":"Industrial robotics changed car assembly more than any other sector.","exampleCN":"工业机器人技术对汽车装配的改变超过任何其他行业。","why":"Factories were the first large market, so the branch that serves them is named with a qualifier.","whyCN":"工厂是最早的大市场，因此服务工厂的分支前面加上限定词。"},{"no":"05","title":"Autonomous robot research","titleCN":"自主机器人研究","definition":"the branch that gives robots sensing, planning and independent movement","definitionCN":"赋予机器人感知、规划与自主移动能力的分支","example":"Robotics labs now test machines that explore without a map.","exampleCN":"机器人实验室如今在测试没有地图也能探索的机器。","why":"Autonomy adds perception and decision, so it forms a distinct research branch within the field.","whyCN":"自主性加入感知与决策，因此在该领域内形成独立的研究分支。"},{"no":"06","title":"Robot control systems","titleCN":"机器人控制系统","definition":"the branch that keeps joints stable and follows planned paths","definitionCN":"保持关节稳定并沿规划路径运动的控制分支","example":"Robotics relies on control theory to keep the arm steady.","exampleCN":"机器人技术依靠控制理论让机械臂保持稳定。","why":"A machine that moves must be governed, and that governing work is a core part of the field.","whyCN":"会动的机器必须被支配，这一支配工作构成领域的核心部分。"},{"no":"07","title":"Service and medical robotics","titleCN":"服务与医疗机器人技术","definition":"the branch that builds robots to assist people in care, surgery or daily tasks","definitionCN":"制造在护理、手术或日常事务中协助人的机器人的分支","example":"Medical robotics lets a surgeon work through a tiny opening.","exampleCN":"医疗机器人技术让外科医生通过很小的开口操作。","why":"When robots leave the factory floor, the field is named by the service it performs.","whyCN":"当机器人走出车间，领域便以它所提供的服务命名。"},{"no":"08","title":"Robotics in education and competition","titleCN":"教育与竞赛中的机器人技术","definition":"the use of robot building as a teaching method and a contest","definitionCN":"把机器人制作用作教学方法与竞赛活动","example":"School robotics gives students a reason to learn physics.","exampleCN":"学校机器人活动给学生学习物理的理由。","why":"A field that is easy to demonstrate becomes a teaching subject, and the word takes on that role.","whyCN":"易于演示的领域会成为教学科目，这个词也承担起这一角色。"}],"etymology":{"intro":{"en":"Robotics is robot plus the Greek subject ending -ics; robot itself came to English from a Czech play in 1920, built on a word for forced labour.","cn":"这个词由「机器人」加希腊语学科词尾构成；「机器人」本身来自 1920 年一部捷克戏剧，词根源自「苦役」。"},"items":[{"era":"CZECH ROBOTA","en":"Robota meant forced labour or drudgery, a word tied to the historical system of unpaid service.","cn":"这个词意为苦役或繁重劳动，与历史上无偿服役的制度相关。"},{"era":"CAPEK 1920","en":"A play about manufactured workers used robot for the artificial people, and the word spread quickly in translation.","cn":"一部关于人造工人的戏剧用这个词指人造人，该词随译本迅速传播。"},{"era":"ROBOT IN ENGLISH","en":"English adopted robot in the 1920s for a machine that performs work, often shaped like a person.","cn":"英语在二十世纪二十年代采用这个词，指执行工作、常具人形的机器。"},{"era":"ROBOTICS AS A DISCIPLINE","en":"Writers on machines added the Greek subject ending to robot, producing a name for the field of building and using them.","cn":"机器领域的写作者在「机器人」后加希腊语学科词尾，造出研究制造与使用机器人的领域名称。"},{"era":"INDUSTRIAL AND SERVICE ERAS","en":"Assembly-line arms gave the field its first industry, and later medical and household machines widened it.","cn":"装配线机械臂给了这个领域第一个产业，后来的医疗与家用机器又拓宽了它。"},{"era":"COINAGE ATTRIBUTION UNCERTAIN","en":"The suggestion of the word robot is generally credited to the playwright's brother, but the attribution rests on later recollection rather than a contemporary record.","cn":"「机器人」一词的提议一般归功于剧作家的兄弟，但这一归属依据的是后来的回忆，而非当时的记录。"}]},"similar":{"note":{"en":"The first group shares the robot stem; the second group names neighbouring automation fields.","cn":"第一组共享「机器人」词干；第二组是相邻的自动化领域。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"robot","ipa":"/ˈrəʊbɒt/","tag":"base noun","definition":"A single machine; robotics is the field that designs and uses such machines.","definitionCN":"单台机器；机器人技术是设计与使用这类机器的领域。"},{"word":"robotic","ipa":"/rəʊˈbɒtɪk/","tag":"adjective","definition":"Relating to robots, or stiff like one; it describes rather than names the field.","definitionCN":"与机器人有关的，或像机器人一样僵硬；描述而非命名领域。"},{"word":"robotically","ipa":"/rəʊˈbɒtɪkli/","tag":"adverb","definition":"In a mechanical way; it modifies an action.","definitionCN":"以机械的方式；修饰动作。"},{"word":"robotize","ipa":"/ˈrəʊbətaɪz/","tag":"verb","definition":"To convert a process to robot operation.","definitionCN":"把流程改为机器人操作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"automation","ipa":"/ˌɔːtəˈmeɪʃən/","tag":"wider practice","definition":"Replacing human work with machines of any kind; robots are one branch of it.","definitionCN":"用任何机器替代人工；机器人只是其中一个分支。"},{"word":"mechatronics","ipa":"/ˌmekəˈtrɒnɪks/","tag":"sister field","definition":"The union of mechanics, electronics and control; it supplies much of the engineering inside robotics.","definitionCN":"机械、电子与控制的结合；为机器人技术提供大量内部工程基础。"},{"word":"cybernetics","ipa":"/ˌsaɪbəˈnetɪks/","tag":"older theory","definition":"The study of control and communication in machines and living things, a theoretical ancestor.","definitionCN":"研究机器与生物中的控制与通信，是理论上的祖先。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Czech labour root, the play and the real branch names.","cn":"正常联想：捷克语「苦役」词根、那部戏剧与真实分支名称。"},"normal":[{"en":"Robot came from a word for forced labour, and the subject ending makes it a field.","cn":"「机器人」来自表示苦役的词，加上学科词尾就成了一个领域。"},{"en":"The family runs robot, robotic, robotically, robotize and robotics.","cn":"同族词有机器人、机器人的、以机械方式、使机器人化与机器人技术。"},{"en":"Fixed phrases mark the sectors: industrial, service and medical robotics.","cn":"固定搭配标出行业：工业、服务与医疗机器人技术。"},{"en":"Fixed phrases mark the people: robotics engineer, robotics company, robotics research.","cn":"固定搭配标出人与机构：机器人工程师、机器人公司、机器人研究。"},{"en":"A 1920 play gave the machine its name, and the factory gave the field its first market.","cn":"1920 年的一部戏剧给了机器名字，工厂给了这个领域第一个市场。"}],"abstract":[{"en":"Picture a workforce made of metal that never asks for a break.","cn":"想象一支金属做的劳动队伍，从不要求休息。"},{"en":"Picture a hand that can be lent to someone across the world.","cn":"想象一只可以借给世界另一端某人的手。"},{"en":"Picture a body assembled from parts that each know their own job.","cn":"想象一具由各司其职的部件组装起来的身体。"}]},"examples":[{"en":"Robotics is one of the fastest-growing engineering fields.","cn":"机器人技术是发展最快的工程领域之一。"},{"en":"The lab opened a robotics programme for local schools.","cn":"实验室为当地学校开设了机器人项目。"},{"en":"Service robotics now includes machines that deliver medicine.","cn":"服务机器人技术如今包括送药的机器。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「机器人」+「学科」——研究怎么造、怎么用机器人的学问","word":"robotics"},"root":"捷克语「苦役」，1920 年经戏剧进入英语；再加希腊语学科词尾构成机器人技术。","sensesIntro":{"en":"Eight senses run from the discipline to the industry, the making, the industrial branch, autonomy, control, service uses and education.","cn":"八个义项从学科出发，依次到产业、制造、工业分支、自主性、控制、服务用途与教育。"},"semanticMap":{"core":{"en":"CORE IMAGE: metal workers assembled from parts, each part given a job by a shared program.","cn":"核心意象：由部件组装起来的金属劳动者，每个部件都由同一套程序分派任务。"},"chain":["FORCED LABOUR","ARTIFICIAL WORKER","MACHINE","SENSOR","CONTROL","AUTONOMOUS TASK"],"branches":[{"senses":"01 · 03","en":"THE FIELD AND THE MAKING: the discipline, and the practical work of building bodies and drives.","cn":"领域与制造：学科，以及建造本体与驱动的实际工作。"},{"senses":"02","en":"THE MARKET: companies and factories that make robots a business.","cn":"市场：把机器人变成商业的公司与工厂。"},{"senses":"04","en":"THE FACTORY BRANCH: arms, grippers and assembly lines.","cn":"工厂分支：机械臂、夹爪与装配线。"},{"senses":"05 · 06","en":"SENSE AND GOVERN: autonomy through perception and planning, and the control that keeps motion stable.","cn":"感知与支配：通过感知与规划获得的自主，以及保持运动稳定的控制。"},{"senses":"07 · 08","en":"PEOPLE OUTSIDE THE FACTORY: care and surgery, and the classroom where the field is taught.","cn":"工厂之外的人：护理与手术，以及讲授这一领域的课堂。"}]},"affixes":{"intro":{"en":"Robotics is a Czech-derived noun with a Greek subject ending; the two halves come from very different places.","cn":"这个词以捷克语为词干，配希腊语学科词尾；两半的来源差异很大。"},"latinIntro":{"en":"Neither half is Latin: robot is Czech and -ics is Greek, so the Latin list is empty.","cn":"两半都不是拉丁语：「机器人」来自捷克语，学科词尾来自希腊语，因此拉丁词条留空。"},"items":[{"word":"robota","structure":"Czech noun","meaning":"forced labour, drudgery","meaningCN":"苦役；繁重劳动","example":"The root supplies the image of work without choice.","exampleCN":"词根提供「无从选择的工作」这一画面。"},{"word":"robot","structure":"Czech coinage used in a 1920 play","meaning":"an artificial worker","meaningCN":"人造劳动者","example":"The noun entered English with the play's success.","exampleCN":"这个名词随该剧的成功进入英语。"},{"word":"-ics","structure":"Greek subject ending","meaning":"a field of study or practice","meaningCN":"研究或实践的领域","example":"The ending turns a thing into a discipline.","exampleCN":"这个词尾把某事物变成一门学科。"},{"word":"robotics","structure":"robot plus -ics","meaning":"the field of robots","meaningCN":"机器人领域","example":"The compound names the discipline that builds and uses robots.","exampleCN":"这个复合词命名建造与使用机器人的学科。"},{"word":"robotic","structure":"robot plus the adjective ending","meaning":"relating to robots","meaningCN":"与机器人有关的","example":"A robotic arm repeats the same weld.","exampleCN":"机械臂重复同一道焊接。"},{"word":"robotically","structure":"robotic plus the adverb ending","meaning":"in a mechanical way","meaningCN":"以机械的方式","example":"The hand moved robotically across the bench.","exampleCN":"那只手机械地掠过工作台。"},{"word":"robotize","structure":"robot plus the verb ending","meaning":"to convert to robot operation","meaningCN":"使改为机器人操作","example":"The plant robotized its painting line.","exampleCN":"工厂把喷漆线改为机器人操作。"},{"word":"robotization","structure":"robotize plus the action noun ending","meaning":"the process of converting to robots","meaningCN":"改用机器人的过程","example":"Robotization reduced exposure to paint fumes.","exampleCN":"机器人化减少了接触油漆气体的机会。"}],"latinEntries":[],"derivatives":[{"word":"robot","pos":"n.","zh":"源自捷克语「苦役」，义为「机器人」"},{"word":"robotic","pos":"adj.","zh":"由「机器人」加形容词尾构成，义为「机器人的、机械的」"},{"word":"robotically","pos":"adv.","zh":"由「机器人的」加副词词尾构成，义为「以机械方式」"},{"word":"robotize","pos":"v.","zh":"由「机器人」加动词词尾构成，义为「使机器人化」"},{"word":"robotization","pos":"n.","zh":"由该动词加动作名词尾构成，义为「机器人化」"}]}},{"word":"robotic","ipa_uk":"/rəʊˈbɒtɪk/","ipa_us":"/roʊˈbɑːtɪk/","definition_zh":"机器人的；机器人般的；机械呆板的","definition_en":"relating to robots, or behaving like a robot in a stiff, mechanical way","core_image":"一只机械手在流水线上精准地重复同一个动作，动作之间没有停顿，也没有表情","scene":"手术台旁，机械臂在医生指令下稳定地完成缝合，手部抖动比人手小得多。Robotic surgery allows movements too steady for a human hand.","sceneCN":"这里指由机器人完成的、与机器人相关的（第 3 个义项：机器人技术的）；句意：机器人手术能完成人手难以保持的稳定动作。","pos":[{"tag":"adj.","zh":"机器人的；机械呆板的；自动化的"}],"collocations":[{"phrase":"robotic arm","zh":"机械臂"},{"phrase":"robotic surgery","zh":"机器人手术"},{"phrase":"robotic system","zh":"机器人系统"},{"phrase":"robotic device","zh":"机器人设备"},{"phrase":"robotic voice","zh":"机械般的嗓音"},{"phrase":"robotic movement","zh":"机械般的动作"}],"forms":[{"label":"原级","form":"robotic"},{"label":"比较级","form":"more robotic"},{"label":"最高级","form":"most robotic"},{"label":"副词","form":"robotically"},{"label":"名词（学科）","form":"robotics"},{"label":"名词（机器）","form":"robot"}],"derivatives":[{"word":"robot","pos":"n.","zh":"源自捷克语「苦役」，义为「机器人」"},{"word":"robotics","pos":"n.","zh":"由「机器人」加希腊语学科词尾构成，义为「机器人技术」"},{"word":"robotically","pos":"adv.","zh":"由该形容词加副词词尾构成，义为「以机械方式」"},{"word":"robotize","pos":"v.","zh":"由「机器人」加动词词尾构成，义为「使机器人化」"},{"word":"robotization","pos":"n.","zh":"由该动词加动作名词尾构成，义为「机器人化」"}],"senses":[{"no":"01","title":"Belonging to a robot","titleCN":"属于机器人的","definition":"describing a part, tool or action that belongs to or is performed by a robot","definitionCN":"指属于机器人或由机器人执行的部件、工具或动作","example":"The robotic hand picked up the egg without breaking it.","exampleCN":"机械手拿起鸡蛋而没有弄破。","why":"The adjective simply marks possession or origin, the most literal relation to the noun robot.","whyCN":"这个形容词只标记所属或来源，是与「机器人」最字面的关系。"},{"no":"02","title":"Stiff like a machine","titleCN":"像机器一样僵硬","definition":"describing movements or manner that are stiff, regular and without natural variation","definitionCN":"指僵硬、规律、缺乏自然变化的动作或举止","example":"His robotic walk made the audience laugh.","exampleCN":"他机械般的走路姿势让观众笑了。","why":"When a person moves like a machine, the adjective transfers from origin to resemblance.","whyCN":"当一个人像机器那样动作，这个形容词就从「来源」转向「相似」。"},{"no":"03","title":"Relating to robot technology","titleCN":"与机器人技术有关的","definition":"describing methods or equipment that use robot technology in another field","definitionCN":"指在另一领域使用机器人技术的方法或设备","example":"Robotic surgery shortens recovery for many patients.","exampleCN":"机器人手术缩短了许多患者的恢复时间。","why":"A technique performed through a robot is labelled by the adjective rather than the field noun.","whyCN":"通过机器人实施的技术用这个形容词标注，而不是用领域名词。"},{"no":"04","title":"Automated mechanical equipment","titleCN":"自动化的机械装置","definition":"describing a machine that acts on its own according to a program","definitionCN":"指按程序自行动作的机械","example":"A robotic vacuum maps the room before it cleans.","exampleCN":"自动吸尘器先绘制房间地图再清扫。","why":"Consumer machines that act by themselves borrow the adjective even when they barely resemble a robot.","whyCN":"自行动作的消费机器即使不太像机器人，也借用了这个形容词。"},{"no":"05","title":"Without expression or feeling","titleCN":"无表情、无感情","definition":"describing a voice or face that shows no emotion","definitionCN":"指不显露情感的声音或面孔","example":"The announcement was read in a robotic voice.","exampleCN":"通告用一个机械般的声音宣读。","why":"A machine has no inner state to show, so absence of feeling is read as machine-likeness.","whyCN":"机器没有可显露的内心状态，因此「没有感情」被读作「像机器」。"},{"no":"06","title":"Repeated without thought","titleCN":"不加思考地重复","definition":"describing behaviour carried out by routine with no adaptation","definitionCN":"指按惯例执行、毫无变通的行为","example":"The staff gave robotic answers to every complaint.","exampleCN":"员工对每个投诉都给出机械的答复。","why":"Repetition without adjustment copies a program, so the adjective describes habitual emptiness.","whyCN":"不加调整的重复复制了程序，因此这个形容词描述习惯性的空洞。"},{"no":"07","title":"Made by a robot","titleCN":"由机器人制造的","definition":"describing a product assembled or handled by robots","definitionCN":"指由机器人组装或处理的产品","example":"The robotic assembly line runs with almost no lights.","exampleCN":"这条机器人装配线几乎不用开灯就能运行。","why":"Origin can describe the maker as well as the made thing, giving this production sense.","whyCN":"来源既可描述制作者，也可描述制成品，于是有了这一生产义。"},{"no":"08","title":"Precise beyond human steadiness","titleCN":"精准得超过人手","definition":"describing accuracy so regular that it seems machine-controlled","definitionCN":"指精准得如此规律，仿佛由机器控制","example":"Her robotic consistency at the free-throw line impressed the coach.","exampleCN":"她在罚球线上机器般的稳定性让教练印象深刻。","why":"When human precision reaches machine regularity, resemblance becomes praise rather than criticism.","whyCN":"当人的精准达到机器的规律性，相似便成了赞美而非批评。"}],"etymology":{"intro":{"en":"Robotic is robot plus the adjective ending -ic; robot came from Czech robota, forced labour, through a 1920 play.","cn":"这个词由「机器人」加形容词词尾构成；「机器人」经 1920 年一部戏剧来自捷克语「苦役」。"},"items":[{"era":"CZECH ROBOTA","en":"Robota named forced labour, and the word carried the idea of work done without choice.","cn":"这个词指苦役，带着「无从选择地劳动」的观念。"},{"era":"CAPEK 1920","en":"The play used robot for artificial workers, and translations spread the noun across Europe and America.","cn":"该剧用这个词指人造劳动者，译本把名词传遍欧美。"},{"era":"ENGLISH ROBOT","en":"English adopted the noun in the 1920s, first for human-like machines and later for any programmable machine.","cn":"英语在二十世纪二十年代接受这个名词，先指人形机器，后指任何可编程机器。"},{"era":"ADJECTIVE ROBOTIC","en":"The adjective was formed with the ordinary English ending -ic, meaning relating to or resembling.","cn":"这个形容词用普通英语词尾构成，意为「与……有关的」或「像……的」。"},{"era":"EXTENDED MEANING","en":"As machines entered daily life, the adjective came to describe stiff human behaviour and unfeeling voices.","cn":"随着机器进入日常生活，这个形容词开始描述僵硬的人类举止与无情的声音。"},{"era":"FIRST RECORD UNCERTAIN","en":"The first recorded use of the adjective is not established; the noun is well dated, but the derived adjective has no firm first citation.","cn":"这个形容词的首见没有确证；名词的年代清楚，但派生形容词没有可靠的首次引用。"}]},"similar":{"note":{"en":"The first group shares the robot stem; the second group describes machine-like qualities with other words.","cn":"第一组共享「机器人」词干；第二组用其他词描述类似机器的性质。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"robot","ipa":"/ˈrəʊbɒt/","tag":"base noun","definition":"The machine itself; the adjective describes what belongs to or resembles it.","definitionCN":"机器本身；形容词描述属于它或像它的事物。"},{"word":"robotics","ipa":"/rəʊˈbɒtɪks/","tag":"field noun","definition":"The discipline of designing and using robots; the adjective does not name a field.","definitionCN":"设计与使用机器人的学科；形容词并不命名学科。"},{"word":"robotically","ipa":"/rəʊˈbɒtɪkli/","tag":"adverb","definition":"In a machine-like way; it modifies an action rather than a noun.","definitionCN":"以类似机器的方式；修饰动作而非名词。"},{"word":"robotize","ipa":"/ˈrəʊbətaɪz/","tag":"verb","definition":"To make a process robotic; the verb names the change.","definitionCN":"使流程机器人化；动词命名这一改变。"}]},{"heading":"NEAR MEANING","entries":[{"word":"mechanical","ipa":"/mɪˈkænɪkl/","tag":"quality adjective","definition":"Acting like a mechanism; it stresses repetition and lack of thought without naming robots.","definitionCN":"像机械那样运作；强调重复与缺乏思考，不点明机器人。"},{"word":"automatic","ipa":"/ˌɔːtəˈmætɪk/","tag":"function adjective","definition":"Working by itself; it stresses self-operation rather than resemblance to a robot.","definitionCN":"自行工作的；强调自行运作，而非与机器人相似。"},{"word":"stiff","ipa":"/stɪf/","tag":"manner adjective","definition":"Rigid and awkward in movement; the plain physical word behind the figurative sense.","definitionCN":"动作僵硬笨拙；是这一比喻义背后的平实物理词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Czech root, the play and the real adjective family.","cn":"正常联想：捷克词根、那部戏剧与真实形容词词族。"},"normal":[{"en":"Robot plus -ic: of or like a robot.","cn":"「机器人」加形容词词尾：属于机器人或像机器人。"},{"en":"The family runs robot, robotic, robotically, robotics and robotize.","cn":"同族词有机器人、机器人的、以机械方式、机器人技术与使机器人化。"},{"en":"Fixed phrases mark the machine: robotic arm, robotic system, robotic device.","cn":"固定搭配标出机器：机械臂、机器人系统、机器人设备。"},{"en":"Fixed phrases mark the manner: robotic voice, robotic movement.","cn":"固定搭配标出举止：机械般的嗓音、机械般的动作。"},{"en":"The word for forced labour became the word for a machine that never tires.","cn":"表示苦役的词，变成了永不疲倦的机器的名字。"}],"abstract":[{"en":"Picture a smile that appears on time but never reaches the eyes.","cn":"想象一个按时出现的微笑，却从不抵达眼睛。"},{"en":"Picture a dancer who repeats every step perfectly but never listens to the music.","cn":"想象一位舞者每一步都完美重复，却从不听音乐。"},{"en":"Picture a hand that can hold an egg or a hammer with the same pressure.","cn":"想象一只手拿鸡蛋和拿锤子都用同样的力气。"}]},"examples":[{"en":"The robotic arm welds the same joint two hundred times a day.","cn":"机械臂每天焊接同一个接头两百次。"},{"en":"His robotic tone made the apology sound rehearsed.","cn":"他机械般的语调让道歉听起来像背稿。"},{"en":"Robotic helpers now deliver meals inside the hospital.","cn":"机器人助手如今在医院内送餐。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「机器人」+「的」——像机器人那样精准，也像机器人那样僵硬","word":"robotic"},"root":"「机器人」（捷克语「苦役」，1920 年经戏剧进入英语）加形容词词尾。","sensesIntro":{"en":"Eight senses move from belonging to a robot, through stiffness, technology, automation, blankness, routine, machine production and superhuman steadiness.","cn":"八个义项从「属于机器人」出发，依次经过僵硬、技术、自动化、空白、惯例、机器生产与超常稳定。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand that repeats one motion with perfect regularity and no expression.","cn":"核心意象：一只手以完美的规律重复同一个动作，毫无表情。"},"chain":["ROBOT","MACHINE BODY","PRECISE MOTION","NO EXPRESSION","AUTOMATIC TASK","HUMAN-LIKE STIFFNESS"],"branches":[{"senses":"01 · 07","en":"ORIGIN: parts and products that belong to or are made by robots.","cn":"来源：属于机器人或由机器人制造的部件与产品。"},{"senses":"02 · 05 · 06","en":"RESEMBLANCE IN PEOPLE: stiff movement, a blank voice, and answers repeated without thought.","cn":"人的相似：僵硬的动作、空白的声音，以及不加思考重复的答复。"},{"senses":"03","en":"TECHNOLOGY IN ANOTHER FIELD: surgery and other work done through a robot.","cn":"另一领域中的技术：通过机器人完成的手术等工作。"},{"senses":"04","en":"SELF-ACTING EQUIPMENT: consumer and industrial machines that run by program.","cn":"自行运作的设备：按程序运行的消费与工业机器。"},{"senses":"08","en":"PRAISE BY RESEMBLANCE: precision so regular that it seems machine-controlled.","cn":"以相似为赞美：精准得仿佛由机器控制。"}]},"affixes":{"intro":{"en":"Robotic is a Czech-derived noun with a Greek adjective ending; the ending is shared with a large family of English adjectives.","cn":"这个词以捷克语为词干，配希腊语形容词词尾；该词尾与一大批英语形容词共享。"},"latinIntro":{"en":"The root is Czech and the ending is Greek, so no Latin cognate of the root is listed.","cn":"词根来自捷克语，词尾来自希腊语，因此不列出该词根的拉丁同族词。"},"items":[{"word":"robota","structure":"Czech noun","meaning":"forced labour","meaningCN":"苦役；强制劳动","example":"The root supplies the idea of work without choice.","exampleCN":"词根提供「无从选择的工作」这一观念。"},{"word":"robot","structure":"Czech coinage from a 1920 play","meaning":"an artificial worker","meaningCN":"人造劳动者","example":"The noun entered English in the 1920s.","exampleCN":"这个名词在二十世纪二十年代进入英语。"},{"word":"-ic","structure":"adjective ending of Greek origin","meaning":"relating to; resembling","meaningCN":"与……有关的；像……的","example":"The ending turns the machine noun into a describing word.","exampleCN":"这个词尾把机器名词变成描述性词语。"},{"word":"robotic","structure":"robot plus -ic","meaning":"of or like a robot","meaningCN":"属于机器人或像机器人的","example":"The adjective covers both belonging and resemblance.","exampleCN":"这个形容词同时涵盖「所属」与「相似」。"},{"word":"-ally","structure":"adverb ending","meaning":"in the stated manner","meaningCN":"以所述方式","example":"The adverb robotically marks how an action is performed.","exampleCN":"相应的副词标记动作的执行方式。"},{"word":"-ics","structure":"Greek subject ending","meaning":"a field of study","meaningCN":"研究领域","example":"The sibling noun names the discipline, not the quality.","exampleCN":"同源的学科名词命名领域，而不是性质。"},{"word":"-ize","structure":"verb-forming ending","meaning":"to make or become","meaningCN":"使成为；变成","example":"The verb means to convert a process to robots.","exampleCN":"这个动词意为把流程改为机器人操作。"},{"word":"robotics","structure":"robot plus -ics","meaning":"the field of robots","meaningCN":"机器人领域","example":"The field noun is related but not interchangeable with the adjective.","exampleCN":"这个领域名词虽相关，却不能与形容词互换。"}],"latinEntries":[],"derivatives":[{"word":"robot","pos":"n.","zh":"源自捷克语「苦役」，义为「机器人」"},{"word":"robotics","pos":"n.","zh":"由「机器人」加希腊语学科词尾构成，义为「机器人技术」"},{"word":"robotically","pos":"adv.","zh":"由该形容词加副词词尾构成，义为「以机械方式」"},{"word":"robotize","pos":"v.","zh":"由「机器人」加动词词尾构成，义为「使机器人化」"},{"word":"robotization","pos":"n.","zh":"由该动词加动作名词尾构成，义为「机器人化」"}]}}]);
